INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C36','kor',5,2,'u6',11,'연극을 하는 까닭 — 대사를 틀리지 않고 외워 보여 주기보다 작품을 깊이 감상한 것을 인물의 마음이 드러나게 표현하는 것이 중요하다',ARRAY['6국05-04 문학']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C37','kor',5,2,'u6',11,'협력하고 되돌아보기 — 여럿이 협력해 맡은 역할에 책임을 다하고, 목소리·몸짓·협력을 기준으로 잘한 점부터 나눈다',ARRAY['6국05-04 문학']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C38','kor',5,2,'u6',13,'감상 질문 — 답이 하나로 정해져 있지 않고 인물의 마음, 사건의 의미, 배경의 영향을 깊이 생각하게 하는 질문',ARRAY['6국05-03 문학']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C39','kor',5,2,'u6',13,'구성 요소로 감상 질문 만들기 — 인물, 사건, 배경을 하나씩 떠올리며 「왜?」, 「어떤 의미일까?」로 묻는다',ARRAY['6국05-03 문학']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C40','kor',5,2,'u6',13,'묻고 답하며 감상 나누기 — 근거를 들어 답하고 다른 생각도 끝까지 들으며, 나누기 전과 뒤에 달라진 내 감상을 살핀다',ARRAY['6국02-05 읽기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C41','kor',5,2,'u6',13,'함께 할 감상 활동 정하기 — 구성 요소를 생각하며 감상하는 활동을 고르고 반 전체·모둠·짝·혼자 가운데 방법을 모두의 의견으로 정한다',ARRAY['6국02-05 읽기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C42','kor',5,2,'u6',15,'높임 어휘로 직접 높이기 — 웃어른을 직접 높일 때 높임 어휘가 있으면 그것을 먼저 쓴다 — 계시다 · 편찮으시다 (기초 다지기)',ARRAY['기초 다지기(높임 표현)']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C43','kor',5,2,'u6',15,'있으시다 — 웃어른과 밀접한 대상(말씀 · 고민 · 생각)을 높일 때에는 「계시다」가 아니라 「있으시다」를 쓴다 (기초 다지기)',ARRAY['기초 다지기(높임 표현)']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X01','kor',5,'u6',ARRAY['K5-2-u6-C1']::text[],'작품을 감상한다는 것을 줄거리를 아는 것으로만 여긴다','때·곳·인물까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X02','kor',5,'u6',ARRAY['K5-2-u6-C2']::text[],'이야기를 소개할 때 주인공 이름과 줄거리만 쓰면 충분하다고 여기거나 내용과 관계없는 것을 담는다','성격·때·곳도 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X03','kor',5,'u6',ARRAY['K5-2-u6-C3']::text[],'인형극은 사람 배우가 없으니 등장인물이나 극본이 없다고 여긴다','인형도 인물을 맡아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X04','kor',5,'u6',ARRAY['K5-2-u6-C4']::text[],'단원에서 배우는 차례를 섞거나 배울 내용과 하는 일을 엇갈리게 잇는다','이야기 → 극본 → 연극') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X05','kor',5,'u6',ARRAY['K5-2-u6-C5']::text[],'인물은 사람만 될 수 있다고 여기거나 인물을 때·곳·일과 헷갈린다','일을 겪는 사람이나 사물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X06','kor',5,'u6',ARRAY['K5-2-u6-C6']::text[],'사건을 인물이나 배경과 헷갈리거나 일어난 일을 차례 없이 늘어놓는다','일어나는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X07','kor',5,'u6',ARRAY['K5-2-u6-C7']::text[],'배경을 장소만으로 여겨 시간이나 사회적 상황은 배경이 아니라고 여긴다','시간·장소·사회적 상황') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X08','kor',5,'u6',ARRAY['K5-2-u6-C8']::text[],'시대적 배경을 묻는데 장소를 고르거나 때를 알려 주는 말을 찾지 못한다','언제 · 어떤 시대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X09','kor',5,'u6',ARRAY['K5-2-u6-C9']::text[],'공간적 배경을 묻는데 때나 시대를 고른다','어디에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X10','kor',5,'u6',ARRAY['K5-2-u6-C10']::text[],'말과 행동을 살피지 않고 근거 없이 인물의 성격을 정한다','말과 행동이 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X11','kor',5,'u6',ARRAY['K5-2-u6-C11']::text[],'배경은 이야기의 장식일 뿐이라 사건이나 인물의 마음과 관계없다고 여긴다','배경이 사건을 만들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X12','kor',5,'u6',ARRAY['K5-2-u6-C12']::text[],'구성 요소를 따지는 것은 외우기일 뿐 이야기를 이해하는 데 도움이 되지 않는다고 여기거나 구성 요소를 잘못 모은다','흐름과 의미가 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X13','kor',5,'u6',ARRAY['K5-2-u6-C13']::text[],'인물의 마음이 처음부터 끝까지 같다고 여기거나 마음의 변화를 차례 없이 늘어놓는다','사건마다 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X14','kor',5,'u6',ARRAY['K5-2-u6-C14']::text[],'배경, 사건, 인물의 마음을 따로따로만 보고 서로 이어진 관계를 살피지 않는다','배경 → 사건 → 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X15','kor',5,'u6',ARRAY['K5-2-u6-C15']::text[],'인물의 말만 보고 마음을 판단해 행동에 담긴 마음을 놓친다','행동도 함께 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X16','kor',5,'u6',ARRAY['K5-2-u6-C16']::text[],'모르는 낱말을 그냥 지나치거나 사전 뜻을 베끼기만 하고 문장에 넣어 확인하지 않는다','짐작 → 사전 → 넣어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X17','kor',5,'u6',ARRAY['K5-2-u6-C17']::text[],'이야기 속 낱말의 뜻을 앞뒤 문장과 반대로 짐작한다','앞뒤 문장을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X18','kor',5,'u6',ARRAY['K5-2-u6-C18']::text[],'인상 깊은 장면은 하나로 정해져 있다고 여기거나 까닭 없이 장면만 고른다','사람마다 · 까닭과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X19','kor',5,'u6',ARRAY['K5-2-u6-C19']::text[],'인물에게 편지를 쓸 때 인물의 처지나 마음은 헤아리지 않고 줄거리만 옮기거나 꾸짖기만 한다','겪은 일과 마음을 헤아려') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X20','kor',5,'u6',ARRAY['K5-2-u6-C20']::text[],'극본을 혼자 줄글로 읽으려고 쓴 글로 여긴다','연극을 하려고 쓴 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X21','kor',5,'u6',ARRAY['K5-2-u6-C21']::text[],'해설을 보면 인물의 감정을 알 수 있다고 여기거나 해설을 대사·지문과 헷갈린다','때·곳·인물·무대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X22','kor',5,'u6',ARRAY['K5-2-u6-C22']::text[],'인물이 직접 하는 말(대사)을 해설이나 지문과 헷갈린다','인물이 직접 하는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X23','kor',5,'u6',ARRAY['K5-2-u6-C23']::text[],'괄호 안의 지문도 배우가 소리 내어 말하는 대사라고 여기거나 지문을 해설과 헷갈린다','몸과 목소리로 표현') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X24','kor',5,'u6',ARRAY['K5-2-u6-C24']::text[],'이야기 글과 극본의 쓰는 방법과 목적을 헷갈려 극본에도 인물의 말을 줄글로 이어 쓴다','대사와 지문으로 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X25','kor',5,'u6',ARRAY['K5-2-u6-C25']::text[],'극본을 낭독할 때 지문을 살피지 않고 모든 대사를 같은 목소리로 읽거나 해설을 빼고 읽는다','지문대로 목소리를') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X26','kor',5,'u6',ARRAY['K5-2-u6-C26']::text[],'극본을 읽을 때 무대 위 장면은 떠올리지 않고 글자만 따라 읽는다','장면을 상상해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X27','kor',5,'u6',ARRAY['K5-2-u6-C27']::text[],'극본은 대사만 따라 읽으면 내용을 다 알 수 있다고 여긴다','해설·대사·지문 이어서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X28','kor',5,'u6',ARRAY['K5-2-u6-C28']::text[],'인물 관계도에 관계를 잘못 잇거나 관계가 바뀌는 모습을 놓친다','어떤 사이인지 자세히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X29','kor',5,'u6',ARRAY['K5-2-u6-C29']::text[],'사건을 일어난 차례와 다르게 늘어놓거나 흐름을 바꾼 사건을 찾지 못한다','일어난 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X30','kor',5,'u6',ARRAY['K5-2-u6-C30']::text[],'역할 수행 학습의 차례를 섞어 준비 없이 실연부터 하거나 평가를 빼놓는다','설정 → 연습 → 실연 → 평가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X31','kor',5,'u6',ARRAY['K5-2-u6-C31']::text[],'맡은 인물의 대사를 외우기만 하고 인물이 왜 그렇게 말했는지는 묻지 않는다','왜 그렇게 말했을까') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X32','kor',5,'u6',ARRAY['K5-2-u6-C32']::text[],'인상적인 부분을 말할 때 극본 속 근거나 까닭 없이 「재미있다」로만 말하거나 내 까닭만 맞다고 우긴다','근거와 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X33','kor',5,'u6',ARRAY['K5-2-u6-C33']::text[],'인물의 특징을 살피지 않고 역할부터 정하거나 연극 준비의 차례를 뒤섞는다','인물 특징부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X34','kor',5,'u6',ARRAY['K5-2-u6-C34']::text[],'같은 대사는 인물이나 상황이 달라도 늘 같은 목소리로 표현하면 된다고 여긴다','성격·지문·마음 따라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X35','kor',5,'u6',ARRAY['K5-2-u6-C35']::text[],'연극하기 전에 소품이나 등장 순서를 점검하지 않거나 점검과 관계없는 것을 챙긴다','소품 · 순서 · 흐름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X36','kor',5,'u6',ARRAY['K5-2-u6-C36']::text[],'연극은 대사를 하나도 틀리지 않고 외워서 보여 주는 것이 가장 중요하다고 여긴다','감상한 것을 표현') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X37','kor',5,'u6',ARRAY['K5-2-u6-C37']::text[],'연극을 되돌아볼 때 아쉬운 점만 늘어놓거나 잘하는 친구에게만 역할을 몰아준다','협력 · 잘한 점 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X38','kor',5,'u6',ARRAY['K5-2-u6-C38']::text[],'감상 질문은 이야기에 답이 그대로 쓰여 있는 것을 묻는 것이 좋다고 여긴다','답이 여럿인 질문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X39','kor',5,'u6',ARRAY['K5-2-u6-C39']::text[],'감상 질문을 만들 때 인물·사건·배경 가운데 어느 요소에 대한 질문인지 가르지 못한다','인물 · 사건 · 배경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X40','kor',5,'u6',ARRAY['K5-2-u6-C40']::text[],'감상을 나눌 때 내 답만 맞다고 우기거나 근거 없이 느낌만 말한다','근거 · 끝까지 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X41','kor',5,'u6',ARRAY['K5-2-u6-C41']::text[],'함께 할 활동을 목소리 큰 친구의 뜻대로만 정하거나 감상과 관계없는 활동을 고른다','모두의 의견으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X42','kor',5,'u6',ARRAY['K5-2-u6-C42']::text[],'웃어른을 직접 높일 때 높임 어휘를 두고 「있으시다」, 「아프시다」처럼 쓴다','계시다 · 편찮으시다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u6-X43','kor',5,'u6',ARRAY['K5-2-u6-C43']::text[],'웃어른과 관련된 말이면 말씀이나 고민에도 「계시다」를 쓴다','말씀 · 고민엔 있으시다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#1','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C1',1,'mc','auto','책 소개 메모에 쓰여 있는 내용은 어느 것인가요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":1,"concept":"K5-2-u6-C1","difficulty":1,"kind":"mc","stem":"책 소개 메모에 쓰여 있는 내용은 어느 것인가요?","options":[{"t":"주인공 바다는 등대섬에 산다","correct":true},{"t":"바다는 겁이 많은 아이이다","mis":"K5-2-u6-X02"},{"t":"이야기는 겨울에 펼쳐진다","mis":"K5-2-u6-X02"},{"t":"바다는 할아버지의 손녀이다","mis":"K5-2-u6-X02"}],"explanation":["메모에 성격은 없어요.","메모에 계절은 없어요.","주인공과 사는 곳은 쓰여 있어요."],"asset":{"type":"passage","lines":["책 제목: 「등대섬의 여름」","주인공: 등대섬에 사는 소녀 바다","줄거리: 바다는 폭풍이 몰아치는 밤, 등대지기 할아버지를 도와 등대 불을 지킨다.","소개하고 싶은 까닭: 마지막 장면이 오래 기억에 남는다."],"title":"책 소개 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#2','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C2',1,'mc','auto','책 소개 메모에 더 담으면 이야기를 깊이 알 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":2,"concept":"K5-2-u6-C2","difficulty":1,"kind":"mc","stem":"책 소개 메모에 더 담으면 이야기를 깊이 알 수 있는 것은 어느 것인가요?","options":[{"t":"이야기가 언제, 어디에서 펼쳐지는지","correct":true},{"t":"책이 모두 몇 쪽인지","mis":"K5-2-u6-X02"},{"t":"책값이 얼마인지","mis":"K5-2-u6-X02"},{"t":"책 표지가 무슨 색인지","mis":"K5-2-u6-X02"}],"explanation":["내용과 거리가 멀어요.","내용과 거리가 멀어요.","때와 곳을 알면 흐름이 보여요."],"asset":{"type":"passage","lines":["책 제목: 「등대섬의 여름」","주인공: 등대섬에 사는 소녀 바다","줄거리: 바다는 폭풍이 몰아치는 밤, 등대지기 할아버지를 도와 등대 불을 지킨다.","소개하고 싶은 까닭: 마지막 장면이 오래 기억에 남는다."],"title":"책 소개 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#3','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C3',1,'ox','auto','연극과 인형극에는 모두 등장인물과 무대가 있어요.',ARRAY['K5-2-u6-X03']::text[],false,'{"seq":3,"concept":"K5-2-u6-C3","difficulty":1,"kind":"ox","stem":"연극과 인형극에는 모두 등장인물과 무대가 있어요.","answer":"O","reason_options":[{"t":"인형극에서는 인형이 인물을 맡을 뿐 등장인물과 무대가 있기 때문에","correct":true},{"t":"인형극에는 사람 배우가 없어 등장인물이 없기 때문에","mis":"K5-2-u6-X03"}],"mis":"K5-2-u6-X03","explanation":["인형도 인물을 맡아요.","둘 다 무대가 있어요.","둘의 같은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#4','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C3',1,'mc','auto','연극이나 인형극을 공연하려면 무대에서 인물이 할 말과 움직임을 적어 둔 글이 있어야 해요. 이 글은 어느 것인가요?',ARRAY['K5-2-u6-X03']::text[],false,'{"seq":4,"concept":"K5-2-u6-C3","difficulty":1,"kind":"mc","stem":"연극이나 인형극을 공연하려면 무대에서 인물이 할 말과 움직임을 적어 둔 글이 있어야 해요. 이 글은 어느 것인가요?","options":[{"t":"극본","correct":true},{"t":"일기","mis":"K5-2-u6-X03"},{"t":"설명서","mis":"K5-2-u6-X03"},{"t":"신문 기사","mis":"K5-2-u6-X03"}],"explanation":["하루를 적은 글이에요.","쓰는 법을 알려 줘요.","공연을 하려고 쓴 글이 극본이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#5','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C1',2,'mc','auto','작품을 깊이 있게 감상하는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X01']::text[],false,'{"seq":5,"concept":"K5-2-u6-C1","difficulty":2,"kind":"mc","stem":"작품을 깊이 있게 감상하는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"인물이 언제, 어디에서, 어떤 일을 겪으며 마음이 어떻게 바뀌는지 살핀다","correct":true},{"t":"줄거리를 한 줄로 외워 둔다","mis":"K5-2-u6-X01"},{"t":"주인공 이름만 기억한다","mis":"K5-2-u6-X01"},{"t":"책을 빨리 다 읽은 것을 자랑한다","mis":"K5-2-u6-X01"}],"explanation":["줄거리만으로는 부족해요.","이름만으로는 부족해요.","때·곳·일·마음을 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#6','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C4',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u6-C4","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"이야기의 구성 요소","r":"인물·사건·배경 알기"},{"l":"극본의 구성 요소","r":"해설·대사·지문 알기"},{"l":"연극하기","r":"역할을 맡아 표현하기"}],"mis":"K5-2-u6-X04","explanation":["이야기부터 살펴요.","극본을 이루는 것을 알아요.","배운 것을 연극으로 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#7','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C2',2,'mc','auto','메모에 「바다는 겁이 많지만 할아버지를 끝까지 돕는 아이이다.」를 더하면 무엇을 더 알 수 있나요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":7,"concept":"K5-2-u6-C2","difficulty":2,"kind":"mc","stem":"메모에 「바다는 겁이 많지만 할아버지를 끝까지 돕는 아이이다.」를 더하면 무엇을 더 알 수 있나요?","options":[{"t":"주인공의 성격","correct":true},{"t":"이야기의 제목","mis":"K5-2-u6-X02"},{"t":"책의 쪽수","mis":"K5-2-u6-X02"},{"t":"글쓴이의 이름","mis":"K5-2-u6-X02"}],"explanation":["제목은 이미 있어요.","쪽수와 관계없어요.","어떤 아이인지 알게 돼요."],"asset":{"type":"passage","lines":["책 제목: 「등대섬의 여름」","주인공: 등대섬에 사는 소녀 바다","줄거리: 바다는 폭풍이 몰아치는 밤, 등대지기 할아버지를 도와 등대 불을 지킨다.","소개하고 싶은 까닭: 마지막 장면이 오래 기억에 남는다."],"title":"책 소개 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#8','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C3',2,'error','auto','연극과 인형극에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u6-X03']::text[],false,'{"seq":8,"concept":"K5-2-u6-C3","difficulty":2,"kind":"error","stem":"연극과 인형극에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「인형극에는 사람이 없으니 극본도 필요 없어.」","correct":true,"mis_target":"K5-2-u6-X03"},{"t":"「연극에서는 사람이 인물을 맡아.」","mis":"K5-2-u6-X03"},{"t":"「둘 다 이야기가 펼쳐지는 무대가 있어.」","mis":"K5-2-u6-X03"}],"explanation":["바른 말이에요.","바른 말이에요.","인형극도 극본이 있어야 공연해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#9','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C4',2,'mc','auto','이 단원에서 가장 먼저 배우는 것은 어느 것인가요?',ARRAY['K5-2-u6-X04']::text[],false,'{"seq":9,"concept":"K5-2-u6-C4","difficulty":2,"kind":"mc","stem":"이 단원에서 가장 먼저 배우는 것은 어느 것인가요?","options":[{"t":"이야기의 구성 요소","correct":true},{"t":"연극하기","mis":"K5-2-u6-X04"},{"t":"극본 감상하기","mis":"K5-2-u6-X04"},{"t":"감상 질문 만들기","mis":"K5-2-u6-X04"}],"explanation":["연극은 뒤에서 해요.","극본은 이야기 다음이에요.","이야기를 이루는 것부터 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_basic#10','kor',5,2,'u6','L01','g5_2_kor_u6_L01_basic','lesson_basic','K5-2-u6-C1',3,'mc','auto','친구가 「줄거리를 알았으니 이 책은 다 감상했어.」라고 말했어요. 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X01','K5-2-u6-X03']::text[],false,'{"seq":10,"concept":"K5-2-u6-C1","difficulty":3,"kind":"mc","stem":"친구가 「줄거리를 알았으니 이 책은 다 감상했어.」라고 말했어요. 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「인물이 어떤 아이인지, 일이 언제 어디에서 벌어졌는지도 살피면 더 깊이 감상할 수 있어.」","correct":true},{"t":"「맞아. 줄거리만 알면 충분해.」","mis":"K5-2-u6-X01"},{"t":"「제목만 알아도 감상한 거야.」","mis":"K5-2-u6-X01"},{"t":"「감상은 연극을 볼 때만 하는 거야.」","mis":"K5-2-u6-X03"}],"explanation":["줄거리는 시작일 뿐이에요.","제목만으로는 몰라요.","때·곳·인물까지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#1','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C2',2,'ox','auto','이야기를 소개할 때에는 주인공 이름과 줄거리만 쓰면 충분해요.',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":1,"concept":"K5-2-u6-C2","difficulty":2,"kind":"ox","stem":"이야기를 소개할 때에는 주인공 이름과 줄거리만 쓰면 충분해요.","answer":"X","reason_options":[{"t":"이야기가 언제, 어디에서 펼쳐지는지와 인물의 성격도 담아야 전체 흐름이 보이기 때문에","correct":true},{"t":"줄거리 속에 이야기의 모든 것이 다 들어 있기 때문에","mis":"K5-2-u6-X02"}],"mis":"K5-2-u6-X02","explanation":["더 담을 것이 있어요.","때·곳·성격을 함께 써요.","그래야 깊이 있게 소개돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#2','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C3',2,'mc','auto','연극과 인형극의 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X03']::text[],false,'{"seq":2,"concept":"K5-2-u6-C3","difficulty":2,"kind":"mc","stem":"연극과 인형극의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"연극은 사람이, 인형극은 인형이 인물을 맡는다","correct":true},{"t":"연극에만 무대가 있다","mis":"K5-2-u6-X03"},{"t":"인형극에는 이야기가 없다","mis":"K5-2-u6-X03"},{"t":"연극에만 등장인물이 있다","mis":"K5-2-u6-X03"}],"explanation":["둘 다 무대가 있어요.","인형극에도 이야기가 있어요.","누가 인물을 맡는지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#3','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C2',3,'mc','auto','책 소개 메모를 고쳐 쓴 것 가운데 이야기를 가장 깊이 있게 소개한 것은 어느 것인가요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":3,"concept":"K5-2-u6-C2","difficulty":3,"kind":"mc","stem":"책 소개 메모를 고쳐 쓴 것 가운데 이야기를 가장 깊이 있게 소개한 것은 어느 것인가요?","options":[{"t":"폭풍 치는 여름밤, 외딴 등대섬에서 겁 많던 바다가 할아버지를 도와 등대 불을 지키며 용기를 낸다","correct":true},{"t":"바다가 나온다. 등대가 나온다. 재미있다","mis":"K5-2-u6-X02"},{"t":"이 책은 무척 두껍고 표지가 파랗다","mis":"K5-2-u6-X02"},{"t":"폭풍이 몰아친다","mis":"K5-2-u6-X02"}],"explanation":["흐름이 보이지 않아요.","내용과 관계없어요.","때·곳·인물·일이 함께 담겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#4','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C1',3,'mc','auto','깊이 있게 감상하려고 할 때 스스로에게 던질 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X01']::text[],false,'{"seq":4,"concept":"K5-2-u6-C1","difficulty":3,"kind":"mc","stem":"깊이 있게 감상하려고 할 때 스스로에게 던질 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이 일이 그때 그곳이 아니었다면 인물의 마음은 어땠을까?」","correct":true},{"t":"「이 책은 몇 쪽일까?」","mis":"K5-2-u6-X01"},{"t":"「주인공 이름은 몇 글자일까?」","mis":"K5-2-u6-X01"},{"t":"「누가 가장 빨리 읽었을까?」","mis":"K5-2-u6-X01"}],"explanation":["내용과 관계없어요.","내용과 관계없어요.","때·곳과 마음을 이어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#5','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C4',3,'mc','auto','이 단원에서 배우는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X04']::text[],false,'{"seq":5,"concept":"K5-2-u6-C4","difficulty":3,"kind":"mc","stem":"이 단원에서 배우는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"이야기의 구성 요소 → 극본의 구성 요소 → 연극하기 → 감상 질문 만들기","correct":true},{"t":"연극하기 → 이야기의 구성 요소 → 감상 질문 만들기 → 극본의 구성 요소","mis":"K5-2-u6-X04"},{"t":"감상 질문 만들기 → 연극하기 → 극본의 구성 요소 → 이야기의 구성 요소","mis":"K5-2-u6-X04"},{"t":"극본의 구성 요소 → 감상 질문 만들기 → 이야기의 구성 요소 → 연극하기","mis":"K5-2-u6-X04"}],"explanation":["연극은 뒤에서 해요.","질문은 마지막에 만들어요.","이야기 → 극본 → 연극 → 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#6','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C2',3,'error','auto','책 소개 메모에 무엇을 더 쓸지 친구들이 말했어요. 이야기를 깊이 알리는 데 도움이 되지 않는 것은 어느 것인가요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":6,"concept":"K5-2-u6-C2","difficulty":3,"kind":"error","stem":"책 소개 메모에 무엇을 더 쓸지 친구들이 말했어요. 이야기를 깊이 알리는 데 도움이 되지 않는 것은 어느 것인가요?","options":[{"t":"「책을 산 서점 이름을 쓰자.」","correct":true,"mis_target":"K5-2-u6-X02"},{"t":"「바다가 어떤 아이인지 쓰자.」","mis":"K5-2-u6-X02"},{"t":"「이야기가 펼쳐지는 때와 곳을 쓰자.」","mis":"K5-2-u6-X02"}],"explanation":["성격은 도움이 돼요.","때와 곳은 도움이 돼요.","서점 이름은 이야기와 관계없어요."],"asset":{"type":"passage","lines":["책 제목: 「등대섬의 여름」","주인공: 등대섬에 사는 소녀 바다","줄거리: 바다는 폭풍이 몰아치는 밤, 등대지기 할아버지를 도와 등대 불을 지킨다.","소개하고 싶은 까닭: 마지막 장면이 오래 기억에 남는다."],"title":"책 소개 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#7','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C3',3,'mc','auto','인형극을 공연하려는 모둠에게 꼭 있어야 하는 것은 어느 것인가요?',ARRAY['K5-2-u6-X03']::text[],false,'{"seq":7,"concept":"K5-2-u6-C3","difficulty":3,"kind":"mc","stem":"인형극을 공연하려는 모둠에게 꼭 있어야 하는 것은 어느 것인가요?","options":[{"t":"인물이 할 말과 움직임을 적은 극본","correct":true},{"t":"관객에게 나누어 줄 간식","mis":"K5-2-u6-X03"},{"t":"사람 배우의 의상","mis":"K5-2-u6-X03"},{"t":"공연을 찍을 사진기","mis":"K5-2-u6-X03"}],"explanation":["없어도 공연할 수 있어요.","인형이 인물을 맡아요.","극본이 있어야 공연해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#8','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C2',4,'essay','teacher','재미있게 읽은 이야기 하나를 골라 소개 메모를 쓰세요. 주인공과 줄거리에 더해 인물의 성격과 이야기가 펼쳐지는 때와 곳을 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C2","difficulty":4,"kind":"essay","stem":"재미있게 읽은 이야기 하나를 골라 소개 메모를 쓰세요. 주인공과 줄거리에 더해 인물의 성격과 이야기가 펼쳐지는 때와 곳을 함께 쓰세요.","answer_guide":{"answer":"예: 책 제목 — 「작은 등불」. 주인공 — 산골 마을에 사는 수줍음 많은 아이 하나. 때와 곳 — 눈이 많이 내린 겨울, 길이 끊긴 산골 마을. 줄거리 — 하나는 눈에 갇힌 마을에 약을 전하려고 용기를 내어 이웃 마을까지 길을 낸다. 수줍던 하나가 용기를 내는 장면이 인상 깊어 소개하고 싶다.","scoring_points":["주인공과 줄거리를 썼는가","인물의 성격을 썼는가","때와 곳을 썼는가"]},"explanation":["주인공과 줄거리를 써요.","성격을 더해요.","때와 곳을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#9','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C1',4,'essay','teacher','줄거리만 아는 것과 작품을 깊이 있게 감상하는 것은 어떻게 다른지 「등대섬의 여름」 메모를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u6-C1","difficulty":4,"kind":"essay","stem":"줄거리만 아는 것과 작품을 깊이 있게 감상하는 것은 어떻게 다른지 「등대섬의 여름」 메모를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 줄거리만 알면 바다가 폭풍 치는 밤에 등대 불을 지켰다는 것만 안다. 깊이 있게 감상하면 외딴 섬이라 도움을 청할 곳이 없었다는 것, 바다가 겁이 많은 아이였다는 것까지 살펴 바다가 얼마나 큰 용기를 냈는지 느낄 수 있다.","scoring_points":["줄거리만 아는 모습을 썼는가","깊이 있는 감상의 모습을 썼는가","메모를 예로 들었는가"]},"explanation":["줄거리만 아는 모습이에요.","때·곳·인물까지 살펴요.","예를 들어요."],"asset":{"type":"passage","lines":["책 제목: 「등대섬의 여름」","주인공: 등대섬에 사는 소녀 바다","줄거리: 바다는 폭풍이 몰아치는 밤, 등대지기 할아버지를 도와 등대 불을 지킨다.","소개하고 싶은 까닭: 마지막 장면이 오래 기억에 남는다."],"title":"책 소개 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L01_challenge#10','kor',5,2,'u6','L01','g5_2_kor_u6_L01_challenge','lesson_challenge','K5-2-u6-C3',4,'essay','teacher','연극이나 인형극을 본 경험을 떠올려 등장인물, 무대, 극본이 어떻게 쓰였는지 쓰고, 이 단원에서 알고 싶은 것을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u6-C3","difficulty":4,"kind":"essay","stem":"연극이나 인형극을 본 경험을 떠올려 등장인물, 무대, 극본이 어떻게 쓰였는지 쓰고, 이 단원에서 알고 싶은 것을 한 가지 쓰세요.","answer_guide":{"answer":"예: 도서관에서 「토끼와 거북」 인형극을 보았다. 토끼와 거북 인형이 등장인물이었고, 숲처럼 꾸민 작은 무대가 있었다. 인형을 움직이는 사람들이 극본에 적힌 말을 하며 공연했을 것이다. 이 단원에서는 극본을 직접 읽고 연극으로 표현하는 방법을 알고 싶다.","scoring_points":["경험을 떠올렸는가","등장인물·무대·극본을 썼는가","알고 싶은 것을 썼는가"]},"explanation":["경험을 떠올려요.","셋을 찾아 써요.","알고 싶은 것을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#1','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C5',1,'mc','auto','이야기에서 어떤 일을 겪는 사람이나 사물을 무엇이라고 하나요?',ARRAY['K5-2-u6-X05']::text[],false,'{"seq":1,"concept":"K5-2-u6-C5","difficulty":1,"kind":"mc","stem":"이야기에서 어떤 일을 겪는 사람이나 사물을 무엇이라고 하나요?","options":[{"t":"인물","correct":true},{"t":"사건","mis":"K5-2-u6-X05"},{"t":"배경","mis":"K5-2-u6-X05"},{"t":"해설","mis":"K5-2-u6-X05"}],"explanation":["일어나는 일이에요.","때와 곳이에요.","일을 겪는 사람이나 사물이 인물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#2','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C6',1,'mc','auto','이야기에서 일어나는 일을 무엇이라고 하나요?',ARRAY['K5-2-u6-X06']::text[],false,'{"seq":2,"concept":"K5-2-u6-C6","difficulty":1,"kind":"mc","stem":"이야기에서 일어나는 일을 무엇이라고 하나요?","options":[{"t":"사건","correct":true},{"t":"인물","mis":"K5-2-u6-X06"},{"t":"배경","mis":"K5-2-u6-X06"},{"t":"지문","mis":"K5-2-u6-X06"}],"explanation":["일을 겪는 쪽이에요.","때와 곳이에요.","일어나는 일이 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#3','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C7',1,'mc','auto','이야기가 펼쳐지는 시간과 장소, 사회적 상황을 무엇이라고 하나요?',ARRAY['K5-2-u6-X07']::text[],false,'{"seq":3,"concept":"K5-2-u6-C7","difficulty":1,"kind":"mc","stem":"이야기가 펼쳐지는 시간과 장소, 사회적 상황을 무엇이라고 하나요?","options":[{"t":"배경","correct":true},{"t":"인물","mis":"K5-2-u6-X07"},{"t":"사건","mis":"K5-2-u6-X07"},{"t":"대사","mis":"K5-2-u6-X07"}],"explanation":["일을 겪는 쪽이에요.","일어나는 일이에요.","시간·장소·상황이 배경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#4','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C11',1,'mc','auto','「천막 교실의 반쪽 연필」에서 아이들이 천막에서 공부한 까닭은 무엇인가요?',ARRAY['K5-2-u6-X11']::text[],false,'{"seq":4,"concept":"K5-2-u6-C11","difficulty":1,"kind":"mc","stem":"「천막 교실의 반쪽 연필」에서 아이들이 천막에서 공부한 까닭은 무엇인가요?","options":[{"t":"학교 건물이 다친 군인들을 돌보는 곳이 되어서","correct":true},{"t":"천막이 더 시원해서","mis":"K5-2-u6-X11"},{"t":"산비탈 경치를 보며 공부하려고","mis":"K5-2-u6-X11"},{"t":"선생님이 천막을 좋아하셔서","mis":"K5-2-u6-X11"}],"explanation":["글에 없어요.","글에 없어요.","전쟁이라는 상황이 사건을 만들었어요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#5','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C9',2,'mc','auto','「천막 교실의 반쪽 연필」의 공간적 배경으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X09']::text[],false,'{"seq":5,"concept":"K5-2-u6-C9","difficulty":2,"kind":"mc","stem":"「천막 교실의 반쪽 연필」의 공간적 배경으로 알맞은 것은 어느 것인가요?","options":[{"t":"부산 바닷가 언덕과 산비탈의 천막 교실","correct":true},{"t":"우리나라에 전쟁이 일어났던 때","mis":"K5-2-u6-X09"},{"t":"그해 겨울","mis":"K5-2-u6-X09"},{"t":"받아쓰기 시간","mis":"K5-2-u6-X09"}],"explanation":["때를 알려 줘요.","때를 알려 줘요.","어디에서 일어났는지가 공간적 배경이에요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#6','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C8',2,'mc','auto','「천막 교실의 반쪽 연필」의 시대적 배경으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X08']::text[],false,'{"seq":6,"concept":"K5-2-u6-C8","difficulty":2,"kind":"mc","stem":"「천막 교실의 반쪽 연필」의 시대적 배경으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라에 전쟁이 일어나 피란을 온 때","correct":true},{"t":"부산 바닷가 언덕","mis":"K5-2-u6-X08"},{"t":"사과 상자를 책상 삼은 교실","mis":"K5-2-u6-X08"},{"t":"산비탈에 친 천막","mis":"K5-2-u6-X08"}],"explanation":["곳을 알려 줘요.","곳을 알려 줘요.","어떤 시대·상황인지가 시대적 배경이에요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#7','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C10',2,'mc','auto','「짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.」에서 알 수 있는 순덕이의 성격은 어느 것인가요?',ARRAY['K5-2-u6-X10']::text[],false,'{"seq":7,"concept":"K5-2-u6-C10","difficulty":2,"kind":"mc","stem":"「짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.」에서 알 수 있는 순덕이의 성격은 어느 것인가요?","options":[{"t":"어려울 때 가진 것을 나눌 줄 안다","correct":true},{"t":"욕심이 많다","mis":"K5-2-u6-X10"},{"t":"겁이 많다","mis":"K5-2-u6-X10"},{"t":"남의 일에 관심이 없다","mis":"K5-2-u6-X10"}],"explanation":["행동과 반대예요.","행동과 관계없어요.","하나뿐인 연필을 나눈 행동이 근거예요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#8','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C6',2,'match','auto','「천막 교실의 반쪽 연필」의 구성 요소와 알맞은 내용을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C6","difficulty":2,"kind":"match","stem":"「천막 교실의 반쪽 연필」의 구성 요소와 알맞은 내용을 이으세요.","pairs":[{"l":"인물","r":"나, 순덕, 선생님"},{"l":"사건","r":"순덕이가 연필을 반으로 나누어 주었다"},{"l":"배경","r":"전쟁 무렵 부산의 천막 교실"}],"mis":"K5-2-u6-X06","explanation":["일을 겪는 사람들이에요.","일어난 일이에요.","때와 곳이에요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#9','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C5',2,'ox','auto','이야기에서는 사람만 인물이 될 수 있어요.',ARRAY['K5-2-u6-X05']::text[],false,'{"seq":9,"concept":"K5-2-u6-C5","difficulty":2,"kind":"ox","stem":"이야기에서는 사람만 인물이 될 수 있어요.","answer":"X","reason_options":[{"t":"어떤 일을 겪는 동물이나 사물도 인물이 될 수 있기 때문에","correct":true},{"t":"인물은 사람을 가리키는 말이기 때문에","mis":"K5-2-u6-X05"}],"mis":"K5-2-u6-X05","explanation":["동물도 인물이 돼요.","사물도 인물이 돼요.","일을 겪으면 인물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_basic#10','kor',5,2,'u6','L02','g5_2_kor_u6_L02_basic','lesson_basic','K5-2-u6-C11',3,'mc','auto','「천막 교실의 반쪽 연필」의 배경이 오늘날의 교실이었다면 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X11']::text[],false,'{"seq":10,"concept":"K5-2-u6-C11","difficulty":3,"kind":"mc","stem":"「천막 교실의 반쪽 연필」의 배경이 오늘날의 교실이었다면 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"연필을 쉽게 구할 수 있어 반쪽 연필을 나눈 일이 지금만큼 큰 뜻을 갖지 않았을 것이다","correct":true},{"t":"배경이 바뀌어도 사건과 인물의 마음은 똑같다","mis":"K5-2-u6-X11"},{"t":"배경은 장식이라 아무것도 달라지지 않는다","mis":"K5-2-u6-X11"},{"t":"선생님이 우산을 들고 수업했을 것이다","mis":"K5-2-u6-X11"}],"explanation":["배경이 바뀌면 사건도 바뀌어요.","배경은 장식이 아니에요.","배경이 사건의 뜻을 바꿔요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#1','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C11',2,'ox','auto','배경은 이야기의 장식일 뿐이라 신경 쓰지 않고 읽어도 돼요.',ARRAY['K5-2-u6-X11']::text[],false,'{"seq":1,"concept":"K5-2-u6-C11","difficulty":2,"kind":"ox","stem":"배경은 이야기의 장식일 뿐이라 신경 쓰지 않고 읽어도 돼요.","answer":"X","reason_options":[{"t":"배경은 사건을 만들고 인물의 마음에 영향을 주기 때문에","correct":true},{"t":"사건과 인물만 알면 이야기를 다 알 수 있기 때문에","mis":"K5-2-u6-X11"}],"mis":"K5-2-u6-X11","explanation":["배경도 중요해요.","배경이 사건을 만들어요.","배경을 알면 마음이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#2','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C7',2,'mc','auto','배경에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X07']::text[],false,'{"seq":2,"concept":"K5-2-u6-C7","difficulty":2,"kind":"mc","stem":"배경에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"때와 곳뿐 아니라 그때의 사회적 상황도 배경이다","correct":true},{"t":"배경은 장소만 가리킨다","mis":"K5-2-u6-X07"},{"t":"배경은 날씨만 가리킨다","mis":"K5-2-u6-X07"},{"t":"배경은 인물의 성격을 가리킨다","mis":"K5-2-u6-X07"}],"explanation":["때도 배경이에요.","날씨만이 아니에요.","시간·장소·사회적 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#3','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C10',3,'mc','auto','「선생님은 책임감이 강하다.」라고 짐작한 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X10']::text[],false,'{"seq":3,"concept":"K5-2-u6-C10","difficulty":3,"kind":"mc","stem":"「선생님은 책임감이 강하다.」라고 짐작한 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"비가 오면 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨다","correct":true},{"t":"학교 건물이 다친 군인들을 돌보는 곳이 되었다","mis":"K5-2-u6-X10"},{"t":"아이들이 사과 상자를 책상으로 썼다","mis":"K5-2-u6-X10"},{"t":"그해 겨울 받아쓰기가 있었다","mis":"K5-2-u6-X10"}],"explanation":["배경을 알려 줘요.","아이들의 모습이에요.","선생님의 행동이 근거예요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#4','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C8',3,'error','auto','「천막 교실의 반쪽 연필」의 배경을 나누어 말한 것이에요. 잘못 나눈 것은 어느 것인가요?',ARRAY['K5-2-u6-X09','K5-2-u6-X08']::text[],false,'{"seq":4,"concept":"K5-2-u6-C8","difficulty":3,"kind":"error","stem":"「천막 교실의 반쪽 연필」의 배경을 나누어 말한 것이에요. 잘못 나눈 것은 어느 것인가요?","options":[{"t":"「공간적 배경은 전쟁이 일어났던 때이다.」","correct":true,"mis_target":"K5-2-u6-X09"},{"t":"「시대적 배경은 우리나라에 전쟁이 일어났던 때이다.」","mis":"K5-2-u6-X08"},{"t":"「공간적 배경은 부산 바닷가 언덕과 천막 교실이다.」","mis":"K5-2-u6-X09"}],"explanation":["바르게 나누었어요.","바르게 나누었어요.","때는 시대적 배경이에요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#5','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C12',3,'mc','auto','인물, 사건, 배경을 생각하며 이야기를 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X12']::text[],false,'{"seq":5,"concept":"K5-2-u6-C12","difficulty":3,"kind":"mc","stem":"인물, 사건, 배경을 생각하며 이야기를 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이야기의 전체 흐름과 담긴 의미를 잘 파악할 수 있다","correct":true},{"t":"이야기를 빨리 다 읽을 수 있다","mis":"K5-2-u6-X12"},{"t":"낱말의 뜻을 몰라도 된다","mis":"K5-2-u6-X12"},{"t":"글쓴이의 이름을 알 수 있다","mis":"K5-2-u6-X12"}],"explanation":["빠르기와 관계없어요.","낱말 뜻은 따로 살펴요.","흐름과 의미가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#6','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C5',3,'mc','auto','「낡은 장난감 병정이 밤마다 깨어나 다친 인형을 돌보았어요.」에서 인물로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X05','K5-2-u6-X06']::text[],false,'{"seq":6,"concept":"K5-2-u6-C5","difficulty":3,"kind":"mc","stem":"「낡은 장난감 병정이 밤마다 깨어나 다친 인형을 돌보았어요.」에서 인물로 알맞은 것은 어느 것인가요?","options":[{"t":"장난감 병정과 다친 인형","correct":true},{"t":"밤","mis":"K5-2-u6-X05"},{"t":"사람이 나오지 않으니 인물이 없다","mis":"K5-2-u6-X05"},{"t":"돌보아 준 일","mis":"K5-2-u6-X06"}],"explanation":["때를 알려 줘요.","사물도 인물이 돼요.","일을 겪는 병정과 인형이 인물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#7','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C6',3,'mc','auto','「천막 교실의 반쪽 연필」에서 일어난 사건을 차례대로 늘어놓은 것은 어느 것인가요?',ARRAY['K5-2-u6-X06']::text[],false,'{"seq":7,"concept":"K5-2-u6-C6","difficulty":3,"kind":"mc","stem":"「천막 교실의 반쪽 연필」에서 일어난 사건을 차례대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"천막 교실에서 공부했다 → 연필을 잃고 훌쩍였다 → 순덕이가 연필을 나누어 주었다 → 받아쓰기를 다 맞혔다","correct":true},{"t":"순덕이가 연필을 나누어 주었다 → 천막 교실에서 공부했다 → 받아쓰기를 다 맞혔다 → 연필을 잃고 훌쩍였다","mis":"K5-2-u6-X06"},{"t":"받아쓰기를 다 맞혔다 → 연필을 잃고 훌쩍였다 → 천막 교실에서 공부했다 → 순덕이가 연필을 나누어 주었다","mis":"K5-2-u6-X06"},{"t":"연필을 잃고 훌쩍였다 → 받아쓰기를 다 맞혔다 → 순덕이가 연필을 나누어 주었다 → 천막 교실에서 공부했다","mis":"K5-2-u6-X06"}],"explanation":["차례가 뒤섞였어요.","차례가 뒤섞였어요.","일어난 차례대로 놓았어요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#8','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C7',4,'essay','teacher','「천막 교실의 반쪽 연필」의 인물, 사건, 배경을 찾아 쓰고, 배경을 시대적 배경과 공간적 배경으로 나누어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C7","difficulty":4,"kind":"essay","stem":"「천막 교실의 반쪽 연필」의 인물, 사건, 배경을 찾아 쓰고, 배경을 시대적 배경과 공간적 배경으로 나누어 쓰세요.","answer_guide":{"answer":"예: 인물 — 나, 짝 순덕이, 선생님. 사건 — 천막 교실에서 공부하던 내가 연필을 잃고 울자 순덕이가 연필을 반으로 나누어 주었고, 그해 겨울 나는 받아쓰기를 처음 다 맞혔다. 시대적 배경 — 우리나라에 전쟁이 일어나 피란을 온 때. 공간적 배경 — 부산 바닷가 언덕과 산비탈의 천막 교실.","scoring_points":["인물·사건·배경을 찾았는가","시대적 배경을 썼는가","공간적 배경을 썼는가"]},"explanation":["셋을 찾아요.","때를 써요.","곳을 써요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#9','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C11',4,'essay','teacher','「천막 교실의 반쪽 연필」에서 배경이 사건과 인물의 마음에 어떤 영향을 주었는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u6-C11","difficulty":4,"kind":"essay","stem":"「천막 교실의 반쪽 연필」에서 배경이 사건과 인물의 마음에 어떤 영향을 주었는지 쓰세요.","answer_guide":{"answer":"예: 전쟁 때문에 학교 건물을 쓸 수 없어 아이들은 천막에서 상자를 책상 삼아 공부했다. 물건이 귀한 때라 몽당연필 하나도 무척 소중했고, 그래서 연필을 잃은 내가 울었고 순덕이가 연필을 반으로 나눈 일이 큰 감동을 준다.","scoring_points":["배경을 썼는가","배경이 사건에 준 영향을 썼는가","인물의 마음과 이어 썼는가"]},"explanation":["배경을 찾아요.","사건과 이어요.","마음과 이어요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L02_challenge#10','kor',5,2,'u6','L02','g5_2_kor_u6_L02_challenge','lesson_challenge','K5-2-u6-C10',4,'essay','teacher','「천막 교실의 반쪽 연필」의 인물 가운데 한 명을 골라 그 인물의 말이나 행동을 근거로 성격을 짐작해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u6-C10","difficulty":4,"kind":"essay","stem":"「천막 교실의 반쪽 연필」의 인물 가운데 한 명을 골라 그 인물의 말이나 행동을 근거로 성격을 짐작해 쓰세요.","answer_guide":{"answer":"예: 선생님은 책임감이 강한 분이다. 비가 와서 천막 틈으로 빗물이 떨어져도 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨고, 「공책은 젖어도 배운 것은 젖지 않는단다.」라고 말씀하셨기 때문이다.","scoring_points":["인물을 골랐는가","성격을 짐작했는가","말이나 행동을 근거로 썼는가"]},"explanation":["인물을 골라요.","성격을 써요.","근거를 들어요."],"asset":{"type":"passage","lines":["우리나라에 전쟁이 일어났던 해 봄, 피란 온 우리 가족은 부산 바닷가 언덕에 살았어요.","학교 건물은 다친 군인들을 돌보는 곳이 되어, 우리는 산비탈 천막에서 공부했어요.","책상이 없어 사과 상자를 엎어 놓고 공책을 폈지요.","비가 오면 선생님은 한 손으로 우산을 받쳐 든 채 끝까지 칠판에 글씨를 쓰셨어요.","「공책은 젖어도 배운 것은 젖지 않는단다.」","몽당연필을 잃고 훌쩍이자 짝 순덕이가 제 연필을 반으로 똑 부러뜨려 내밀었어요.","「반쪽이라도 둘이 쓰면 두 자루야.」","그해 겨울, 받아쓰기를 처음 다 맞힌 날 나는 반쪽 연필을 쥐고 집까지 뛰어갔어요."],"title":"천막 교실의 반쪽 연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#1','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C14',1,'mc','auto','아버지가 「내일은 배 못 띄운다.」라고 말한 까닭은 무엇인가요?',ARRAY['K5-2-u6-X15','K5-2-u6-X14']::text[],false,'{"seq":1,"concept":"K5-2-u6-C14","difficulty":1,"kind":"mc","stem":"아버지가 「내일은 배 못 띄운다.」라고 말한 까닭은 무엇인가요?","options":[{"t":"태풍이 올라온다는 소식이 들려서","correct":true},{"t":"도윤이가 대회에 나가는 것이 싫어서","mis":"K5-2-u6-X15"},{"t":"나룻배가 고장 나서","mis":"K5-2-u6-X14"},{"t":"그물을 손질해야 해서","mis":"K5-2-u6-X14"}],"explanation":["글에 없어요.","글에 없어요.","섬이라는 배경과 태풍이 사건을 만들었어요."],"asset":{"type":"passage","lines":["다리가 놓이기 전, 작은 섬 소리섬에서 육지로 가는 배는 아버지의 나룻배뿐이었어요.","도윤이는 육지에서 열리는 어린이 그림 대회에 학교 대표로 뽑혔어요.","대회 전날 밤, 도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.","그런데 라디오에서 태풍이 올라온다는 소식이 흘러나왔어요.","아버지는 묵묵히 그물을 손질하다가 한마디만 했어요. 「내일은 배 못 띄운다.」","「한 해를 기다린 대회란 말이에요!」 도윤이는 방문을 쾅 닫았어요.","이불을 뒤집어쓰자 아버지가 야속해서 눈물이 났어요."],"title":"바람이 잦아든 새벽 (앞)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#2','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C17',1,'mc','auto','「아버지는 묵묵히 그물을 손질하다가」에서 「묵묵히」의 뜻은 어느 것인가요?',ARRAY['K5-2-u6-X17']::text[],false,'{"seq":2,"concept":"K5-2-u6-C17","difficulty":1,"kind":"mc","stem":"「아버지는 묵묵히 그물을 손질하다가」에서 「묵묵히」의 뜻은 어느 것인가요?","options":[{"t":"말없이 잠잠하게","correct":true},{"t":"빠르고 바쁘게","mis":"K5-2-u6-X17"},{"t":"크게 화를 내며","mis":"K5-2-u6-X17"},{"t":"즐겁게 노래하며","mis":"K5-2-u6-X17"}],"explanation":["뜻이 달라요.","뜻이 달라요.","한마디만 한 모습과 맞아요."],"asset":{"type":"passage","lines":["다리가 놓이기 전, 작은 섬 소리섬에서 육지로 가는 배는 아버지의 나룻배뿐이었어요.","도윤이는 육지에서 열리는 어린이 그림 대회에 학교 대표로 뽑혔어요.","대회 전날 밤, 도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.","그런데 라디오에서 태풍이 올라온다는 소식이 흘러나왔어요.","아버지는 묵묵히 그물을 손질하다가 한마디만 했어요. 「내일은 배 못 띄운다.」","「한 해를 기다린 대회란 말이에요!」 도윤이는 방문을 쾅 닫았어요.","이불을 뒤집어쓰자 아버지가 야속해서 눈물이 났어요."],"title":"바람이 잦아든 새벽 (앞)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#3','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C13',1,'mc','auto','대회 전날 밤, 크레파스를 몇 번이나 다시 챙긴 도윤이의 마음은 어느 것인가요?',ARRAY['K5-2-u6-X13']::text[],false,'{"seq":3,"concept":"K5-2-u6-C13","difficulty":1,"kind":"mc","stem":"대회 전날 밤, 크레파스를 몇 번이나 다시 챙긴 도윤이의 마음은 어느 것인가요?","options":[{"t":"설레어 들뜬 마음","correct":true},{"t":"야속한 마음","mis":"K5-2-u6-X13"},{"t":"미안한 마음","mis":"K5-2-u6-X13"},{"t":"지루한 마음","mis":"K5-2-u6-X13"}],"explanation":["나중의 마음이에요.","나중의 마음이에요.","대회를 기다리며 들떴어요."],"asset":{"type":"passage","lines":["다리가 놓이기 전, 작은 섬 소리섬에서 육지로 가는 배는 아버지의 나룻배뿐이었어요.","도윤이는 육지에서 열리는 어린이 그림 대회에 학교 대표로 뽑혔어요.","대회 전날 밤, 도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.","그런데 라디오에서 태풍이 올라온다는 소식이 흘러나왔어요.","아버지는 묵묵히 그물을 손질하다가 한마디만 했어요. 「내일은 배 못 띄운다.」","「한 해를 기다린 대회란 말이에요!」 도윤이는 방문을 쾅 닫았어요.","이불을 뒤집어쓰자 아버지가 야속해서 눈물이 났어요."],"title":"바람이 잦아든 새벽 (앞)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#4','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C15',1,'mc','auto','새벽에 도윤이가 본 아버지의 모습은 어느 것인가요?',ARRAY['K5-2-u6-X15']::text[],false,'{"seq":4,"concept":"K5-2-u6-C15","difficulty":1,"kind":"mc","stem":"새벽에 도윤이가 본 아버지의 모습은 어느 것인가요?","options":[{"t":"흠뻑 젖은 채 나룻배 밧줄을 다시 묶고 있었다","correct":true},{"t":"방에서 코를 골며 자고 있었다","mis":"K5-2-u6-X15"},{"t":"라디오를 듣고 있었다","mis":"K5-2-u6-X15"},{"t":"그물을 팔러 육지에 가 있었다","mis":"K5-2-u6-X15"}],"explanation":["글에 없어요.","글에 없어요.","밤새 배를 지킨 모습이에요."],"asset":{"type":"passage","lines":["밤새 바람이 문풍지를 흔들었어요.","새벽에 나가 보니 아버지가 흠뻑 젖은 채 나룻배 밧줄을 다시 묶고 있었어요.","「배가 떠내려가면 우리 섬은 육지로 갈 길이 없어진단다.」","아버지의 손등에는 밧줄에 쓸린 자국이 벌겋게 나 있었어요.","해가 뜰 무렵, 바람이 거짓말처럼 잦아들었어요. 아버지는 말없이 노를 잡았어요.","「가자. 대회 늦겠다.」","도윤이는 노를 젓는 아버지의 젖은 등을 오래도록 바라보았어요.","그날 도윤이가 그린 그림의 제목은 「새벽 바다의 아버지」였어요."],"title":"바람이 잦아든 새벽 (뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#5','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C17',2,'mc','auto','「바람이 거짓말처럼 잦아들었어요.」에서 「잦아들다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X17']::text[],false,'{"seq":5,"concept":"K5-2-u6-C17","difficulty":2,"kind":"mc","stem":"「바람이 거짓말처럼 잦아들었어요.」에서 「잦아들다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"거센 기운이 차차 가라앉아 가다","correct":true},{"t":"거센 기운이 점점 세지다","mis":"K5-2-u6-X17"},{"t":"갑자기 방향이 바뀌다","mis":"K5-2-u6-X17"},{"t":"소리가 크게 울리다","mis":"K5-2-u6-X17"}],"explanation":["뜻과 반대예요.","뜻이 달라요.","바람이 약해져 배를 띄웠어요."],"asset":{"type":"passage","lines":["밤새 바람이 문풍지를 흔들었어요.","새벽에 나가 보니 아버지가 흠뻑 젖은 채 나룻배 밧줄을 다시 묶고 있었어요.","「배가 떠내려가면 우리 섬은 육지로 갈 길이 없어진단다.」","아버지의 손등에는 밧줄에 쓸린 자국이 벌겋게 나 있었어요.","해가 뜰 무렵, 바람이 거짓말처럼 잦아들었어요. 아버지는 말없이 노를 잡았어요.","「가자. 대회 늦겠다.」","도윤이는 노를 젓는 아버지의 젖은 등을 오래도록 바라보았어요.","그날 도윤이가 그린 그림의 제목은 「새벽 바다의 아버지」였어요."],"title":"바람이 잦아든 새벽 (뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#6','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C13',2,'mc','auto','사건에 따라 바뀐 도윤이의 마음을 차례대로 늘어놓은 것은 어느 것인가요?',ARRAY['K5-2-u6-X13']::text[],false,'{"seq":6,"concept":"K5-2-u6-C13","difficulty":2,"kind":"mc","stem":"사건에 따라 바뀐 도윤이의 마음을 차례대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"들뜬 마음 → 야속한 마음 → 놀라고 미안한 마음 → 고맙고 뭉클한 마음","correct":true},{"t":"야속한 마음 → 들뜬 마음 → 고맙고 뭉클한 마음 → 놀라고 미안한 마음","mis":"K5-2-u6-X13"},{"t":"고맙고 뭉클한 마음 → 놀라고 미안한 마음 → 들뜬 마음 → 야속한 마음","mis":"K5-2-u6-X13"},{"t":"놀라고 미안한 마음 → 야속한 마음 → 들뜬 마음 → 고맙고 뭉클한 마음","mis":"K5-2-u6-X13"}],"explanation":["차례가 뒤섞였어요.","차례가 뒤섞였어요.","사건의 차례를 따라갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#7','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C15',2,'mc','auto','아버지의 마음이 깊다는 것을 가장 잘 짐작하게 하는 것은 어느 것인가요?',ARRAY['K5-2-u6-X15','K5-2-u6-X14']::text[],false,'{"seq":7,"concept":"K5-2-u6-C15","difficulty":2,"kind":"mc","stem":"아버지의 마음이 깊다는 것을 가장 잘 짐작하게 하는 것은 어느 것인가요?","options":[{"t":"바람이 잦아들자 말없이 노를 잡았다","correct":true},{"t":"「내일은 배 못 띄운다.」라고 짧게 말했다","mis":"K5-2-u6-X15"},{"t":"라디오에서 태풍 소식이 나왔다","mis":"K5-2-u6-X14"},{"t":"도윤이가 방문을 쾅 닫았다","mis":"K5-2-u6-X15"}],"explanation":["말만 보면 무뚝뚝해 보여요.","배경이에요.","말없이 노를 잡은 행동에 마음이 담겼어요."],"asset":{"type":"passage","lines":["밤새 바람이 문풍지를 흔들었어요.","새벽에 나가 보니 아버지가 흠뻑 젖은 채 나룻배 밧줄을 다시 묶고 있었어요.","「배가 떠내려가면 우리 섬은 육지로 갈 길이 없어진단다.」","아버지의 손등에는 밧줄에 쓸린 자국이 벌겋게 나 있었어요.","해가 뜰 무렵, 바람이 거짓말처럼 잦아들었어요. 아버지는 말없이 노를 잡았어요.","「가자. 대회 늦겠다.」","도윤이는 노를 젓는 아버지의 젖은 등을 오래도록 바라보았어요.","그날 도윤이가 그린 그림의 제목은 「새벽 바다의 아버지」였어요."],"title":"바람이 잦아든 새벽 (뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#8','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C16',2,'match','auto','모르는 낱말의 뜻을 알아보는 차례를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C16","difficulty":2,"kind":"match","stem":"모르는 낱말의 뜻을 알아보는 차례를 알맞게 이으세요.","pairs":[{"l":"먼저","r":"앞뒤 문장으로 뜻을 짐작한다"},{"l":"그다음","r":"국어사전에서 뜻을 찾아 확인한다"},{"l":"마지막","r":"찾은 뜻을 문장에 넣어 읽어 본다"}],"mis":"K5-2-u6-X16","explanation":["짐작부터 해요.","사전으로 확인해요.","문장에 넣어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#9','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C18',2,'ox','auto','인상 깊은 장면은 사람마다 다를 수 있어요.',ARRAY['K5-2-u6-X18']::text[],false,'{"seq":9,"concept":"K5-2-u6-C18","difficulty":2,"kind":"ox","stem":"인상 깊은 장면은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"저마다 겪은 일과 느낀 점이 달라 마음에 남는 장면도 다르기 때문에","correct":true},{"t":"이야기마다 정해진 인상 깊은 장면이 하나뿐이기 때문에","mis":"K5-2-u6-X18"}],"mis":"K5-2-u6-X18","explanation":["사람마다 달라요.","까닭과 함께 말해요.","서로 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_basic#10','kor',5,2,'u6','L04','g5_2_kor_u6_L04_basic','lesson_basic','K5-2-u6-C14',3,'mc','auto','「바람이 잦아든 새벽」에서 배경, 사건, 인물의 마음이 이어진 모습을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u6-X14']::text[],false,'{"seq":10,"concept":"K5-2-u6-C14","difficulty":3,"kind":"mc","stem":"「바람이 잦아든 새벽」에서 배경, 사건, 인물의 마음이 이어진 모습을 바르게 말한 것은 어느 것인가요?","options":[{"t":"다리 없는 섬에 태풍이 와서 → 배를 못 띄우게 되고 → 도윤이는 아버지가 야속했다","correct":true},{"t":"도윤이가 야속해서 → 태풍이 왔고 → 섬에 다리가 없어졌다","mis":"K5-2-u6-X14"},{"t":"그림 대회가 열려서 → 다리가 놓였고 → 아버지가 기뻐했다","mis":"K5-2-u6-X14"},{"t":"배경과 사건과 마음은 서로 관계가 없다","mis":"K5-2-u6-X14"}],"explanation":["앞뒤가 바뀌었어요.","글과 맞지 않아요.","배경 → 사건 → 마음으로 이어져요."],"asset":{"type":"passage","lines":["다리가 놓이기 전, 작은 섬 소리섬에서 육지로 가는 배는 아버지의 나룻배뿐이었어요.","도윤이는 육지에서 열리는 어린이 그림 대회에 학교 대표로 뽑혔어요.","대회 전날 밤, 도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.","그런데 라디오에서 태풍이 올라온다는 소식이 흘러나왔어요.","아버지는 묵묵히 그물을 손질하다가 한마디만 했어요. 「내일은 배 못 띄운다.」","「한 해를 기다린 대회란 말이에요!」 도윤이는 방문을 쾅 닫았어요.","이불을 뒤집어쓰자 아버지가 야속해서 눈물이 났어요."],"title":"바람이 잦아든 새벽 (앞)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#1','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C15',2,'ox','auto','인물의 성격은 인물이 한 말만 보면 다 알 수 있어요.',ARRAY['K5-2-u6-X15']::text[],false,'{"seq":1,"concept":"K5-2-u6-C15","difficulty":2,"kind":"ox","stem":"인물의 성격은 인물이 한 말만 보면 다 알 수 있어요.","answer":"X","reason_options":[{"t":"짧은 말 뒤에도 행동에 깊은 마음이 담길 수 있어 말과 행동을 함께 보아야 하기 때문에","correct":true},{"t":"인물은 생각한 것을 모두 말로 하기 때문에","mis":"K5-2-u6-X15"}],"mis":"K5-2-u6-X15","explanation":["말만으로는 부족해요.","행동도 함께 봐요.","아버지의 행동을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#2','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C17',2,'mc','auto','「아버지가 야속해서 눈물이 났어요.」에서 「야속하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X17']::text[],false,'{"seq":2,"concept":"K5-2-u6-C17","difficulty":2,"kind":"mc","stem":"「아버지가 야속해서 눈물이 났어요.」에서 「야속하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"무정한 행동이 섭섭하게 여겨져 언짢다","correct":true},{"t":"고마워서 마음이 따뜻하다","mis":"K5-2-u6-X17"},{"t":"무서워서 몸이 떨린다","mis":"K5-2-u6-X17"},{"t":"너무 기뻐서 가슴이 뛴다","mis":"K5-2-u6-X17"}],"explanation":["뜻과 반대예요.","뜻이 달라요.","섭섭하고 언짢은 마음이에요."],"asset":{"type":"passage","lines":["다리가 놓이기 전, 작은 섬 소리섬에서 육지로 가는 배는 아버지의 나룻배뿐이었어요.","도윤이는 육지에서 열리는 어린이 그림 대회에 학교 대표로 뽑혔어요.","대회 전날 밤, 도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.","그런데 라디오에서 태풍이 올라온다는 소식이 흘러나왔어요.","아버지는 묵묵히 그물을 손질하다가 한마디만 했어요. 「내일은 배 못 띄운다.」","「한 해를 기다린 대회란 말이에요!」 도윤이는 방문을 쾅 닫았어요.","이불을 뒤집어쓰자 아버지가 야속해서 눈물이 났어요."],"title":"바람이 잦아든 새벽 (앞)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#3','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C14',3,'mc','auto','이 이야기의 배경이 다리가 놓인 섬이었다면 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X14']::text[],false,'{"seq":3,"concept":"K5-2-u6-C14","difficulty":3,"kind":"mc","stem":"이 이야기의 배경이 다리가 놓인 섬이었다면 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다리로 육지에 갈 수 있어 아버지가 밤새 배를 지키는 사건이 일어나지 않았을 것이다","correct":true},{"t":"배경이 바뀌어도 사건과 마음은 똑같다","mis":"K5-2-u6-X14"},{"t":"도윤이가 그림 대회에 뽑히지 않았을 것이다","mis":"K5-2-u6-X14"},{"t":"아버지가 더 무뚝뚝해졌을 것이다","mis":"K5-2-u6-X14"}],"explanation":["배경이 사건을 바꿔요.","대표로 뽑힌 일과는 관계없어요.","배가 유일한 길이라 생긴 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#4','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C16',3,'mc','auto','「잦아들다」의 뜻을 몰랐을 때 가장 알맞게 알아본 친구는 누구인가요?',ARRAY['K5-2-u6-X16','K5-2-u6-X17']::text[],false,'{"seq":4,"concept":"K5-2-u6-C16","difficulty":3,"kind":"mc","stem":"「잦아들다」의 뜻을 몰랐을 때 가장 알맞게 알아본 친구는 누구인가요?","options":[{"t":"「바람이 잦아들자 배를 띄웠으니 바람이 약해진 것 같다.」라고 짐작하고 사전에서 확인한 뒤 문장에 넣어 읽었다","correct":true},{"t":"뜻을 모르는 채 그냥 지나쳤다","mis":"K5-2-u6-X16"},{"t":"사전 뜻을 공책에 베끼기만 하고 문장에 넣어 보지 않았다","mis":"K5-2-u6-X16"},{"t":"「잦다」가 들어 있으니 바람이 더 자주 분다는 뜻이라고 정했다","mis":"K5-2-u6-X17"}],"explanation":["그냥 지나치면 장면이 흐려요.","문장에 넣어 확인해요.","짐작 → 사전 → 넣어 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#5','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C18',3,'error','auto','친구들이 인상 깊은 장면을 말했어요. 감상을 나누는 말로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u6-X18']::text[],false,'{"seq":5,"concept":"K5-2-u6-C18","difficulty":3,"kind":"error","stem":"친구들이 인상 깊은 장면을 말했어요. 감상을 나누는 말로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「인상 깊은 장면은 내가 고른 것 하나뿐이야. 너는 틀렸어.」","correct":true,"mis_target":"K5-2-u6-X18"},{"t":"「손등에 쓸린 자국 장면이 기억에 남아. 아버지가 얼마나 애썼는지 보여서.」","mis":"K5-2-u6-X18"},{"t":"「그림 제목 장면이 좋았어. 도윤이 마음이 바뀐 게 느껴져서.」","mis":"K5-2-u6-X18"}],"explanation":["까닭이 있어요.","까닭이 있어요.","장면은 사람마다 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#6','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C13',3,'mc','auto','도윤이가 아버지를 야속하게 여기던 마음이 바뀌게 된 계기는 어느 장면인가요?',ARRAY['K5-2-u6-X13']::text[],false,'{"seq":6,"concept":"K5-2-u6-C13","difficulty":3,"kind":"mc","stem":"도윤이가 아버지를 야속하게 여기던 마음이 바뀌게 된 계기는 어느 장면인가요?","options":[{"t":"새벽에 젖은 채 밧줄을 묶는 아버지를 본 장면","correct":true},{"t":"라디오에서 태풍 소식이 나온 장면","mis":"K5-2-u6-X13"},{"t":"크레파스를 다시 챙긴 장면","mis":"K5-2-u6-X13"},{"t":"아버지가 그물을 손질한 장면","mis":"K5-2-u6-X13"}],"explanation":["야속함이 생긴 장면이에요.","들뜬 마음의 장면이에요.","아버지의 애씀을 본 뒤 마음이 바뀌었어요."],"asset":{"type":"passage","lines":["밤새 바람이 문풍지를 흔들었어요.","새벽에 나가 보니 아버지가 흠뻑 젖은 채 나룻배 밧줄을 다시 묶고 있었어요.","「배가 떠내려가면 우리 섬은 육지로 갈 길이 없어진단다.」","아버지의 손등에는 밧줄에 쓸린 자국이 벌겋게 나 있었어요.","해가 뜰 무렵, 바람이 거짓말처럼 잦아들었어요. 아버지는 말없이 노를 잡았어요.","「가자. 대회 늦겠다.」","도윤이는 노를 젓는 아버지의 젖은 등을 오래도록 바라보았어요.","그날 도윤이가 그린 그림의 제목은 「새벽 바다의 아버지」였어요."],"title":"바람이 잦아든 새벽 (뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#7','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C19',3,'mc','auto','도윤이에게 쓰는 편지의 한 부분으로 인물의 처지와 마음을 가장 잘 헤아린 것은 어느 것인가요?',ARRAY['K5-2-u6-X19']::text[],false,'{"seq":7,"concept":"K5-2-u6-C19","difficulty":3,"kind":"mc","stem":"도윤이에게 쓰는 편지의 한 부분으로 인물의 처지와 마음을 가장 잘 헤아린 것은 어느 것인가요?","options":[{"t":"「한 해를 기다린 대회였으니 얼마나 속상했겠니. 그래도 새벽 바다에서 아버지 등을 보며 마음이 따뜻해졌을 것 같아.」","correct":true},{"t":"「도윤아, 너는 소리섬에 살고 대회에 나갔어.」","mis":"K5-2-u6-X19"},{"t":"「방문을 쾅 닫다니 버릇이 없구나.」","mis":"K5-2-u6-X19"},{"t":"「그림 대회는 재미없어.」","mis":"K5-2-u6-X19"}],"explanation":["줄거리만 옮겼어요.","꾸짖기만 했어요.","처지와 마음을 헤아렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#8','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C13',4,'essay','teacher','「바람이 잦아든 새벽」에서 사건에 따라 도윤이의 마음이 어떻게 바뀌었는지 차례대로 쓰고, 마음이 바뀐 까닭을 사건과 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C13","difficulty":4,"kind":"essay","stem":"「바람이 잦아든 새벽」에서 사건에 따라 도윤이의 마음이 어떻게 바뀌었는지 차례대로 쓰고, 마음이 바뀐 까닭을 사건과 이어 쓰세요.","answer_guide":{"answer":"예: 대회 전날 밤에는 들뜬 마음이었다. 아버지가 태풍 때문에 배를 못 띄운다고 하자 야속하고 서운했다. 새벽에 젖은 채 밧줄을 묶는 아버지를 보고 놀라고 미안했다. 바람이 잦아들어 아버지가 노를 저어 주자 고맙고 뭉클했다.","scoring_points":["마음을 차례대로 썼는가","마음마다 사건을 이어 썼는가","이야기와 맞는가"]},"explanation":["차례대로 써요.","사건과 이어요.","글과 맞춰요."],"asset":{"type":"passage","lines":["밤새 바람이 문풍지를 흔들었어요.","새벽에 나가 보니 아버지가 흠뻑 젖은 채 나룻배 밧줄을 다시 묶고 있었어요.","「배가 떠내려가면 우리 섬은 육지로 갈 길이 없어진단다.」","아버지의 손등에는 밧줄에 쓸린 자국이 벌겋게 나 있었어요.","해가 뜰 무렵, 바람이 거짓말처럼 잦아들었어요. 아버지는 말없이 노를 잡았어요.","「가자. 대회 늦겠다.」","도윤이는 노를 젓는 아버지의 젖은 등을 오래도록 바라보았어요.","그날 도윤이가 그린 그림의 제목은 「새벽 바다의 아버지」였어요."],"title":"바람이 잦아든 새벽 (뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#9','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C18',4,'essay','teacher','「바람이 잦아든 새벽」에서 가장 인상 깊은 장면을 고르고, 그 장면을 고른 까닭을 인물의 말이나 행동과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u6-C18","difficulty":4,"kind":"essay","stem":"「바람이 잦아든 새벽」에서 가장 인상 깊은 장면을 고르고, 그 장면을 고른 까닭을 인물의 말이나 행동과 함께 쓰세요.","answer_guide":{"answer":"예: 아버지의 손등에 밧줄에 쓸린 자국이 벌겋게 나 있는 장면이 가장 인상 깊다. 「내일은 배 못 띄운다.」라는 짧은 말만 했지만, 밤새 배를 지킨 손등을 보니 아버지가 섬 사람들과 도윤이를 얼마나 아끼는지 느껴졌기 때문이다.","scoring_points":["장면을 골랐는가","까닭을 썼는가","말이나 행동을 근거로 들었는가"]},"explanation":["장면을 골라요.","까닭을 써요.","근거를 들어요."],"asset":{"type":"passage","lines":["밤새 바람이 문풍지를 흔들었어요.","새벽에 나가 보니 아버지가 흠뻑 젖은 채 나룻배 밧줄을 다시 묶고 있었어요.","「배가 떠내려가면 우리 섬은 육지로 갈 길이 없어진단다.」","아버지의 손등에는 밧줄에 쓸린 자국이 벌겋게 나 있었어요.","해가 뜰 무렵, 바람이 거짓말처럼 잦아들었어요. 아버지는 말없이 노를 잡았어요.","「가자. 대회 늦겠다.」","도윤이는 노를 젓는 아버지의 젖은 등을 오래도록 바라보았어요.","그날 도윤이가 그린 그림의 제목은 「새벽 바다의 아버지」였어요."],"title":"바람이 잦아든 새벽 (뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L04_challenge#10','kor',5,2,'u6','L04','g5_2_kor_u6_L04_challenge','lesson_challenge','K5-2-u6-C19',4,'essay','teacher','도윤이나 아버지 가운데 한 사람에게 마음을 담아 편지를 쓰세요. 인물이 겪은 일과 그때의 마음을 헤아린 말을 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u6-C19","difficulty":4,"kind":"essay","stem":"도윤이나 아버지 가운데 한 사람에게 마음을 담아 편지를 쓰세요. 인물이 겪은 일과 그때의 마음을 헤아린 말을 넣으세요.","answer_guide":{"answer":"예: 도윤이 아버지께. 태풍 소식에 배를 못 띄운다고 하셨을 때 도윤이가 방문을 쾅 닫아 많이 속상하셨지요. 그래도 밤새 비바람 속에서 밧줄을 묶으신 덕분에 도윤이가 대회에 갈 수 있었어요. 말은 짧아도 마음은 누구보다 깊으신 아버지의 모습이 오래 기억에 남을 것 같아요.","scoring_points":["받는 사람을 정했는가","겪은 일을 썼는가","마음을 헤아린 말을 썼는가"]},"explanation":["받는 사람을 정해요.","겪은 일을 써요.","마음을 헤아려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#1','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C20',1,'mc','auto','연극을 하려고 쓴 글을 무엇이라고 하나요?',ARRAY['K5-2-u6-X20']::text[],false,'{"seq":1,"concept":"K5-2-u6-C20","difficulty":1,"kind":"mc","stem":"연극을 하려고 쓴 글을 무엇이라고 하나요?","options":[{"t":"극본","correct":true},{"t":"일기","mis":"K5-2-u6-X20"},{"t":"기행문","mis":"K5-2-u6-X20"},{"t":"설명하는 글","mis":"K5-2-u6-X20"}],"explanation":["하루를 적은 글이에요.","여행을 적은 글이에요.","공연하려고 쓴 글이 극본이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#2','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C22',1,'mc','auto','극본에서 인물이 직접 하는 말을 무엇이라고 하나요?',ARRAY['K5-2-u6-X22']::text[],false,'{"seq":2,"concept":"K5-2-u6-C22","difficulty":1,"kind":"mc","stem":"극본에서 인물이 직접 하는 말을 무엇이라고 하나요?","options":[{"t":"대사","correct":true},{"t":"지문","mis":"K5-2-u6-X22"},{"t":"해설","mis":"K5-2-u6-X22"},{"t":"제목","mis":"K5-2-u6-X22"}],"explanation":["괄호 속 안내예요.","첫 부분의 설명이에요.","인물이 직접 하는 말이 대사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#3','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C23',1,'mc','auto','「(고개를 저으며) 마지막 차가 벌써 떠났단다.」에서 「(고개를 저으며)」는 극본의 구성 요소 가운데 무엇인가요?',ARRAY['K5-2-u6-X23']::text[],false,'{"seq":3,"concept":"K5-2-u6-C23","difficulty":1,"kind":"mc","stem":"「(고개를 저으며) 마지막 차가 벌써 떠났단다.」에서 「(고개를 저으며)」는 극본의 구성 요소 가운데 무엇인가요?","options":[{"t":"지문","correct":true},{"t":"해설","mis":"K5-2-u6-X23"},{"t":"대사","mis":"K5-2-u6-X23"},{"t":"제목","mis":"K5-2-u6-X23"}],"explanation":["첫 부분의 설명이에요.","소리 내어 하는 말이에요.","행동을 괄호로 나타낸 지문이에요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#4','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C21',1,'mc','auto','극본 첫 부분에서 때와 곳, 나오는 인물, 무대 모습을 알려 주는 부분은 무엇인가요?',ARRAY['K5-2-u6-X21']::text[],false,'{"seq":4,"concept":"K5-2-u6-C21","difficulty":1,"kind":"mc","stem":"극본 첫 부분에서 때와 곳, 나오는 인물, 무대 모습을 알려 주는 부분은 무엇인가요?","options":[{"t":"해설","correct":true},{"t":"대사","mis":"K5-2-u6-X21"},{"t":"지문","mis":"K5-2-u6-X21"},{"t":"줄거리","mis":"K5-2-u6-X21"}],"explanation":["인물이 하는 말이에요.","괄호 속 안내예요.","첫 부분의 설명이 해설이에요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#5','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C23',2,'mc','auto','하율이를 맡은 배우가 「(울먹이며) 내일이 할아버지 생신인데…….」를 연기하는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X23','K5-2-u6-X25']::text[],false,'{"seq":5,"concept":"K5-2-u6-C23","difficulty":2,"kind":"mc","stem":"하율이를 맡은 배우가 「(울먹이며) 내일이 할아버지 생신인데…….」를 연기하는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"「울먹이며」는 말하지 않고 울먹이는 목소리로 대사를 한다","correct":true},{"t":"「울먹이며 내일이 할아버지 생신인데」라고 모두 소리 내어 말한다","mis":"K5-2-u6-X23"},{"t":"큰 소리로 웃으며 대사를 한다","mis":"K5-2-u6-X25"},{"t":"대사는 빼고 「울먹이며」만 말한다","mis":"K5-2-u6-X23"}],"explanation":["지문은 말하지 않아요.","지문과 맞지 않아요.","지문을 목소리로 표현해요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#6','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C21',2,'mc','auto','극본 「눈 오는 날의 우체국」의 무대를 꾸밀 때 해설에서 알 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u6-X21']::text[],false,'{"seq":6,"concept":"K5-2-u6-C21","difficulty":2,"kind":"mc","stem":"극본 「눈 오는 날의 우체국」의 무대를 꾸밀 때 해설에서 알 수 있는 것은 어느 것인가요?","options":[{"t":"무대 왼쪽에 빨간 우체통이 있고 창밖으로 눈이 쌓인다","correct":true},{"t":"하율이가 울먹인다","mis":"K5-2-u6-X21"},{"t":"우체부가 빙그레 웃는다","mis":"K5-2-u6-X21"},{"t":"할머니가 편지를 들고 간다","mis":"K5-2-u6-X21"}],"explanation":["지문에 있어요.","지문에 있어요.","해설이 무대를 알려 줘요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#7','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C24',2,'match','auto','이야기 글과 극본에서 인물의 말과 행동을 쓰는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u6-C24","difficulty":2,"kind":"match","stem":"이야기 글과 극본에서 인물의 말과 행동을 쓰는 방법을 알맞게 이으세요.","pairs":[{"l":"이야기 글의 인물 말","r":"따옴표 안에 쓴다"},{"l":"극본의 인물 말","r":"인물 이름 뒤에 대사로 쓴다"},{"l":"극본의 인물 행동","r":"괄호 안 지문으로 쓴다"}],"mis":"K5-2-u6-X24","explanation":["줄글 속 따옴표예요.","이름 뒤 대사예요.","괄호 속 지문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#8','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C23',2,'ox','auto','극본에서 괄호 안의 말도 배우가 소리 내어 말하는 대사예요.',ARRAY['K5-2-u6-X23']::text[],false,'{"seq":8,"concept":"K5-2-u6-C23","difficulty":2,"kind":"ox","stem":"극본에서 괄호 안의 말도 배우가 소리 내어 말하는 대사예요.","answer":"X","reason_options":[{"t":"괄호 안의 지문은 표정·행동·말투를 몸과 목소리로 표현하라는 안내이기 때문에","correct":true},{"t":"극본에 쓰인 말은 모두 소리 내어 읽어야 하기 때문에","mis":"K5-2-u6-X23"}],"mis":"K5-2-u6-X23","explanation":["지문은 대사가 아니에요.","몸과 목소리로 표현해요.","소리 내어 말하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#9','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C26',2,'mc','auto','극본을 읽을 때 장면을 상상하며 읽는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X26','K5-2-u6-X25']::text[],false,'{"seq":9,"concept":"K5-2-u6-C26","difficulty":2,"kind":"mc","stem":"극본을 읽을 때 장면을 상상하며 읽는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해설로 무대 모습을 떠올리고 지문으로 인물의 움직임을 그려 본다","correct":true},{"t":"대사만 빠르게 소리 내어 읽는다","mis":"K5-2-u6-X26"},{"t":"괄호 안의 말은 건너뛴다","mis":"K5-2-u6-X25"},{"t":"인물 이름만 따로 모아 읽는다","mis":"K5-2-u6-X26"}],"explanation":["장면이 떠오르지 않아요.","지문이 장면을 알려 줘요.","해설과 지문으로 무대를 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_basic#10','kor',5,2,'u6','L07','g5_2_kor_u6_L07_basic','lesson_basic','K5-2-u6-C22',3,'mc','auto','「하율아, 눈 오는데 어딜 그렇게 뛰어갔니?」는 극본의 무엇이고, 누가 하는 말인가요?',ARRAY['K5-2-u6-X22','K5-2-u6-X23']::text[],false,'{"seq":10,"concept":"K5-2-u6-C22","difficulty":3,"kind":"mc","stem":"「하율아, 눈 오는데 어딜 그렇게 뛰어갔니?」는 극본의 무엇이고, 누가 하는 말인가요?","options":[{"t":"할머니의 대사","correct":true},{"t":"우체부의 대사","mis":"K5-2-u6-X22"},{"t":"해설","mis":"K5-2-u6-X22"},{"t":"할머니의 지문","mis":"K5-2-u6-X23"}],"explanation":["말한 사람이 달라요.","첫 부분의 설명이 아니에요.","할머니가 직접 하는 말이에요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#1','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C20',2,'ox','auto','극본은 읽는 사람이 혼자 줄글로 읽으려고 쓴 글이에요.',ARRAY['K5-2-u6-X20']::text[],false,'{"seq":1,"concept":"K5-2-u6-C20","difficulty":2,"kind":"ox","stem":"극본은 읽는 사람이 혼자 줄글로 읽으려고 쓴 글이에요.","answer":"X","reason_options":[{"t":"극본은 무대에서 연극으로 공연하려고 쓴 글이기 때문에","correct":true},{"t":"극본도 이야기 글처럼 줄글로 이어 쓰기 때문에","mis":"K5-2-u6-X20"}],"mis":"K5-2-u6-X20","explanation":["공연하려고 써요.","대사와 지문으로 나눠요.","극본의 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#2','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C21',2,'mc','auto','해설을 읽으면 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X21','K5-2-u6-X22']::text[],false,'{"seq":2,"concept":"K5-2-u6-C21","difficulty":2,"kind":"mc","stem":"해설을 읽으면 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"때, 곳, 나오는 인물, 무대 모습","correct":true},{"t":"인물이 지금 느끼는 감정","mis":"K5-2-u6-X21"},{"t":"인물이 다음에 할 대사","mis":"K5-2-u6-X22"},{"t":"객석에 앉은 관객의 수","mis":"K5-2-u6-X21"}],"explanation":["감정은 대사와 지문에서 드러나요.","대사는 따로 있어요.","해설은 무대를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#3','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C21',3,'error','auto','극본에 대해 친구들이 말했어요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u6-X21','K5-2-u6-X23','K5-2-u6-X22']::text[],false,'{"seq":3,"concept":"K5-2-u6-C21","difficulty":3,"kind":"error","stem":"극본에 대해 친구들이 말했어요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「해설을 보면 인물의 감정을 알 수 있어.」","correct":true,"mis_target":"K5-2-u6-X21"},{"t":"「지문으로 인물의 행동이나 목소리를 알 수 있어.」","mis":"K5-2-u6-X23"},{"t":"「대사와 지문을 살펴보면 인물의 마음을 알 수 있어.」","mis":"K5-2-u6-X22"}],"explanation":["바른 말이에요.","바른 말이에요.","해설은 때·곳·인물·무대를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#4','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C24',3,'mc','auto','이야기 글 「하율이는 숨을 헐떡이며 아저씨에게 편지를 오늘 꼭 보내야 한다고 말했어요.」를 극본으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K5-2-u6-X24','K5-2-u6-X23']::text[],false,'{"seq":4,"concept":"K5-2-u6-C24","difficulty":3,"kind":"mc","stem":"이야기 글 「하율이는 숨을 헐떡이며 아저씨에게 편지를 오늘 꼭 보내야 한다고 말했어요.」를 극본으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"하율: (숨을 헐떡이며) 아저씨, 이 편지 오늘 꼭 보내야 해요!","correct":true},{"t":"하율이는 숨을 헐떡였어요. 그리고 편지를 보내야 한다고 말했어요.","mis":"K5-2-u6-X24"},{"t":"하율: 숨을 헐떡이며 편지를 보내야 한다고 말했다.","mis":"K5-2-u6-X24"},{"t":"(하율: 아저씨, 이 편지 오늘 꼭 보내야 해요!) 숨을 헐떡이며","mis":"K5-2-u6-X23"}],"explanation":["줄글 그대로예요.","행동이 괄호 밖에 있어요.","대사와 지문으로 나누었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#5','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C25',3,'mc','auto','「눈 오는 날의 우체국」을 모둠이 낭독하려고 해요. 준비하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X25','K5-2-u6-X23']::text[],false,'{"seq":5,"concept":"K5-2-u6-C25","difficulty":3,"kind":"mc","stem":"「눈 오는 날의 우체국」을 모둠이 낭독하려고 해요. 준비하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해설·하율·우체부·할머니 역할을 나누고, 지문을 보고 목소리와 표정을 정해 해설부터 차례대로 읽는다","correct":true},{"t":"지문은 건너뛰고 대사만 한 사람이 모두 읽는다","mis":"K5-2-u6-X25"},{"t":"해설은 빼고 마지막 대사부터 읽는다","mis":"K5-2-u6-X25"},{"t":"괄호 안의 말까지 모두 큰 소리로 읽는다","mis":"K5-2-u6-X23"}],"explanation":["지문을 살려야 해요.","해설부터 차례대로예요.","역할을 나누고 지문대로 읽어요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#6','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C26',3,'mc','auto','우체부가 「(빙그레 웃으며)」 말하는 장면을 상상할 때 그 순간 우체부의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X26']::text[],false,'{"seq":6,"concept":"K5-2-u6-C26","difficulty":3,"kind":"mc","stem":"우체부가 「(빙그레 웃으며)」 말하는 장면을 상상할 때 그 순간 우체부의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"편지를 보낼 좋은 방법이 떠올라 하율이를 안심시키고 싶은 마음","correct":true},{"t":"하율이를 놀리고 싶은 마음","mis":"K5-2-u6-X26"},{"t":"우체국 문을 빨리 닫고 싶은 마음","mis":"K5-2-u6-X26"},{"t":"할머니에게 화가 난 마음","mis":"K5-2-u6-X26"}],"explanation":["대사와 맞지 않아요.","대사와 맞지 않아요.","지문과 대사를 함께 떠올려요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#7','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C23',3,'mc','auto','극본에 지문이 없다면 배우가 가장 어려워할 일은 어느 것인가요?',ARRAY['K5-2-u6-X21','K5-2-u6-X22']::text[],false,'{"seq":7,"concept":"K5-2-u6-C23","difficulty":3,"kind":"mc","stem":"극본에 지문이 없다면 배우가 가장 어려워할 일은 어느 것인가요?","options":[{"t":"인물이 어떤 표정과 말투로 대사를 해야 할지 알기","correct":true},{"t":"무대가 어디인지 알기","mis":"K5-2-u6-X21"},{"t":"누가 나오는지 알기","mis":"K5-2-u6-X21"},{"t":"인물이 무슨 말을 하는지 알기","mis":"K5-2-u6-X22"}],"explanation":["해설이 알려 줘요.","해설이 알려 줘요.","지문이 표정과 말투를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#8','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C20',4,'essay','teacher','극본의 구성 요소인 해설, 대사, 지문의 뜻을 각각 쓰고, 「눈 오는 날의 우체국」에서 예를 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C20","difficulty":4,"kind":"essay","stem":"극본의 구성 요소인 해설, 대사, 지문의 뜻을 각각 쓰고, 「눈 오는 날의 우체국」에서 예를 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 해설은 극본 첫 부분에서 때, 곳, 등장인물, 무대 배경을 설명하는 부분이다 — 「때: 눈 내리는 겨울 저녁」. 대사는 인물이 직접 하는 말이다 — 「아저씨, 이 편지 오늘 꼭 보내야 해요!」. 지문은 인물의 표정, 행동, 말투를 괄호로 나타낸 부분이다 — 「(울먹이며)」.","scoring_points":["세 요소의 뜻을 썼는가","극본에서 예를 찾았는가","뜻과 예가 맞는가"]},"explanation":["뜻을 써요.","예를 찾아요.","맞게 짝지어요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#9','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C24',4,'essay','teacher','「바람이 잦아든 새벽」에서 아버지가 「내일은 배 못 띄운다.」라고 말하는 장면을 해설, 대사, 지문이 들어간 극본으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u6-C24","difficulty":4,"kind":"essay","stem":"「바람이 잦아든 새벽」에서 아버지가 「내일은 배 못 띄운다.」라고 말하는 장면을 해설, 대사, 지문이 들어간 극본으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 때: 태풍 소식이 들려온 밤 · 곳: 작은 섬 소리섬의 집 · 나오는 인물: 도윤, 아버지 / (라디오에서 태풍 소식이 흘러나온다.) / 아버지: (그물을 손질하며 고개를 들지 않고) 내일은 배 못 띄운다. / 도윤: (벌떡 일어나며) 한 해를 기다린 대회란 말이에요! (방문을 쾅 닫는다.)","scoring_points":["해설을 썼는가","대사를 인물 이름 뒤에 썼는가","지문을 괄호로 썼는가"]},"explanation":["해설을 써요.","대사로 써요.","지문은 괄호로 써요."],"asset":{"type":"passage","lines":["다리가 놓이기 전, 작은 섬 소리섬에서 육지로 가는 배는 아버지의 나룻배뿐이었어요.","도윤이는 육지에서 열리는 어린이 그림 대회에 학교 대표로 뽑혔어요.","대회 전날 밤, 도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.","그런데 라디오에서 태풍이 올라온다는 소식이 흘러나왔어요.","아버지는 묵묵히 그물을 손질하다가 한마디만 했어요. 「내일은 배 못 띄운다.」","「한 해를 기다린 대회란 말이에요!」 도윤이는 방문을 쾅 닫았어요.","이불을 뒤집어쓰자 아버지가 야속해서 눈물이 났어요."],"title":"바람이 잦아든 새벽 (앞)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L07_challenge#10','kor',5,2,'u6','L07','g5_2_kor_u6_L07_challenge','lesson_challenge','K5-2-u6-C25',4,'essay','teacher','「눈 오는 날의 우체국」에서 하율이를 맡아 낭독한다면 지문을 보고 각 대사를 어떤 목소리와 표정으로 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u6-C25","difficulty":4,"kind":"essay","stem":"「눈 오는 날의 우체국」에서 하율이를 맡아 낭독한다면 지문을 보고 각 대사를 어떤 목소리와 표정으로 할지 쓰세요.","answer_guide":{"answer":"예: 첫 대사는 「숨을 헐떡이며」라는 지문에 맞게 숨이 찬 목소리로 다급하게 말하고 봉투를 내밀겠다. 둘째 대사는 「울먹이며」에 맞게 목소리를 떨며 작게 말하고 고개를 숙이겠다.","scoring_points":["대사마다 지문을 살폈는가","목소리를 썼는가","표정이나 몸짓을 썼는가"]},"explanation":["지문을 살펴요.","목소리를 정해요.","표정을 정해요."],"asset":{"type":"passage","lines":["때: 눈 내리는 겨울 저녁 · 곳: 산골 마을 작은 우체국 · 나오는 인물: 하율, 우체부, 할머니","무대 왼쪽에 빨간 우체통이 있고, 창밖으로 눈이 소복소복 쌓인다.","하율: (숨을 헐떡이며 봉투를 내민다.) 아저씨, 이 편지 오늘 꼭 보내야 해요!","우체부: (고개를 저으며) 마지막 차가 벌써 떠났단다. 고갯길도 눈에 막혔고.","하율: (울먹이며) 내일이 할아버지 생신인데…….","할머니: (문을 열고 들어서며) 하율아, 눈 오는데 어딜 그렇게 뛰어갔니?","우체부: (빙그레 웃으며) 받는 분이 할아버지라면, 할머니 손에 실려 가면 되겠구나."],"title":"극본 「눈 오는 날의 우체국」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#1','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C29',1,'mc','auto','부엉이 선생님이 음악회가 어렵겠다고 한 까닭은 무엇인가요?',ARRAY['K5-2-u6-X27']::text[],false,'{"seq":1,"concept":"K5-2-u6-C29","difficulty":1,"kind":"mc","stem":"부엉이 선생님이 음악회가 어렵겠다고 한 까닭은 무엇인가요?","options":[{"t":"비에 북이 젖어 소리가 나지 않아서","correct":true},{"t":"관객이 한 명도 오지 않아서","mis":"K5-2-u6-X27"},{"t":"가시가 북을 찢어서","mis":"K5-2-u6-X27"},{"t":"토리가 노래를 못 해서","mis":"K5-2-u6-X27"}],"explanation":["극본에 없어요.","극본에 없어요.","지문과 대사를 이어 읽으면 알아요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#2','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C27',1,'mc','auto','극본을 감상할 때 이어서 읽어야 하는 것은 어느 것인가요?',ARRAY['K5-2-u6-X27']::text[],false,'{"seq":2,"concept":"K5-2-u6-C27","difficulty":1,"kind":"mc","stem":"극본을 감상할 때 이어서 읽어야 하는 것은 어느 것인가요?","options":[{"t":"해설, 대사, 지문","correct":true},{"t":"대사만","mis":"K5-2-u6-X27"},{"t":"인물 이름만","mis":"K5-2-u6-X27"},{"t":"제목과 지문만","mis":"K5-2-u6-X27"}],"explanation":["대사만으로는 부족해요.","이름만으로는 몰라요.","셋을 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#3','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C28',1,'mc','auto','누가 누구와 어떤 사이인지 한눈에 보이게 정리한 것을 무엇이라고 하나요?',ARRAY['K5-2-u6-X28']::text[],false,'{"seq":3,"concept":"K5-2-u6-C28","difficulty":1,"kind":"mc","stem":"누가 누구와 어떤 사이인지 한눈에 보이게 정리한 것을 무엇이라고 하나요?","options":[{"t":"인물 관계도","correct":true},{"t":"무대 배치도","mis":"K5-2-u6-X28"},{"t":"낱말 사전","mis":"K5-2-u6-X28"},{"t":"공연 안내지","mis":"K5-2-u6-X28"}],"explanation":["무대 자리를 그려요.","낱말 뜻을 찾아요.","인물 사이를 그린 것이 관계도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#4','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C29',1,'mc','auto','「빗속의 숲속 음악회」에서 가장 마지막에 일어난 일은 무엇인가요?',ARRAY['K5-2-u6-X29']::text[],false,'{"seq":4,"concept":"K5-2-u6-C29","difficulty":1,"kind":"mc","stem":"「빗속의 숲속 음악회」에서 가장 마지막에 일어난 일은 무엇인가요?","options":[{"t":"뭉치가 가시에게 사과했다","correct":true},{"t":"토리가 가시를 위로했다","mis":"K5-2-u6-X29"},{"t":"빗방울이 떨어져 북이 젖었다","mis":"K5-2-u6-X29"},{"t":"뭉치가 가시에게 북을 치지 말라고 했다","mis":"K5-2-u6-X29"}],"explanation":["앞에서 일어났어요.","앞에서 일어났어요.","마지막 대사를 살펴요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#5','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C28',2,'mc','auto','토리와 가시의 관계를 알 수 있는 지문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X28']::text[],false,'{"seq":5,"concept":"K5-2-u6-C28","difficulty":2,"kind":"mc","stem":"토리와 가시의 관계를 알 수 있는 지문으로 알맞은 것은 어느 것인가요?","options":[{"t":"(가시를 따라가 어깨를 토닥이며)","correct":true},{"t":"(북을 끌어안으며)","mis":"K5-2-u6-X28"},{"t":"(젖은 북을 두드려 보고)","mis":"K5-2-u6-X28"},{"t":"(하늘이 어두워지고 빗방울이 후드득 떨어진다.)","mis":"K5-2-u6-X28"}],"explanation":["뭉치의 행동이에요.","선생님의 행동이에요.","토리가 가시 편이 되어 주어요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#6','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C28',2,'match','auto','인물과 가시와의 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u6-C28","difficulty":2,"kind":"match","stem":"인물과 가시와의 관계를 알맞게 이으세요.","pairs":[{"l":"토리","r":"풀이 죽은 가시의 편이 되어 주는 친구"},{"l":"뭉치","r":"가시를 말렸다가 사과하는 친구"},{"l":"부엉이 선생님","r":"음악회를 이끄는 선생님"}],"mis":"K5-2-u6-X28","explanation":["토리는 위로해요.","뭉치는 사과해요.","선생님은 음악회를 이끌어요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#7','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C30',2,'mc','auto','역할 수행 학습의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X30']::text[],false,'{"seq":7,"concept":"K5-2-u6-C30","difficulty":2,"kind":"mc","stem":"역할 수행 학습의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"상황 설정하기 → 준비 및 연습하기 → 실연하기 → 평가하기","correct":true},{"t":"실연하기 → 상황 설정하기 → 평가하기 → 준비 및 연습하기","mis":"K5-2-u6-X30"},{"t":"평가하기 → 실연하기 → 준비 및 연습하기 → 상황 설정하기","mis":"K5-2-u6-X30"},{"t":"준비 및 연습하기 → 평가하기 → 상황 설정하기 → 실연하기","mis":"K5-2-u6-X30"}],"explanation":["연습 없이 실연하지 않아요.","평가는 마지막이에요.","설정 → 연습 → 실연 → 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#8','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C31',2,'mc','auto','뭉치 역할을 맡은 친구가 인물의 마음을 깊이 이해하려고 던질 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X31']::text[],false,'{"seq":8,"concept":"K5-2-u6-C31","difficulty":2,"kind":"mc","stem":"뭉치 역할을 맡은 친구가 인물의 마음을 깊이 이해하려고 던질 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「뭉치는 왜 가시에게 북을 치지 말라고 했을까?」","correct":true},{"t":"「뭉치의 대사는 모두 몇 줄일까?」","mis":"K5-2-u6-X31"},{"t":"「뭉치 옷은 무슨 색일까?」","mis":"K5-2-u6-X31"},{"t":"「내 대사를 몇 번 외웠을까?」","mis":"K5-2-u6-X31"}],"explanation":["마음과 관계없어요.","마음과 관계없어요.","말한 까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#9','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C27',2,'ox','auto','극본은 대사만 따라 읽으면 내용을 다 알 수 있어요.',ARRAY['K5-2-u6-X27']::text[],false,'{"seq":9,"concept":"K5-2-u6-C27","difficulty":2,"kind":"ox","stem":"극본은 대사만 따라 읽으면 내용을 다 알 수 있어요.","answer":"X","reason_options":[{"t":"지문과 해설을 함께 읽어야 인물의 표정·행동과 사건이 벌어지는 곳까지 알 수 있기 때문에","correct":true},{"t":"인물이 하는 말에 모든 내용이 다 들어 있기 때문에","mis":"K5-2-u6-X27"}],"mis":"K5-2-u6-X27","explanation":["대사만으로는 부족해요.","지문과 해설도 읽어요.","이어 읽어야 감상이 깊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_basic#10','kor',5,2,'u6','L09','g5_2_kor_u6_L09_basic','lesson_basic','K5-2-u6-C29',3,'mc','auto','「빗속의 숲속 음악회」의 흐름을 바꾼 사건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X29']::text[],false,'{"seq":10,"concept":"K5-2-u6-C29","difficulty":3,"kind":"mc","stem":"「빗속의 숲속 음악회」의 흐름을 바꾼 사건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"비가 쏟아져 북이 젖은 일","correct":true},{"t":"토리가 가시를 위로한 일","mis":"K5-2-u6-X29"},{"t":"부엉이 선생님이 무대에 있는 일","mis":"K5-2-u6-X29"},{"t":"나무 무대가 숲속 빈터에 있는 일","mis":"K5-2-u6-X29"}],"explanation":["흐름이 바뀌지 않았어요.","배경이에요.","뜻밖의 비가 가시를 나서게 했어요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#1','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C31',2,'ox','auto','맡은 인물에게 「이 인물은 왜 이렇게 말했을까?」를 물으면 인물의 마음을 더 깊이 이해할 수 있어요.',ARRAY['K5-2-u6-X31']::text[],false,'{"seq":1,"concept":"K5-2-u6-C31","difficulty":2,"kind":"ox","stem":"맡은 인물에게 「이 인물은 왜 이렇게 말했을까?」를 물으면 인물의 마음을 더 깊이 이해할 수 있어요.","answer":"O","reason_options":[{"t":"말한 까닭을 생각하면 그 순간 인물의 마음을 짐작할 수 있기 때문에","correct":true},{"t":"대사를 외우기만 하면 인물의 마음은 저절로 알게 되기 때문에","mis":"K5-2-u6-X31"}],"mis":"K5-2-u6-X31","explanation":["까닭을 물어요.","마음을 짐작해요.","외우기만으로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#2','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C32',2,'mc','auto','인상적인 부분을 나누는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X32']::text[],false,'{"seq":2,"concept":"K5-2-u6-C32","difficulty":2,"kind":"mc","stem":"인상적인 부분을 나누는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「가시가 솔방울을 들고 나서는 장면이 인상적이었어. 북을 못 치게 했는데도 친구들을 도우려 해서 용기가 느껴졌어.」","correct":true},{"t":"「그냥 재미있었어.」","mis":"K5-2-u6-X32"},{"t":"「다 좋았어.」","mis":"K5-2-u6-X32"},{"t":"「제목이 길었어.」","mis":"K5-2-u6-X32"}],"explanation":["까닭이 없어요.","까닭이 없어요.","장면과 까닭을 함께 말했어요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#3','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C27',3,'mc','auto','「(얼굴이 빨개져서)」라는 지문을 빼고 뭉치의 사과를 읽으면 어떻게 될까요?',ARRAY['K5-2-u6-X27']::text[],false,'{"seq":3,"concept":"K5-2-u6-C27","difficulty":3,"kind":"mc","stem":"「(얼굴이 빨개져서)」라는 지문을 빼고 뭉치의 사과를 읽으면 어떻게 될까요?","options":[{"t":"뭉치가 미안하고 쑥스러워하는 마음이 덜 드러난다","correct":true},{"t":"아무것도 달라지지 않는다","mis":"K5-2-u6-X27"},{"t":"대사의 뜻이 정반대가 된다","mis":"K5-2-u6-X27"},{"t":"해설이 사라진다","mis":"K5-2-u6-X27"}],"explanation":["지문이 마음을 보여 줘요.","뜻이 바뀌지는 않아요.","지문이 빠지면 마음이 흐려져요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#4','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C30',3,'error','auto','역할 수행 학습의 차례와 하는 일을 짝지은 것이에요. 잘못 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u6-X30']::text[],false,'{"seq":4,"concept":"K5-2-u6-C30","difficulty":3,"kind":"error","stem":"역할 수행 학습의 차례와 하는 일을 짝지은 것이에요. 잘못 짝지은 것은 어느 것인가요?","options":[{"t":"「실연하기 — 학습 문제를 확인한다.」","correct":true,"mis_target":"K5-2-u6-X30"},{"t":"「준비 및 연습하기 — 극본을 읽고 사건 차례와 관계도를 정리한다.」","mis":"K5-2-u6-X30"},{"t":"「평가하기 — 낭독을 되돌아보고 인상적인 부분을 나눈다.」","mis":"K5-2-u6-X30"}],"explanation":["바르게 짝지었어요.","바르게 짝지었어요.","실연하기는 역할이 되어 낭독하는 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#5','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C28',3,'mc','auto','뭉치와 가시의 관계는 극본의 처음과 끝에서 어떻게 바뀌었나요?',ARRAY['K5-2-u6-X28']::text[],false,'{"seq":5,"concept":"K5-2-u6-C28","difficulty":3,"kind":"mc","stem":"뭉치와 가시의 관계는 극본의 처음과 끝에서 어떻게 바뀌었나요?","options":[{"t":"가시를 말리던 사이에서 가시의 장단에 맞춰 함께하는 사이로 바뀌었다","correct":true},{"t":"처음부터 끝까지 사이가 나빴다","mis":"K5-2-u6-X28"},{"t":"처음에는 친했다가 끝에 다투었다","mis":"K5-2-u6-X28"},{"t":"둘은 서로 말을 나누지 않았다","mis":"K5-2-u6-X28"}],"explanation":["끝에서 바뀌었어요.","차례가 거꾸로예요.","사과와 노래로 관계가 바뀌었어요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#6','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C31',3,'mc','auto','가시를 맡은 친구가 「선생님, 제가 해 볼게요!」 대사를 하기 전에 떠올리면 좋을 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X31','K5-2-u6-X36']::text[],false,'{"seq":6,"concept":"K5-2-u6-C31","difficulty":3,"kind":"mc","stem":"가시를 맡은 친구가 「선생님, 제가 해 볼게요!」 대사를 하기 전에 떠올리면 좋을 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조금 전 북을 치지 말라는 말을 들었지만 음악회를 살리고 싶은 마음","correct":true},{"t":"오늘 저녁에 먹을 것","mis":"K5-2-u6-X31"},{"t":"대사를 틀리면 창피할 것이라는 걱정만","mis":"K5-2-u6-X36"},{"t":"객석의 관객이 몇 명인지","mis":"K5-2-u6-X31"}],"explanation":["인물과 관계없어요.","대사보다 마음이 먼저예요.","그 순간 인물의 마음을 떠올려요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#7','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C32',3,'mc','auto','같은 장면을 두고 친구와 인상적인 까닭이 다를 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u6-X32']::text[],false,'{"seq":7,"concept":"K5-2-u6-C32","difficulty":3,"kind":"mc","stem":"같은 장면을 두고 친구와 인상적인 까닭이 다를 때 알맞은 태도는 어느 것인가요?","options":[{"t":"서로 극본 속 근거를 들어 까닭을 말하고 친구의 해석도 끝까지 듣는다","correct":true},{"t":"내 까닭만 정답이라고 우긴다","mis":"K5-2-u6-X32"},{"t":"까닭은 말하지 않고 장면만 말한다","mis":"K5-2-u6-X32"},{"t":"손을 많이 든 쪽의 까닭만 맞다고 정한다","mis":"K5-2-u6-X32"}],"explanation":["까닭은 여럿일 수 있어요.","까닭을 말해요.","근거를 들고 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#8','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C28',4,'essay','teacher','「빗속의 숲속 음악회」의 인물 관계도를 가시를 가운데 두고 말로 정리해 쓰고, 관계가 바뀐 인물이 있다면 어떻게 바뀌었는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C28","difficulty":4,"kind":"essay","stem":"「빗속의 숲속 음악회」의 인물 관계도를 가시를 가운데 두고 말로 정리해 쓰고, 관계가 바뀐 인물이 있다면 어떻게 바뀌었는지 쓰세요.","answer_guide":{"answer":"예: 가시를 가운데 두면 토리는 풀이 죽은 가시의 편이 되어 주는 친구, 부엉이 선생님은 음악회를 이끄는 선생님, 뭉치는 가시를 말렸다가 사과하는 친구이다. 뭉치는 처음에 가시가 북을 찢을까 봐 막았지만, 가시가 솔방울 장단으로 음악회를 살리자 사과하고 가시의 장단에 맞춰 노래하는 사이가 되었다.","scoring_points":["인물마다 가시와의 관계를 썼는가","관계가 바뀐 인물을 찾았는가","바뀐 모습을 썼는가"]},"explanation":["관계를 정리해요.","바뀐 인물을 찾아요.","어떻게 바뀌었는지 써요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#9','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C29',4,'essay','teacher','「빗속의 숲속 음악회」의 사건을 일어난 차례대로 쓰고, 흐름을 바꾼 사건이 무엇인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u6-C29","difficulty":4,"kind":"essay","stem":"「빗속의 숲속 음악회」의 사건을 일어난 차례대로 쓰고, 흐름을 바꾼 사건이 무엇인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 뭉치가 가시에게 북을 치지 말라고 했다 → 토리가 가시를 위로했다 → 비가 와서 북이 젖었다 → 가시가 솔방울로 장단을 쳤다 → 뭉치가 사과했다. 흐름을 바꾼 사건은 비가 와서 북이 젖은 일이다. 북을 칠 수 없게 되자 가시가 앞으로 나설 기회가 생겼기 때문이다.","scoring_points":["사건을 차례대로 썼는가","흐름을 바꾼 사건을 골랐는가","까닭을 썼는가"]},"explanation":["차례대로 써요.","바꾼 사건을 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L09_challenge#10','kor',5,2,'u6','L09','g5_2_kor_u6_L09_challenge','lesson_challenge','K5-2-u6-C32',4,'essay','teacher','「빗속의 숲속 음악회」에서 가장 인상적인 부분을 고르고, 대사나 지문을 근거로 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u6-C32","difficulty":4,"kind":"essay","stem":"「빗속의 숲속 음악회」에서 가장 인상적인 부분을 고르고, 대사나 지문을 근거로 까닭을 쓰세요.","answer_guide":{"answer":"예: 뭉치가 「(얼굴이 빨개져서) 가시야, 아까는 미안해.」라고 말하는 부분이 가장 인상적이다. 처음에 가시를 막았던 뭉치가 얼굴이 빨개질 만큼 쑥스러워하면서도 먼저 사과해서, 잘못을 인정하는 용기가 느껴졌기 때문이다.","scoring_points":["인상적인 부분을 골랐는가","대사나 지문을 근거로 들었는가","까닭을 썼는가"]},"explanation":["부분을 골라요.","근거를 들어요.","까닭을 써요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#1','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C33',1,'mc','auto','연극을 준비할 때 역할을 정하기 전에 먼저 살펴야 할 것은 무엇인가요?',ARRAY['K5-2-u6-X33']::text[],false,'{"seq":1,"concept":"K5-2-u6-C33","difficulty":1,"kind":"mc","stem":"연극을 준비할 때 역할을 정하기 전에 먼저 살펴야 할 것은 무엇인가요?","options":[{"t":"등장인물의 특징과 성격","correct":true},{"t":"관객의 수","mis":"K5-2-u6-X33"},{"t":"공연 날짜","mis":"K5-2-u6-X33"},{"t":"무대 바닥 색깔","mis":"K5-2-u6-X33"}],"explanation":["역할과 관계없어요.","역할과 관계없어요.","인물을 알아야 어울리는 역할을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#2','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C35',1,'mc','auto','「빗속의 숲속 음악회」를 공연하기 전에 준비해야 할 소품으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X35']::text[],false,'{"seq":2,"concept":"K5-2-u6-C35","difficulty":1,"kind":"mc","stem":"「빗속의 숲속 음악회」를 공연하기 전에 준비해야 할 소품으로 알맞은 것은 어느 것인가요?","options":[{"t":"북과 솔방울","correct":true},{"t":"우체통과 편지","mis":"K5-2-u6-X35"},{"t":"나룻배와 노","mis":"K5-2-u6-X35"},{"t":"종이배와 공책","mis":"K5-2-u6-X35"}],"explanation":["다른 극본의 소품이에요.","다른 이야기의 물건이에요.","극본에 나오는 물건을 챙겨요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#3','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C36',1,'ox','auto','연극에서는 대사를 하나도 틀리지 않고 외우는 것이 가장 중요해요.',ARRAY['K5-2-u6-X36']::text[],false,'{"seq":3,"concept":"K5-2-u6-C36","difficulty":1,"kind":"ox","stem":"연극에서는 대사를 하나도 틀리지 않고 외우는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"작품을 깊이 감상한 것을 인물의 마음이 드러나게 표현하는 것이 더 중요하기 때문에","correct":true},{"t":"대사를 하나라도 틀리면 연극을 처음부터 다시 해야 하기 때문에","mis":"K5-2-u6-X36"}],"mis":"K5-2-u6-X36","explanation":["외우기가 전부가 아니에요.","마음을 표현해요.","감상한 것을 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#4','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C37',1,'mc','auto','연극을 되돌아볼 때 기준으로 삼기 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X37']::text[],false,'{"seq":4,"concept":"K5-2-u6-C37","difficulty":1,"kind":"mc","stem":"연극을 되돌아볼 때 기준으로 삼기 알맞은 것은 어느 것인가요?","options":[{"t":"목소리, 몸짓, 협력","correct":true},{"t":"의상 값, 소품 값, 무대 크기","mis":"K5-2-u6-X37"},{"t":"관객 수, 박수 소리, 공연 시간","mis":"K5-2-u6-X37"},{"t":"대사 줄 수, 쪽수, 글자 수","mis":"K5-2-u6-X37"}],"explanation":["표현과 관계없어요.","표현과 관계없어요.","목소리·몸짓·협력을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#5','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C34',2,'mc','auto','「(얼굴이 빨개져서) 가시야, 아까는 미안해.」를 연기할 때 알맞은 모습은 어느 것인가요?',ARRAY['K5-2-u6-X34']::text[],false,'{"seq":5,"concept":"K5-2-u6-C34","difficulty":2,"kind":"mc","stem":"「(얼굴이 빨개져서) 가시야, 아까는 미안해.」를 연기할 때 알맞은 모습은 어느 것인가요?","options":[{"t":"얼굴을 붉히고 머리를 긁적이며 말한다","correct":true},{"t":"큰 소리로 화를 내며 말한다","mis":"K5-2-u6-X34"},{"t":"관객에게 등을 돌리고 노래한다","mis":"K5-2-u6-X34"},{"t":"웃음을 참지 못하고 크게 웃는다","mis":"K5-2-u6-X34"}],"explanation":["지문과 맞지 않아요.","지문과 맞지 않아요.","미안하고 쑥스러운 마음을 표현해요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#6','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C33',2,'mc','auto','연극을 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X33']::text[],false,'{"seq":6,"concept":"K5-2-u6-C33","difficulty":2,"kind":"mc","stem":"연극을 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"장면 정하기 → 역할 정하기 → 소품 준비하기 → 연습하기 → 점검하기","correct":true},{"t":"연습하기 → 장면 정하기 → 점검하기 → 역할 정하기 → 소품 준비하기","mis":"K5-2-u6-X33"},{"t":"점검하기 → 소품 준비하기 → 연습하기 → 장면 정하기 → 역할 정하기","mis":"K5-2-u6-X33"},{"t":"역할 정하기 → 점검하기 → 장면 정하기 → 연습하기 → 소품 준비하기","mis":"K5-2-u6-X33"}],"explanation":["장면부터 정해요.","점검은 맨 끝이에요.","정하기 → 준비 → 연습 → 점검이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#7','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C35',2,'mc','auto','연극하기 전에 점검할 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u6-X35']::text[],false,'{"seq":7,"concept":"K5-2-u6-C35","difficulty":2,"kind":"mc","stem":"연극하기 전에 점검할 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"다른 모둠의 대사를 다 외웠는지","correct":true},{"t":"소품이 잘 준비되었는지","mis":"K5-2-u6-X35"},{"t":"인물이 등장하는 순서를 아는지","mis":"K5-2-u6-X35"},{"t":"마지막 연습에서 흐름이 어색한 부분은 없는지","mis":"K5-2-u6-X35"}],"explanation":["꼭 점검해요.","꼭 점검해요.","다른 모둠의 대사는 외우지 않아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#8','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C34',2,'mc','auto','토리의 「솔방울 두드리는 네 장단, 나는 정말 좋던데.」를 표현하기에 가장 알맞은 목소리는 어느 것인가요?',ARRAY['K5-2-u6-X34']::text[],false,'{"seq":8,"concept":"K5-2-u6-C34","difficulty":2,"kind":"mc","stem":"토리의 「솔방울 두드리는 네 장단, 나는 정말 좋던데.」를 표현하기에 가장 알맞은 목소리는 어느 것인가요?","options":[{"t":"곁에서 다정하게 속삭이듯","correct":true},{"t":"씩씩하게 소리치듯","mis":"K5-2-u6-X34"},{"t":"화가 나서 쏘아붙이듯","mis":"K5-2-u6-X34"},{"t":"지루한 듯 하품하며","mis":"K5-2-u6-X34"}],"explanation":["위로하는 마음과 달라요.","위로하는 마음과 달라요.","어깨를 토닥이는 지문과 맞아요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#9','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C37',2,'mc','auto','모둠 연극에서 협력하는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X37']::text[],false,'{"seq":9,"concept":"K5-2-u6-C37","difficulty":2,"kind":"mc","stem":"모둠 연극에서 협력하는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"친구가 대사를 잊으면 다음 대사를 자연스럽게 이어 준다","correct":true},{"t":"잘하는 친구에게 중요한 역할을 모두 맡긴다","mis":"K5-2-u6-X37"},{"t":"실수한 친구를 탓한다","mis":"K5-2-u6-X37"},{"t":"내 대사만 연습하고 다른 친구는 신경 쓰지 않는다","mis":"K5-2-u6-X37"}],"explanation":["함께 나누어 맡아요.","서로 도와요.","대사를 이어 주는 것이 협력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_basic#10','kor',5,2,'u6','L11','g5_2_kor_u6_L11_basic','lesson_basic','K5-2-u6-C36',3,'mc','auto','두 모둠의 연극을 보았어요. 이 단원에서 배운 대로 더 좋은 연극이라고 할 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u6-X36','K5-2-u6-X37','K5-2-u6-X34']::text[],false,'{"seq":10,"concept":"K5-2-u6-C36","difficulty":3,"kind":"mc","stem":"두 모둠의 연극을 보았어요. 이 단원에서 배운 대로 더 좋은 연극이라고 할 수 있는 것은 어느 것인가요?","options":[{"t":"대사를 조금 바꾸어 말했지만 인물의 마음과 상황이 잘 전해진 연극","correct":true},{"t":"대사는 하나도 틀리지 않았지만 표정과 몸짓이 없었던 연극","mis":"K5-2-u6-X36"},{"t":"한 친구가 모든 역할을 혼자 맡은 연극","mis":"K5-2-u6-X37"},{"t":"관객을 등지고 대사만 빨리 말한 연극","mis":"K5-2-u6-X34"}],"explanation":["마음이 전해지지 않아요.","협력이 없어요.","감상한 마음이 전해졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#1','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C34',2,'ox','auto','같은 대사라도 인물의 성격이나 그 순간의 마음에 따라 목소리와 표정이 달라질 수 있어요.',ARRAY['K5-2-u6-X34']::text[],false,'{"seq":1,"concept":"K5-2-u6-C34","difficulty":2,"kind":"ox","stem":"같은 대사라도 인물의 성격이나 그 순간의 마음에 따라 목소리와 표정이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"인물의 성격과 지문, 그 순간의 마음이 표현을 정하기 때문에","correct":true},{"t":"대사가 같으면 누가 언제 해도 늘 같게 표현해야 하기 때문에","mis":"K5-2-u6-X34"}],"mis":"K5-2-u6-X34","explanation":["마음에 따라 달라요.","지문을 살펴요.","성격을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#2','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C33',2,'mc','auto','모둠에서 역할 다툼이 생겼을 때 먼저 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X33']::text[],false,'{"seq":2,"concept":"K5-2-u6-C33","difficulty":2,"kind":"mc","stem":"모둠에서 역할 다툼이 생겼을 때 먼저 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"인물의 특징을 함께 살펴보고 어울리는 역할을 이야기한다","correct":true},{"t":"목소리가 큰 친구가 원하는 역할을 맡는다","mis":"K5-2-u6-X33"},{"t":"인물은 살피지 않고 제비뽑기로 바로 정한다","mis":"K5-2-u6-X33"},{"t":"연극을 하지 않기로 한다","mis":"K5-2-u6-X33"}],"explanation":["모두의 생각을 들어요.","인물부터 살펴요.","인물 특징이 길잡이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#3','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C34',3,'mc','auto','뭉치의 첫 대사와 마지막 대사를 표현하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X34']::text[],false,'{"seq":3,"concept":"K5-2-u6-C34","difficulty":3,"kind":"mc","stem":"뭉치의 첫 대사와 마지막 대사를 표현하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"첫 대사는 북을 끌어안고 걱정스럽게, 마지막 대사는 얼굴을 붉히며 미안한 마음으로","correct":true},{"t":"두 대사 모두 같은 목소리로 크게","mis":"K5-2-u6-X34"},{"t":"첫 대사는 웃으며, 마지막 대사는 화를 내며","mis":"K5-2-u6-X34"},{"t":"두 대사 모두 관객을 등지고","mis":"K5-2-u6-X34"}],"explanation":["마음이 바뀌었어요.","지문과 반대예요.","지문과 마음의 변화를 살려요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#4','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C35',3,'error','auto','연극하기 전 점검표에 적힌 것이에요. 점검표에 어울리지 않는 것은 어느 것인가요?',ARRAY['K5-2-u6-X35']::text[],false,'{"seq":4,"concept":"K5-2-u6-C35","difficulty":3,"kind":"error","stem":"연극하기 전 점검표에 적힌 것이에요. 점검표에 어울리지 않는 것은 어느 것인가요?","options":[{"t":"「다른 모둠보다 박수를 더 받을 수 있는가?」","correct":true,"mis_target":"K5-2-u6-X35"},{"t":"「인물이 등장하는 순서를 알고 있는가?」","mis":"K5-2-u6-X35"},{"t":"「관객 쪽을 보며 또렷하게 말하는가?」","mis":"K5-2-u6-X35"}],"explanation":["꼭 살필 것이에요.","꼭 살필 것이에요.","겨루기는 점검할 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#5','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C37',3,'mc','auto','연극을 되돌아보며 나눈 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X37']::text[],false,'{"seq":5,"concept":"K5-2-u6-C37","difficulty":3,"kind":"mc","stem":"연극을 되돌아보며 나눈 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「지문대로 목소리를 바꾼 점이 좋았어. 다음에는 등장할 때 관객에게 등을 보이지 않게 하자.」","correct":true},{"t":"「다 엉망이었어. 다시는 안 할래.」","mis":"K5-2-u6-X37"},{"t":"「네가 틀려서 망쳤어.」","mis":"K5-2-u6-X37"},{"t":"「잘했어. 이제 끝!」","mis":"K5-2-u6-X37"}],"explanation":["잘한 점이 없어요.","친구를 탓했어요.","잘한 점과 나아질 점을 함께 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#6','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C36',3,'mc','auto','공연 중에 대사를 잊어버렸을 때 가장 알맞은 행동은 어느 것인가요?',ARRAY['K5-2-u6-X36','K5-2-u6-X37']::text[],false,'{"seq":6,"concept":"K5-2-u6-C36","difficulty":3,"kind":"mc","stem":"공연 중에 대사를 잊어버렸을 때 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"인물의 마음과 상황에 맞게 내 말로 바꾸어 이어 간다","correct":true},{"t":"공연을 멈추고 처음부터 다시 한다","mis":"K5-2-u6-X36"},{"t":"무대 밖으로 나가 버린다","mis":"K5-2-u6-X37"},{"t":"주머니에서 대본을 꺼내 읽는다","mis":"K5-2-u6-X36"}],"explanation":["흐름이 끊겨요.","친구들이 곤란해져요.","마음이 드러나면 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#7','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C33',3,'mc','auto','「빗속의 숲속 음악회」로 연극을 준비할 때, 역할을 정한 뒤 바로 다음에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X33']::text[],false,'{"seq":7,"concept":"K5-2-u6-C33","difficulty":3,"kind":"mc","stem":"「빗속의 숲속 음악회」로 연극을 준비할 때, 역할을 정한 뒤 바로 다음에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"북과 솔방울 같은 소품을 준비한다","correct":true},{"t":"바로 공연을 한다","mis":"K5-2-u6-X33"},{"t":"발표할 장면을 정한다","mis":"K5-2-u6-X33"},{"t":"연극을 되돌아본다","mis":"K5-2-u6-X33"}],"explanation":["연습과 점검이 남았어요.","장면은 먼저 정해요.","역할 다음은 소품 준비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#8','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C34',4,'essay','teacher','「빗속의 숲속 음악회」에서 한 인물을 맡는다면 그 인물의 성격을 쓰고, 대사 하나를 골라 지문과 성격을 살려 어떻게 표현할지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C34","difficulty":4,"kind":"essay","stem":"「빗속의 숲속 음악회」에서 한 인물을 맡는다면 그 인물의 성격을 쓰고, 대사 하나를 골라 지문과 성격을 살려 어떻게 표현할지 쓰세요.","answer_guide":{"answer":"예: 토리를 맡겠다. 토리는 친구의 마음을 잘 알아주는 다정한 성격이다. 「솔방울 두드리는 네 장단, 나는 정말 좋던데.」를 할 때 지문처럼 가시를 따라가 어깨를 토닥이며 다정하게 속삭이듯 말하고, 가시를 바라보며 웃어 주겠다.","scoring_points":["인물의 성격을 썼는가","대사를 골랐는가","지문과 성격을 살린 표현을 썼는가"]},"explanation":["성격을 써요.","대사를 골라요.","표현을 정해요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#9','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C36',4,'essay','teacher','「연극은 대사를 틀리지 않고 외워 보여 주는 것이 가장 중요하다.」라는 친구의 생각에 대한 내 생각을 이 단원에서 배운 것을 근거로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u6-C36","difficulty":4,"kind":"essay","stem":"「연극은 대사를 틀리지 않고 외워 보여 주는 것이 가장 중요하다.」라는 친구의 생각에 대한 내 생각을 이 단원에서 배운 것을 근거로 쓰세요.","answer_guide":{"answer":"예: 나는 친구의 생각과 조금 다르다. 연극은 작품을 깊이 감상한 것을 표현하는 것이기 때문이다. 대사를 다 외워도 표정과 목소리에 인물의 마음이 없으면 감동이 없다. 대사를 조금 바꾸더라도 인물의 마음과 상황이 잘 드러나고, 친구들과 협력해 끝까지 해내는 것이 더 중요하다.","scoring_points":["내 생각을 밝혔는가","배운 것을 근거로 들었는가","친구의 생각을 존중했는가"]},"explanation":["생각을 밝혀요.","근거를 들어요.","존중하며 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L11_challenge#10','kor',5,2,'u6','L11','g5_2_kor_u6_L11_challenge','lesson_challenge','K5-2-u6-C37',4,'essay','teacher','모둠 연극을 마친 뒤 목소리, 몸짓, 협력을 기준으로 잘한 점과 더 나아질 점을 하나씩 쓰고, 함께한 친구에게 고마운 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u6-C37","difficulty":4,"kind":"essay","stem":"모둠 연극을 마친 뒤 목소리, 몸짓, 협력을 기준으로 잘한 점과 더 나아질 점을 하나씩 쓰고, 함께한 친구에게 고마운 점을 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 지문대로 목소리를 바꾸어 뭉치의 미안한 마음이 잘 전해졌다. 더 나아질 점 — 뒷줄까지 들리게 더 크게 말하겠다. 고마운 점 — 내가 대사를 잊었을 때 토리를 맡은 친구가 자연스럽게 다음 대사를 이어 주어 고마웠다.","scoring_points":["잘한 점을 썼는가","더 나아질 점을 썼는가","고마운 점을 썼는가"]},"explanation":["잘한 점부터 써요.","나아질 점을 써요.","고마움을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#1','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C39',1,'mc','auto','「종이배에 실은 약속」에서 은별이가 마루에게 마음을 전한 방법은 무엇인가요?',ARRAY['K5-2-u6-X39']::text[],false,'{"seq":1,"concept":"K5-2-u6-C39","difficulty":1,"kind":"mc","stem":"「종이배에 실은 약속」에서 은별이가 마루에게 마음을 전한 방법은 무엇인가요?","options":[{"t":"종이배 안쪽에 「같이 놀래?」라고 적어 책상에 올려 두었다","correct":true},{"t":"마루에게 큰 소리로 말했다","mis":"K5-2-u6-X39"},{"t":"마루 할머니 댁에 편지를 보냈다","mis":"K5-2-u6-X39"},{"t":"칠판에 마루 이름을 적었다","mis":"K5-2-u6-X39"}],"explanation":["이야기에 없어요.","이야기에 없어요.","종이배에 쓴 말이 마음을 전했어요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#2','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C38',1,'mc','auto','답이 하나로 정해져 있지 않고 작품의 의미를 깊이 생각하게 하는 질문을 무엇이라고 하나요?',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":2,"concept":"K5-2-u6-C38","difficulty":1,"kind":"mc","stem":"답이 하나로 정해져 있지 않고 작품의 의미를 깊이 생각하게 하는 질문을 무엇이라고 하나요?","options":[{"t":"감상 질문","correct":true},{"t":"내용 확인 질문","mis":"K5-2-u6-X38"},{"t":"받아쓰기 문제","mis":"K5-2-u6-X38"},{"t":"퀴즈 문제","mis":"K5-2-u6-X38"}],"explanation":["답이 글에 쓰여 있어요.","감상과 관계없어요.","의미를 묻는 것이 감상 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#3','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C39',1,'mc','auto','「종이배에 실은 약속」의 배경에 대한 감상 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X39']::text[],false,'{"seq":3,"concept":"K5-2-u6-C39","difficulty":1,"kind":"mc","stem":"「종이배에 실은 약속」의 배경에 대한 감상 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"이야기가 강가 마을이라서 달라진 것은 무엇일까?","correct":true},{"t":"은별이가 종이배를 접은 까닭은 무엇일까?","mis":"K5-2-u6-X39"},{"t":"두 종이배가 하나로 겹쳐진 일은 어떤 의미일까?","mis":"K5-2-u6-X39"},{"t":"마루가 강물만 바라본 까닭은 무엇일까?","mis":"K5-2-u6-X39"}],"explanation":["인물에 대한 질문이에요.","사건에 대한 질문이에요.","곳을 묻는 배경 질문이에요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#4','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C40',1,'mc','auto','친구와 묻고 답하며 감상을 나눌 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u6-X40']::text[],false,'{"seq":4,"concept":"K5-2-u6-C40","difficulty":1,"kind":"mc","stem":"친구와 묻고 답하며 감상을 나눌 때 알맞은 태도는 어느 것인가요?","options":[{"t":"이야기 속 근거를 들어 답하고 친구의 다른 생각도 끝까지 듣는다","correct":true},{"t":"내 답과 다르면 친구의 말을 끊는다","mis":"K5-2-u6-X40"},{"t":"정답 하나를 정해 모두 따르게 한다","mis":"K5-2-u6-X40"},{"t":"근거 없이 느낌만 짧게 말한다","mis":"K5-2-u6-X40"}],"explanation":["끝까지 들어요.","답은 여럿일 수 있어요.","근거를 들고 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#5','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C38',2,'ox','auto','감상 질문은 이야기에 답이 그대로 쓰여 있는 것을 묻는 것이 좋아요.',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":5,"concept":"K5-2-u6-C38","difficulty":2,"kind":"ox","stem":"감상 질문은 이야기에 답이 그대로 쓰여 있는 것을 묻는 것이 좋아요.","answer":"X","reason_options":[{"t":"답이 그대로 쓰인 질문은 내용 확인에 그치고, 마음·의미·영향을 묻는 질문이 감상을 깊게 하기 때문에","correct":true},{"t":"답이 하나로 정해져야 좋은 질문이기 때문에","mis":"K5-2-u6-X38"}],"mis":"K5-2-u6-X38","explanation":["확인 질문이에요.","답이 여럿이어도 돼요.","의미를 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#6','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C39',2,'match','auto','감상 질문과 이야기의 구성 요소를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u6-C39","difficulty":2,"kind":"match","stem":"감상 질문과 이야기의 구성 요소를 알맞게 이으세요.","pairs":[{"l":"은별이가 「같이 놀래?」라고 적은 까닭은 무엇일까?","r":"인물"},{"l":"두 종이배가 하나로 겹쳐진 일은 어떤 의미일까?","r":"사건"},{"l":"장마가 그친 여름이라는 때는 어떤 느낌을 줄까?","r":"배경"}],"mis":"K5-2-u6-X39","explanation":["인물의 마음이에요.","일어난 일이에요.","때와 곳이에요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#7','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C38',2,'mc','auto','다음 가운데 감상 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":7,"concept":"K5-2-u6-C38","difficulty":2,"kind":"mc","stem":"다음 가운데 감상 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마루가 쉬는 시간마다 강물만 바라본 까닭은 무엇일까?","correct":true},{"t":"마루는 어디에서 전학 왔나요?","mis":"K5-2-u6-X38"},{"t":"은별이는 종이배에 무엇이라고 적었나요?","mis":"K5-2-u6-X38"},{"t":"종이배는 다리 밑에서 어떻게 되었나요?","mis":"K5-2-u6-X38"}],"explanation":["답이 글에 있어요.","답이 글에 있어요.","마음을 깊이 생각하게 해요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#8','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C41',2,'mc','auto','감상 활동을 함께 정하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X41']::text[],false,'{"seq":8,"concept":"K5-2-u6-C41","difficulty":2,"kind":"mc","stem":"감상 활동을 함께 정하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 활동을 견주어 보고 반 친구 모두의 의견을 들어 정한다","correct":true},{"t":"목소리가 큰 친구의 의견대로 정한다","mis":"K5-2-u6-X41"},{"t":"감상과 관계없는 체육 놀이를 고른다","mis":"K5-2-u6-X41"},{"t":"아무것도 정하지 않고 저마다 아무 일이나 한다","mis":"K5-2-u6-X41"}],"explanation":["모두의 의견을 들어요.","감상 활동을 골라요.","함께 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#9','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C40',2,'mc','auto','묻고 답하며 감상을 나눈 뒤 하면 좋은 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X40']::text[],false,'{"seq":9,"concept":"K5-2-u6-C40","difficulty":2,"kind":"mc","stem":"묻고 답하며 감상을 나눈 뒤 하면 좋은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"나누기 전과 뒤에 달라진 내 감상을 적어 본다","correct":true},{"t":"친구 답 가운데 틀린 것을 세어 본다","mis":"K5-2-u6-X40"},{"t":"내 답이 맞았는지만 확인한다","mis":"K5-2-u6-X40"},{"t":"질문 카드를 모두 버린다","mis":"K5-2-u6-X40"}],"explanation":["틀린 답을 찾는 활동이 아니에요.","맞고 틀림을 따지지 않아요.","달라진 감상을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_basic#10','kor',5,2,'u6','L13','g5_2_kor_u6_L13_basic','lesson_basic','K5-2-u6-C40',3,'mc','auto','「두 종이배가 다리 밑에서 하나로 겹쳐진 일은 어떤 의미일까?」에 근거를 들어 답한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X40','K5-2-u6-X38']::text[],false,'{"seq":10,"concept":"K5-2-u6-C40","difficulty":3,"kind":"mc","stem":"「두 종이배가 다리 밑에서 하나로 겹쳐진 일은 어떤 의미일까?」에 근거를 들어 답한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 아이가 서로 마음을 열고 친구가 되었다는 뜻 같아. 가을에 함께 접은 종이배가 창가에 줄지어 놓였으니까.","correct":true},{"t":"종이배가 물에 젖어 망가졌다는 뜻이야. 다른 까닭은 없어.","mis":"K5-2-u6-X40"},{"t":"그냥 다리가 낮았다는 뜻이야.","mis":"K5-2-u6-X40"},{"t":"답이 이야기에 쓰여 있지 않으니 알 수 없어.","mis":"K5-2-u6-X38"}],"explanation":["근거가 없어요.","의미를 생각하지 않았어요.","이야기 속 근거를 들었어요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#1','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C40',2,'ox','auto','같은 이야기도 친구마다 다르게 감상할 수 있어요.',ARRAY['K5-2-u6-X40']::text[],false,'{"seq":1,"concept":"K5-2-u6-C40","difficulty":2,"kind":"ox","stem":"같은 이야기도 친구마다 다르게 감상할 수 있어요.","answer":"O","reason_options":[{"t":"저마다의 경험과 생각에 따라 이야기에서 발견하는 의미가 다를 수 있기 때문에","correct":true},{"t":"이야기에는 감상이 하나로 정해져 있기 때문에","mis":"K5-2-u6-X40"}],"mis":"K5-2-u6-X40","explanation":["감상은 여럿이에요.","근거를 들어 나눠요.","서로 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#2','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C39',2,'mc','auto','「종이배에 실은 약속」의 인물에 대한 감상 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X39','K5-2-u6-X38']::text[],false,'{"seq":2,"concept":"K5-2-u6-C39","difficulty":2,"kind":"mc","stem":"「종이배에 실은 약속」의 인물에 대한 감상 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"은별이가 말 대신 종이배에 마음을 적은 까닭은 무엇일까?","correct":true},{"t":"강가 마을이라는 곳은 이야기에 어떤 느낌을 줄까?","mis":"K5-2-u6-X39"},{"t":"장마가 그친 여름이라는 때는 어떤 느낌을 줄까?","mis":"K5-2-u6-X39"},{"t":"이 책은 몇 쪽일까?","mis":"K5-2-u6-X38"}],"explanation":["배경에 대한 질문이에요.","배경에 대한 질문이에요.","인물의 마음을 물어요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#3','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C38',3,'error','auto','친구들이 만든 질문이에요. 감상 질문이라고 하기 어려운 것은 어느 것인가요?',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":3,"concept":"K5-2-u6-C38","difficulty":3,"kind":"error","stem":"친구들이 만든 질문이에요. 감상 질문이라고 하기 어려운 것은 어느 것인가요?","options":[{"t":"「마루는 어디에서 전학 왔을까?」","correct":true,"mis_target":"K5-2-u6-X38"},{"t":"「마루가 강물이 어디까지 가는지 물은 까닭은 무엇일까?」","mis":"K5-2-u6-X38"},{"t":"「가을 창가에 줄지어 놓인 종이배들은 무엇을 말해 줄까?」","mis":"K5-2-u6-X38"}],"explanation":["의미를 묻는 질문이에요.","의미를 묻는 질문이에요.","답이 글에 그대로 있어요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#4','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C40',3,'mc','auto','「마루는 처음에 어떤 마음이었을까?」에 대한 두 친구의 답이 달라요. 가장 알맞은 반응은 어느 것인가요?',ARRAY['K5-2-u6-X40','K5-2-u6-X38']::text[],false,'{"seq":4,"concept":"K5-2-u6-C40","difficulty":3,"kind":"mc","stem":"「마루는 처음에 어떤 마음이었을까?」에 대한 두 친구의 답이 달라요. 가장 알맞은 반응은 어느 것인가요?","options":[{"t":"「둘 다 이야기 속 근거가 있으니 함께 견주어 보자.」","correct":true},{"t":"「둘 중 하나는 틀렸어.」","mis":"K5-2-u6-X40"},{"t":"「근거는 필요 없어. 느낌대로 말하면 돼.」","mis":"K5-2-u6-X40"},{"t":"「선생님이 정답을 알려 주실 때까지 기다리자.」","mis":"K5-2-u6-X38"}],"explanation":["둘 다 근거가 있어요.","근거는 꼭 있어야 해요.","견주어 보며 감상을 넓혀요."],"asset":{"type":"speech","turns":[{"who":"하린","text":"마루는 외로웠을 것 같아. 쉬는 시간마다 혼자 강물만 바라봤잖아."},{"who":"지후","text":"나는 마루가 살던 곳이 그리웠을 것 같아. 도시에서 막 전학 왔잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#5','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C39',3,'mc','auto','배경에 대한 감상 질문을 하나 더 만들려고 해요. 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X39']::text[],false,'{"seq":5,"concept":"K5-2-u6-C39","difficulty":3,"kind":"mc","stem":"배경에 대한 감상 질문을 하나 더 만들려고 해요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이야기가 도시였다면 두 아이는 무엇으로 마음을 나누었을까?","correct":true},{"t":"은별이는 종이배를 몇 번 접었을까?","mis":"K5-2-u6-X39"},{"t":"마루의 짝은 누구일까?","mis":"K5-2-u6-X39"},{"t":"은별이는 왜 마루에게 먼저 다가갔을까?","mis":"K5-2-u6-X39"}],"explanation":["답이 글에 없거나 사실 확인이에요.","사실 확인이에요.","곳이 바뀌면 어떨지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#6','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C41',3,'mc','auto','감상 질문 잔치를 반 전체로 하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X41']::text[],false,'{"seq":6,"concept":"K5-2-u6-C41","difficulty":3,"kind":"mc","stem":"감상 질문 잔치를 반 전체로 하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 친구의 다양한 답을 한꺼번에 들어 감상을 넓힐 수 있다","correct":true},{"t":"질문을 만들지 않아도 된다","mis":"K5-2-u6-X41"},{"t":"한 사람의 답만 들으면 된다","mis":"K5-2-u6-X41"},{"t":"이야기를 읽지 않아도 된다","mis":"K5-2-u6-X41"}],"explanation":["질문은 저마다 만들어요.","여러 답을 들어요.","다양한 답이 감상을 넓혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#7','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C38',3,'mc','auto','감상 질문을 「왜?」나 「어떤 의미일까?」로 만들면 좋은 까닭은 무엇인가요?',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":7,"concept":"K5-2-u6-C38","difficulty":3,"kind":"mc","stem":"감상 질문을 「왜?」나 「어떤 의미일까?」로 만들면 좋은 까닭은 무엇인가요?","options":[{"t":"친구마다 다른 답이 나와 작품의 의미를 깊이 생각하게 되기 때문에","correct":true},{"t":"답이 하나로 정해져 채점하기 쉽기 때문에","mis":"K5-2-u6-X38"},{"t":"이야기를 읽지 않아도 답할 수 있기 때문에","mis":"K5-2-u6-X38"},{"t":"질문이 짧아지기 때문에","mis":"K5-2-u6-X38"}],"explanation":["답이 여럿이어도 돼요.","이야기가 근거예요.","의미를 생각하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#8','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C39',4,'essay','teacher','「종이배에 실은 약속」을 읽고 인물, 사건, 배경에 대한 감상 질문을 하나씩 만들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u6-C39","difficulty":4,"kind":"essay","stem":"「종이배에 실은 약속」을 읽고 인물, 사건, 배경에 대한 감상 질문을 하나씩 만들어 쓰세요.","answer_guide":{"answer":"예: 인물 — 마루는 종이배를 받았을 때 어떤 마음이었을까? 사건 — 두 아이가 종이배를 강물에 함께 띄운 일은 어떤 의미일까? 배경 — 장마가 그친 여름 강가라는 배경은 두 아이의 만남에 어떤 느낌을 줄까?","scoring_points":["인물 질문을 만들었는가","사건·배경 질문을 만들었는가","답이 여럿일 수 있는 질문인가"]},"explanation":["인물을 물어요.","사건과 배경을 물어요.","의미를 물어요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#9','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C40',4,'essay','teacher','내가 만든 감상 질문 하나를 골라 이야기 속 근거를 들어 답을 쓰고, 친구가 다르게 답한다면 어떻게 들을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u6-C40","difficulty":4,"kind":"essay","stem":"내가 만든 감상 질문 하나를 골라 이야기 속 근거를 들어 답을 쓰고, 친구가 다르게 답한다면 어떻게 들을지 쓰세요.","answer_guide":{"answer":"예: 질문 — 마루는 종이배를 받았을 때 어떤 마음이었을까? 답 — 반갑고 고마웠을 것 같다. 방과 후에 종이배를 들고 강가로 나가 은별이에게 먼저 말을 걸었기 때문이다. 친구가 「부끄러웠을 것 같다.」라고 답하면 어떤 장면을 근거로 했는지 끝까지 듣고, 내 생각과 견주어 보겠다.","scoring_points":["질문을 골랐는가","근거를 들어 답했는가","다른 답을 듣는 태도를 썼는가"]},"explanation":["질문을 골라요.","근거를 들어 답해요.","끝까지 들어요."],"asset":{"type":"passage","lines":["장마가 그친 여름, 강가 마을 학교에 도시에서 마루가 전학 왔어요.","마루는 쉬는 시간마다 창밖 강물만 바라보았어요.","짝 은별이는 공책을 찢어 종이배를 접고, 배 안쪽에 「같이 놀래?」라고 적었어요.","은별이는 종이배를 마루 책상에 살며시 올려 두었지요.","방과 후, 마루는 종이배를 들고 강가로 나갔어요. 「이 강물은 어디까지 가?」","「바다까지 가. 우리 할머니 댁 앞까지.」 두 아이는 종이배를 접어 강물에 띄웠어요.","종이배 두 척은 나란히 떠내려가다가 다리 밑에서 하나로 겹쳐졌어요.","가을이 되자, 마루의 창가에는 은별이와 함께 접은 종이배가 줄지어 놓였어요."],"title":"종이배에 실은 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_L13_challenge#10','kor',5,2,'u6','L13','g5_2_kor_u6_L13_challenge','lesson_challenge','K5-2-u6-C41',4,'essay','teacher','우리 반이 작품의 구성 요소를 생각하며 감상하는 활동을 한다면 어떤 활동을 어떤 방법(반 전체·모둠·짝·혼자)으로 하고 싶은지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u6-C41","difficulty":4,"kind":"essay","stem":"우리 반이 작품의 구성 요소를 생각하며 감상하는 활동을 한다면 어떤 활동을 어떤 방법(반 전체·모둠·짝·혼자)으로 하고 싶은지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 인상 깊은 장면을 그려 까닭을 붙이는 장면 그림 전시를 모둠으로 하고 싶다. 모둠 친구들이 같은 이야기에서 서로 다른 장면을 고르면, 그림을 보며 인물의 마음과 배경을 이야기 나누면서 감상을 넓힐 수 있기 때문이다.","scoring_points":["활동을 골랐는가","방법을 정했는가","까닭을 썼는가"]},"explanation":["활동을 골라요.","방법을 정해요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#1','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C5',1,'mc','auto','이야기의 구성 요소 가운데 어떤 일을 겪는 사람이나 사물을 가리키는 것은 어느 것인가요?',ARRAY['K5-2-u6-X05']::text[],false,'{"seq":1,"concept":"K5-2-u6-C5","difficulty":1,"kind":"mc","stem":"이야기의 구성 요소 가운데 어떤 일을 겪는 사람이나 사물을 가리키는 것은 어느 것인가요?","options":[{"t":"인물","correct":true},{"t":"배경","mis":"K5-2-u6-X05"},{"t":"사건","mis":"K5-2-u6-X05"},{"t":"대사","mis":"K5-2-u6-X05"}],"explanation":["때와 곳이에요.","일어나는 일이에요.","일을 겪는 쪽이 인물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#2','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C21',1,'mc','auto','극본에서 때, 곳, 등장인물, 무대 배경 같은 것을 설명하는 부분은 어느 것인가요?',ARRAY['K5-2-u6-X21']::text[],false,'{"seq":2,"concept":"K5-2-u6-C21","difficulty":1,"kind":"mc","stem":"극본에서 때, 곳, 등장인물, 무대 배경 같은 것을 설명하는 부분은 어느 것인가요?","options":[{"t":"해설","correct":true},{"t":"대사","mis":"K5-2-u6-X21"},{"t":"지문","mis":"K5-2-u6-X21"},{"t":"제목","mis":"K5-2-u6-X21"}],"explanation":["인물이 하는 말이에요.","괄호 속 안내예요.","첫 부분의 설명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#3','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C42',1,'mc','auto','「할머니께서 아프십니다.」를 높임 어휘를 써서 바르게 고친 것은 어느 것인가요?',ARRAY['K5-2-u6-X42']::text[],false,'{"seq":3,"concept":"K5-2-u6-C42","difficulty":1,"kind":"mc","stem":"「할머니께서 아프십니다.」를 높임 어휘를 써서 바르게 고친 것은 어느 것인가요?","options":[{"t":"할머니께서 편찮으십니다.","correct":true},{"t":"할머니께서 아프시겠습니다.","mis":"K5-2-u6-X42"},{"t":"할머니께서 아프셨습니다.","mis":"K5-2-u6-X42"},{"t":"할머니께서 아파하십니다.","mis":"K5-2-u6-X42"}],"explanation":["높임 어휘가 아니에요.","높임 어휘가 아니에요.","높임 어휘 「편찮으시다」를 먼저 써요."],"asset":{"type":"passage","lines":["할머니께서 아프십니다. → 할머니께서 편찮으십니다.","할아버지께서는 고민이 계십니다. → 할아버지께서는 고민이 있으십니다.","교장 선생님께서 교장실에 있으십니다. → 교장 선생님께서 교장실에 계십니다.","교장 선생님의 말씀이 계시겠습니다. → 교장 선생님의 말씀이 있으시겠습니다."],"title":"높임 표현 바르게 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#4','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C9',1,'mc','auto','「골목 끝 수선집」의 공간적 배경은 어느 것인가요?',ARRAY['K5-2-u6-X09']::text[],false,'{"seq":4,"concept":"K5-2-u6-C9","difficulty":1,"kind":"mc","stem":"「골목 끝 수선집」의 공간적 배경은 어느 것인가요?","options":[{"t":"시장 골목 끝의 작은 신발 수선집","correct":true},{"t":"눈이 펑펑 내리던 겨울","mis":"K5-2-u6-X09"},{"t":"달리기 대회 날","mis":"K5-2-u6-X09"},{"t":"다음 날 아침","mis":"K5-2-u6-X09"}],"explanation":["때예요.","때예요.","어디에서인지가 공간적 배경이에요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#5','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C26',1,'mc','auto','「도서관의 마지막 손님」의 해설을 보고 떠올릴 수 있는 무대는 어느 것인가요?',ARRAY['K5-2-u6-X26']::text[],false,'{"seq":5,"concept":"K5-2-u6-C26","difficulty":1,"kind":"mc","stem":"「도서관의 마지막 손님」의 해설을 보고 떠올릴 수 있는 무대는 어느 것인가요?","options":[{"t":"불빛이 하나둘 꺼지는 책장 사이와 빗방울 맺힌 창문","correct":true},{"t":"햇빛이 쏟아지는 운동장","mis":"K5-2-u6-X26"},{"t":"눈 덮인 산골 우체국","mis":"K5-2-u6-X26"},{"t":"숲속 빈터의 나무 무대","mis":"K5-2-u6-X26"}],"explanation":["해설과 달라요.","다른 극본이에요.","해설로 무대를 떠올려요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#6','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C33',1,'mc','auto','연극 준비에서 공연 바로 전, 맨 마지막에 하는 일은 어느 것인가요?',ARRAY['K5-2-u6-X33']::text[],false,'{"seq":6,"concept":"K5-2-u6-C33","difficulty":1,"kind":"mc","stem":"연극 준비에서 공연 바로 전, 맨 마지막에 하는 일은 어느 것인가요?","options":[{"t":"점검하기","correct":true},{"t":"장면 정하기","mis":"K5-2-u6-X33"},{"t":"역할 정하기","mis":"K5-2-u6-X33"},{"t":"소품 준비하기","mis":"K5-2-u6-X33"}],"explanation":["맨 처음이에요.","앞에서 해요.","공연 전에 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#7','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C38',1,'mc','auto','감상 질문에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":7,"concept":"K5-2-u6-C38","difficulty":1,"kind":"mc","stem":"감상 질문에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"답이 하나로 정해져 있지 않고 작품의 의미를 생각하게 한다","correct":true},{"t":"답이 이야기에 그대로 쓰여 있다","mis":"K5-2-u6-X38"},{"t":"정답이 하나뿐이다","mis":"K5-2-u6-X38"},{"t":"책 제목만 물어본다","mis":"K5-2-u6-X38"}],"explanation":["확인 질문이에요.","답은 여럿일 수 있어요.","의미를 생각하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#8','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C17',1,'mc','auto','「도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.」에서 「들뜨다」의 뜻은 어느 것인가요?',ARRAY['K5-2-u6-X17']::text[],false,'{"seq":8,"concept":"K5-2-u6-C17","difficulty":1,"kind":"mc","stem":"「도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.」에서 「들뜨다」의 뜻은 어느 것인가요?","options":[{"t":"마음이 가라앉지 아니하고 조금 흥분되다","correct":true},{"t":"마음이 차분하게 가라앉다","mis":"K5-2-u6-X17"},{"t":"몸이 아파 힘이 없다","mis":"K5-2-u6-X17"},{"t":"화가 나서 얼굴이 붉어지다","mis":"K5-2-u6-X17"}],"explanation":["뜻과 반대예요.","뜻이 달라요.","설레어 가라앉지 않는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#9','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C13',2,'mc','auto','「골목 끝 수선집」에서 사건에 따라 바뀐 서준이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X13']::text[],false,'{"seq":9,"concept":"K5-2-u6-C13","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」에서 사건에 따라 바뀐 서준이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"쭈뼛쭈뼛 걱정하던 마음 → 밑창의 글씨에 힘을 얻은 마음","correct":true},{"t":"처음부터 끝까지 신나는 마음","mis":"K5-2-u6-X13"},{"t":"기쁜 마음 → 화난 마음","mis":"K5-2-u6-X13"},{"t":"힘을 얻은 마음 → 쭈뼛쭈뼛 걱정하던 마음","mis":"K5-2-u6-X13"}],"explanation":["마음이 바뀌었어요.","이야기와 달라요.","사건에 따라 마음이 바뀌었어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#10','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C21',2,'mc','auto','「도서관의 마지막 손님」의 해설에서 알 수 없는 것은 어느 것인가요?',ARRAY['K5-2-u6-X21']::text[],false,'{"seq":10,"concept":"K5-2-u6-C21","difficulty":2,"kind":"mc","stem":"「도서관의 마지막 손님」의 해설에서 알 수 없는 것은 어느 것인가요?","options":[{"t":"지안이가 책을 품에 안을 때의 마음","correct":true},{"t":"비 오는 토요일 저녁이라는 때","mis":"K5-2-u6-X21"},{"t":"동네 작은 도서관이라는 곳","mis":"K5-2-u6-X21"},{"t":"지안과 사서 선생님이 나온다는 것","mis":"K5-2-u6-X21"}],"explanation":["해설에 있어요.","해설에 있어요.","마음은 대사와 지문에서 드러나요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#11','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C42',2,'error','auto','높임 표현을 쓴 문장이에요. 바르지 않은 것은 어느 것인가요?',ARRAY['K5-2-u6-X42','K5-2-u6-X43']::text[],false,'{"seq":11,"concept":"K5-2-u6-C42","difficulty":2,"kind":"error","stem":"높임 표현을 쓴 문장이에요. 바르지 않은 것은 어느 것인가요?","options":[{"t":"「할아버지께서 방에 있으십니다.」","correct":true,"mis_target":"K5-2-u6-X42"},{"t":"「할머니께서 편찮으십니다.」","mis":"K5-2-u6-X42"},{"t":"「아버지께서는 걱정이 있으십니다.」","mis":"K5-2-u6-X43"}],"explanation":["높임 어휘를 썼어요.","밀접한 대상이라 바르게 썼어요.","어른을 직접 높일 때는 「계십니다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#12','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C7',2,'match','auto','「골목 끝 수선집」의 구성 요소와 알맞은 내용을 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K5-2-u6-C7","difficulty":2,"kind":"match","stem":"「골목 끝 수선집」의 구성 요소와 알맞은 내용을 이으세요.","pairs":[{"l":"인물","r":"서준, 수선집 할아버지"},{"l":"사건","r":"할아버지가 운동화 밑창을 고쳐 주었다"},{"l":"배경","r":"눈 내리는 겨울, 시장 골목 끝 수선집"}],"mis":"K5-2-u6-X07","explanation":["일을 겪는 사람들이에요.","일어난 일이에요.","때와 곳이에요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#13','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C38',2,'mc','auto','「골목 끝 수선집」을 읽고 만든 질문 가운데 감상 질문은 어느 것인가요?',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":13,"concept":"K5-2-u6-C38","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」을 읽고 만든 질문 가운데 감상 질문은 어느 것인가요?","options":[{"t":"「끝까지」라는 글씨는 서준이에게 어떤 의미였을까?","correct":true},{"t":"서준이의 운동화는 어디가 떨어졌나요?","mis":"K5-2-u6-X38"},{"t":"수선집은 어디에 있나요?","mis":"K5-2-u6-X38"},{"t":"할아버지는 안경을 어디에 걸쳤나요?","mis":"K5-2-u6-X38"}],"explanation":["답이 글에 있어요.","답이 글에 있어요.","의미를 물어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#14','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C36',2,'mc','auto','연극을 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X36','K5-2-u6-X37']::text[],false,'{"seq":14,"concept":"K5-2-u6-C36","difficulty":2,"kind":"mc","stem":"연극을 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작품을 깊이 감상한 것을 목소리와 몸짓으로 표현하려고","correct":true},{"t":"대사를 얼마나 잘 외웠는지 자랑하려고","mis":"K5-2-u6-X36"},{"t":"다른 모둠과 박수 수를 겨루려고","mis":"K5-2-u6-X37"},{"t":"글을 읽지 않아도 되게 하려고","mis":"K5-2-u6-X36"}],"explanation":["외우기가 목적이 아니에요.","겨루기가 아니에요.","감상한 것을 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#15','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C24',2,'ox','auto','같은 이야기라도 이야기 글과 극본은 쓰는 모양과 목적이 달라요.',ARRAY['K5-2-u6-X24']::text[],false,'{"seq":15,"concept":"K5-2-u6-C24","difficulty":2,"kind":"ox","stem":"같은 이야기라도 이야기 글과 극본은 쓰는 모양과 목적이 달라요.","answer":"O","reason_options":[{"t":"이야기 글은 읽는 사람에게 줄글로 들려주고, 극본은 공연하려고 대사와 지문으로 쓰기 때문에","correct":true},{"t":"극본은 이야기 글을 짧게 줄인 것일 뿐이기 때문에","mis":"K5-2-u6-X24"}],"mis":"K5-2-u6-X24","explanation":["모양이 달라요.","목적이 달라요.","쓰임에 맞게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#16','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C10',2,'mc','auto','「서준이는 마지막 바퀴에서 넘어질 뻔했지만 다시 달렸어요.」로 짐작할 수 있는 서준이의 성격은 어느 것인가요?',ARRAY['K5-2-u6-X10']::text[],false,'{"seq":16,"concept":"K5-2-u6-C10","difficulty":2,"kind":"mc","stem":"「서준이는 마지막 바퀴에서 넘어질 뻔했지만 다시 달렸어요.」로 짐작할 수 있는 서준이의 성격은 어느 것인가요?","options":[{"t":"쉽게 포기하지 않는다","correct":true},{"t":"겁이 많아 금방 포기한다","mis":"K5-2-u6-X10"},{"t":"남을 잘 놀린다","mis":"K5-2-u6-X10"},{"t":"게으르다","mis":"K5-2-u6-X10"}],"explanation":["행동과 반대예요.","행동과 관계없어요.","다시 달린 행동이 근거예요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#17','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C14',3,'mc','auto','「골목 끝 수선집」의 배경이 맑은 봄날 큰 신발 가게였다면 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X14']::text[],false,'{"seq":17,"concept":"K5-2-u6-C14","difficulty":3,"kind":"mc","stem":"「골목 끝 수선집」의 배경이 맑은 봄날 큰 신발 가게였다면 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"눈길을 헤치고 찾아간 서준이의 간절함과 작은 수선집의 따뜻함이 덜 느껴졌을 것이다","correct":true},{"t":"배경이 바뀌어도 느낌은 조금도 달라지지 않는다","mis":"K5-2-u6-X14"},{"t":"서준이가 달리기 대회에 나가지 않았을 것이다","mis":"K5-2-u6-X14"},{"t":"할아버지가 더 많은 말을 했을 것이다","mis":"K5-2-u6-X14"}],"explanation":["배경이 느낌을 바꿔요.","근거가 없어요.","배경과 마음이 이어져 있어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#18','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C21',3,'error','auto','「도서관의 마지막 손님」에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u6-X21','K5-2-u6-X23']::text[],false,'{"seq":18,"concept":"K5-2-u6-C21","difficulty":3,"kind":"error","stem":"「도서관의 마지막 손님」에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「해설을 보면 지안이가 얼마나 간절한지 알 수 있어.」","correct":true,"mis_target":"K5-2-u6-X21"},{"t":"「해설로 비 오는 저녁 도서관이라는 것을 알 수 있어.」","mis":"K5-2-u6-X21"},{"t":"「지문을 보면 선생님이 지안이 마음을 알아준 게 보여.」","mis":"K5-2-u6-X23"}],"explanation":["바른 말이에요.","바른 말이에요.","간절함은 대사와 지문에서 보여요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#19','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C43',3,'mc','auto','「계시다」와 「있으시다」를 바르게 가른 것은 어느 것인가요?',ARRAY['K5-2-u6-X43','K5-2-u6-X42']::text[],false,'{"seq":19,"concept":"K5-2-u6-C43","difficulty":3,"kind":"mc","stem":"「계시다」와 「있으시다」를 바르게 가른 것은 어느 것인가요?","options":[{"t":"어른이 어디에 있음을 높일 때는 「계시다」, 어른의 말씀·고민을 높일 때는 「있으시다」","correct":true},{"t":"둘은 언제나 바꾸어 써도 된다","mis":"K5-2-u6-X43"},{"t":"어른에게는 「있으시다」만 쓴다","mis":"K5-2-u6-X42"},{"t":"말씀·고민에는 「계시다」, 어른이 있는 곳에는 「있으시다」","mis":"K5-2-u6-X43"}],"explanation":["쓰임이 달라요.","직접 높일 때는 「계시다」예요.","주어가 누구인지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#20','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C39',3,'mc','auto','「골목 끝 수선집」의 배경에 대한 감상 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X39','K5-2-u6-X38']::text[],false,'{"seq":20,"concept":"K5-2-u6-C39","difficulty":3,"kind":"mc","stem":"「골목 끝 수선집」의 배경에 대한 감상 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"눈 펑펑 내리는 겨울 시장 골목이라는 배경은 이야기에 어떤 느낌을 줄까?","correct":true},{"t":"할아버지는 왜 글씨를 새겼을까?","mis":"K5-2-u6-X39"},{"t":"서준이는 왜 다시 달렸을까?","mis":"K5-2-u6-X39"},{"t":"수선집 유리문은 무슨 색일까?","mis":"K5-2-u6-X38"}],"explanation":["인물에 대한 질문이에요.","인물에 대한 질문이에요.","때와 곳을 물어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#21','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C30',3,'mc','auto','역할 수행 학습의 실연하기에서 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X30']::text[],false,'{"seq":21,"concept":"K5-2-u6-C30","difficulty":3,"kind":"mc","stem":"역할 수행 학습의 실연하기에서 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"맡은 역할이 되어 극본을 낭독하거나 연기한다","correct":true},{"t":"학습 문제를 확인한다","mis":"K5-2-u6-X30"},{"t":"사건 차례를 정리한다","mis":"K5-2-u6-X30"},{"t":"인상적인 부분을 되돌아본다","mis":"K5-2-u6-X30"}],"explanation":["상황 설정하기예요.","준비 및 연습하기예요.","실연은 역할이 되어 해 보는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#22','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C18',3,'mc','auto','「골목 끝 수선집」에서 두 친구가 서로 다른 장면을 인상 깊다고 했어요. 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u6-X18']::text[],false,'{"seq":22,"concept":"K5-2-u6-C18","difficulty":3,"kind":"mc","stem":"「골목 끝 수선집」에서 두 친구가 서로 다른 장면을 인상 깊다고 했어요. 알맞은 생각은 어느 것인가요?","options":[{"t":"고른 까닭이 이야기와 맞으면 서로 다른 장면을 골라도 된다","correct":true},{"t":"인상 깊은 장면은 하나로 정해져 있다","mis":"K5-2-u6-X18"},{"t":"까닭은 말하지 않아도 된다","mis":"K5-2-u6-X18"},{"t":"더 많은 친구가 고른 장면만 맞다","mis":"K5-2-u6-X18"}],"explanation":["사람마다 달라요.","까닭이 필요해요.","근거가 맞으면 돼요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#23','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C7',4,'essay','teacher','「골목 끝 수선집」의 인물, 사건, 배경을 정리해 쓰고, 배경이 사건과 인물의 마음에 어떤 영향을 주었는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u6-C7","difficulty":4,"kind":"essay","stem":"「골목 끝 수선집」의 인물, 사건, 배경을 정리해 쓰고, 배경이 사건과 인물의 마음에 어떤 영향을 주었는지 쓰세요.","answer_guide":{"answer":"예: 인물 — 서준, 수선집 할아버지. 사건 — 달리기 대회 전날 밑창이 떨어진 운동화를 할아버지가 고쳐 주고 「끝까지」라는 글씨를 새겨 주었다. 배경 — 눈이 펑펑 내리던 겨울, 시장 골목 끝 작은 수선집. 대회 바로 전날이라는 때가 서준이를 급하게 만들었고, 눈 내리는 골목 끝 작은 수선집이라는 곳은 할아버지의 말없는 따뜻함을 더 크게 느끼게 한다.","scoring_points":["인물·사건·배경을 정리했는가","배경이 사건에 준 영향을 썼는가","인물의 마음과 이어 썼는가"]},"explanation":["정리해요.","사건과 이어요.","마음과 이어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#24','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C24',4,'essay','teacher','「골목 끝 수선집」에서 서준이가 수선집에 들어서는 장면을 해설, 대사, 지문이 들어간 극본으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u6-C24","difficulty":4,"kind":"essay","stem":"「골목 끝 수선집」에서 서준이가 수선집에 들어서는 장면을 해설, 대사, 지문이 들어간 극본으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 때: 눈 내리는 겨울 저녁 · 곳: 시장 골목 끝 작은 신발 수선집 · 나오는 인물: 서준, 할아버지 / 할아버지가 안경을 코끝에 걸치고 바느질을 한다. / 서준: (운동화를 들고 쭈뼛쭈뼛 들어서며) 저……. 내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요. / 할아버지: (운동화를 이리저리 돌려 보다가 말없이 고개를 끄덕인다.)","scoring_points":["해설을 썼는가","대사를 인물 이름 뒤에 썼는가","지문을 괄호로 썼는가"]},"explanation":["해설을 써요.","대사로 써요.","지문은 괄호로 써요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_a#25','kor',5,2,'u6','','g5_2_kor_u6_review_a','unit_review','K5-2-u6-C42',4,'essay','teacher','웃어른께 높임 표현을 바르게 쓴 문장을 두 개 만들어 쓰세요. 하나는 「계시다」나 「편찮으시다」처럼 어른을 직접 높이는 말을, 하나는 「있으시다」처럼 어른과 밀접한 대상을 높이는 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u6-C42","difficulty":4,"kind":"essay","stem":"웃어른께 높임 표현을 바르게 쓴 문장을 두 개 만들어 쓰세요. 하나는 「계시다」나 「편찮으시다」처럼 어른을 직접 높이는 말을, 하나는 「있으시다」처럼 어른과 밀접한 대상을 높이는 말을 쓰세요.","answer_guide":{"answer":"예: 할아버지께서 거실에 계십니다. 선생님께서는 우리 반에 하실 말씀이 있으십니다.","scoring_points":["어른을 직접 높이는 문장을 썼는가","밀접한 대상을 높이는 문장을 썼는가","높임 표현이 바른가"]},"explanation":["직접 높여요.","밀접한 대상을 높여요.","바르게 써요."],"asset":{"type":"passage","lines":["할머니께서 아프십니다. → 할머니께서 편찮으십니다.","할아버지께서는 고민이 계십니다. → 할아버지께서는 고민이 있으십니다.","교장 선생님께서 교장실에 있으십니다. → 교장 선생님께서 교장실에 계십니다.","교장 선생님의 말씀이 계시겠습니다. → 교장 선생님의 말씀이 있으시겠습니다."],"title":"높임 표현 바르게 고치기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#1','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C7',1,'ox','auto','이야기가 펼쳐지는 시간과 장소, 사회적 상황을 배경이라고 해요.',ARRAY['K5-2-u6-X07']::text[],false,'{"seq":1,"concept":"K5-2-u6-C7","difficulty":1,"kind":"ox","stem":"이야기가 펼쳐지는 시간과 장소, 사회적 상황을 배경이라고 해요.","answer":"O","reason_options":[{"t":"배경은 이야기가 언제, 어디에서, 어떤 상황에서 펼쳐지는지를 말하기 때문에","correct":true},{"t":"배경은 이야기가 펼쳐지는 장소만을 말하기 때문에","mis":"K5-2-u6-X07"}],"mis":"K5-2-u6-X07","explanation":["때도 배경이에요.","상황도 배경이에요.","배경의 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#2','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C23',1,'mc','auto','「도서관의 마지막 손님」에서 지문을 찾으면 어느 것인가요?',ARRAY['K5-2-u6-X23','K5-2-u6-X22','K5-2-u6-X21']::text[],false,'{"seq":2,"concept":"K5-2-u6-C23","difficulty":1,"kind":"mc","stem":"「도서관의 마지막 손님」에서 지문을 찾으면 어느 것인가요?","options":[{"t":"(책을 품에 꼭 안으며)","correct":true},{"t":"딱 한 장만 더 읽으면 안 돼요?","mis":"K5-2-u6-X23"},{"t":"그럼 나도 같이 기다릴게.","mis":"K5-2-u6-X22"},{"t":"때: 비 오는 토요일 저녁","mis":"K5-2-u6-X21"}],"explanation":["대사예요.","대사예요.","괄호 속 행동이 지문이에요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#3','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C43',1,'mc','auto','「할아버지께서는 고민이 계십니다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K5-2-u6-X43']::text[],false,'{"seq":3,"concept":"K5-2-u6-C43","difficulty":1,"kind":"mc","stem":"「할아버지께서는 고민이 계십니다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"할아버지께서는 고민이 있으십니다.","correct":true},{"t":"할아버지께서는 고민이 계시겠습니다.","mis":"K5-2-u6-X43"},{"t":"할아버지께서는 고민이 계셨습니다.","mis":"K5-2-u6-X43"},{"t":"할아버지께서는 고민께서 계십니다.","mis":"K5-2-u6-X43"}],"explanation":["고민에 「계시다」는 어색해요.","고민에 「계시다」는 어색해요.","밀접한 대상에는 「있으시다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#4','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C5',1,'mc','auto','「골목 끝 수선집」의 인물을 바르게 모은 것은 어느 것인가요?',ARRAY['K5-2-u6-X05']::text[],false,'{"seq":4,"concept":"K5-2-u6-C5","difficulty":1,"kind":"mc","stem":"「골목 끝 수선집」의 인물을 바르게 모은 것은 어느 것인가요?","options":[{"t":"서준, 수선집 할아버지","correct":true},{"t":"눈, 시장 골목","mis":"K5-2-u6-X05"},{"t":"겨울, 다음 날 아침","mis":"K5-2-u6-X05"},{"t":"달리기 대회, 유리문","mis":"K5-2-u6-X05"}],"explanation":["배경이에요.","때예요.","일을 겪는 사람들이에요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#5','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C25',1,'mc','auto','극본을 낭독할 때 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u6-X23','K5-2-u6-X25']::text[],false,'{"seq":5,"concept":"K5-2-u6-C25","difficulty":1,"kind":"mc","stem":"극본을 낭독할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"지문을 보고 알맞은 목소리와 표정으로 대사를 읽는다","correct":true},{"t":"지문까지 모두 소리 내어 읽는다","mis":"K5-2-u6-X23"},{"t":"모든 대사를 같은 목소리로 읽는다","mis":"K5-2-u6-X25"},{"t":"해설은 빼고 대사만 읽는다","mis":"K5-2-u6-X25"}],"explanation":["지문은 말하지 않아요.","지문대로 바꿔요.","지문을 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#6','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C37',1,'ox','auto','연극은 여러 사람이 협력해서 이야기를 표현하는 작품이에요.',ARRAY['K5-2-u6-X37']::text[],false,'{"seq":6,"concept":"K5-2-u6-C37","difficulty":1,"kind":"ox","stem":"연극은 여러 사람이 협력해서 이야기를 표현하는 작품이에요.","answer":"O","reason_options":[{"t":"여럿이 역할을 나누어 맡고 서로 대사와 움직임을 이어 주어야 하기 때문에","correct":true},{"t":"연극은 주인공을 맡은 사람 혼자 잘하면 되기 때문에","mis":"K5-2-u6-X37"}],"mis":"K5-2-u6-X37","explanation":["함께 만들어요.","서로 이어 줘요.","협력이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#7','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C39',1,'mc','auto','「골목 끝 수선집」의 인물에 대한 감상 질문은 어느 것인가요?',ARRAY['K5-2-u6-X39','K5-2-u6-X38']::text[],false,'{"seq":7,"concept":"K5-2-u6-C39","difficulty":1,"kind":"mc","stem":"「골목 끝 수선집」의 인물에 대한 감상 질문은 어느 것인가요?","options":[{"t":"할아버지가 밑창에 「끝까지」라고 새겨 준 까닭은 무엇일까?","correct":true},{"t":"시장 골목이라는 곳은 이야기에 어떤 느낌을 줄까?","mis":"K5-2-u6-X39"},{"t":"눈 오는 겨울이라는 때는 어떤 느낌을 줄까?","mis":"K5-2-u6-X39"},{"t":"수선집은 골목 어디에 있나요?","mis":"K5-2-u6-X38"}],"explanation":["배경에 대한 질문이에요.","배경에 대한 질문이에요.","인물의 마음을 물어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#8','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C16',1,'mc','auto','모르는 낱말의 뜻을 국어사전에서 찾은 뒤 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X16']::text[],false,'{"seq":8,"concept":"K5-2-u6-C16","difficulty":1,"kind":"mc","stem":"모르는 낱말의 뜻을 국어사전에서 찾은 뒤 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"찾은 뜻을 문장에 넣어 읽어 보며 앞뒤와 맞는지 살핀다","correct":true},{"t":"뜻을 베끼고 바로 잊는다","mis":"K5-2-u6-X16"},{"t":"사전 뜻과 상관없이 내 짐작대로 정한다","mis":"K5-2-u6-X16"},{"t":"그 낱말이 나온 문장을 지운다","mis":"K5-2-u6-X16"}],"explanation":["확인하지 않았어요.","사전으로 확인해요.","문장에 넣어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#9','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C14',2,'mc','auto','「골목 끝 수선집」에서 배경과 사건이 이어진 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X14']::text[],false,'{"seq":9,"concept":"K5-2-u6-C14","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」에서 배경과 사건이 이어진 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"시장 골목 끝에 작은 수선집이 있어서 → 서준이가 운동화를 고치러 들어간다","correct":true},{"t":"서준이가 달려서 → 눈이 내렸다","mis":"K5-2-u6-X14"},{"t":"운동화 그림이 붙어서 → 골목에 수선집이 생겼다","mis":"K5-2-u6-X14"},{"t":"배경과 사건은 아무 관계가 없다","mis":"K5-2-u6-X14"}],"explanation":["앞뒤가 바뀌었어요.","앞뒤가 바뀌었어요.","배경이 사건을 만들어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#10','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C23',2,'mc','auto','「(눈을 동그랗게 뜨고) 정말요?」의 지문으로 알 수 있는 지안이의 마음은 어느 것인가요?',ARRAY['K5-2-u6-X23']::text[],false,'{"seq":10,"concept":"K5-2-u6-C23","difficulty":2,"kind":"mc","stem":"「(눈을 동그랗게 뜨고) 정말요?」의 지문으로 알 수 있는 지안이의 마음은 어느 것인가요?","options":[{"t":"뜻밖의 말에 놀라고 기쁜 마음","correct":true},{"t":"지루하고 졸린 마음","mis":"K5-2-u6-X23"},{"t":"화가 난 마음","mis":"K5-2-u6-X23"},{"t":"무서운 마음","mis":"K5-2-u6-X23"}],"explanation":["지문과 달라요.","지문과 달라요.","눈을 동그랗게 뜬 모습이 단서예요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#11','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C43',2,'error','auto','웃어른을 높이는 문장 가운데 높임 표현이 바르지 않은 것은 어느 것인가요?',ARRAY['K5-2-u6-X43','K5-2-u6-X42']::text[],false,'{"seq":11,"concept":"K5-2-u6-C43","difficulty":2,"kind":"error","stem":"웃어른을 높이는 문장 가운데 높임 표현이 바르지 않은 것은 어느 것인가요?","options":[{"t":"「선생님께서는 좋은 생각이 계십니다.」","correct":true,"mis_target":"K5-2-u6-X43"},{"t":"「교장 선생님께서 교장실에 계십니다.」","mis":"K5-2-u6-X42"},{"t":"「교장 선생님의 말씀이 있으시겠습니다.」","mis":"K5-2-u6-X43"}],"explanation":["바르게 썼어요.","바르게 썼어요.","생각에는 「있으십니다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#12','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C22',2,'match','auto','극본의 구성 요소와 「도서관의 마지막 손님」에서 찾은 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K5-2-u6-C22","difficulty":2,"kind":"match","stem":"극본의 구성 요소와 「도서관의 마지막 손님」에서 찾은 예를 알맞게 이으세요.","pairs":[{"l":"해설","r":"때: 비 오는 토요일 저녁"},{"l":"대사","r":"딱 한 장만 더 읽으면 안 돼요?"},{"l":"지문","r":"(열쇠 꾸러미를 흔들며)"}],"mis":"K5-2-u6-X22","explanation":["첫 부분의 설명이에요.","인물이 하는 말이에요.","괄호 속 행동이에요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#13','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C40',2,'mc','auto','「끝까지」의 의미를 두고 친구와 답이 다를 때 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u6-X40','K5-2-u6-X38']::text[],false,'{"seq":13,"concept":"K5-2-u6-C40","difficulty":2,"kind":"mc","stem":"「끝까지」의 의미를 두고 친구와 답이 다를 때 알맞은 말은 어느 것인가요?","options":[{"t":"「네 답의 근거를 들어 볼래? 나는 마지막 바퀴 장면을 근거로 생각했어.」","correct":true},{"t":"「내 답이 맞으니 그만 말해.」","mis":"K5-2-u6-X40"},{"t":"「의미 같은 건 없어.」","mis":"K5-2-u6-X38"},{"t":"「근거는 필요 없어.」","mis":"K5-2-u6-X40"}],"explanation":["끝까지 들어요.","의미를 생각해요.","근거를 주고받아요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#14','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C37',2,'mc','auto','모둠 연극을 되돌아보며 말할 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X37']::text[],false,'{"seq":14,"concept":"K5-2-u6-C37","difficulty":2,"kind":"mc","stem":"모둠 연극을 되돌아보며 말할 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"잘한 점 → 더 나아질 점 → 고마운 점","correct":true},{"t":"아쉬운 점만 말하기","mis":"K5-2-u6-X37"},{"t":"실수한 친구 이름 말하기 → 끝내기","mis":"K5-2-u6-X37"},{"t":"아무것도 말하지 않기","mis":"K5-2-u6-X37"}],"explanation":["잘한 점부터예요.","탓하지 않아요.","잘한 점부터 고마운 점까지 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#15','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C20',2,'mc','auto','극본을 쓴 목적으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X20']::text[],false,'{"seq":15,"concept":"K5-2-u6-C20","difficulty":2,"kind":"mc","stem":"극본을 쓴 목적으로 알맞은 것은 어느 것인가요?","options":[{"t":"무대에서 연극으로 공연하려고","correct":true},{"t":"일기처럼 하루를 기록하려고","mis":"K5-2-u6-X20"},{"t":"물건의 쓰임을 설명하려고","mis":"K5-2-u6-X20"},{"t":"주장을 펼쳐 설득하려고","mis":"K5-2-u6-X20"}],"explanation":["일기의 목적이에요.","설명하는 글이에요.","극본은 공연하려고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#16','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C5',2,'mc','auto','「낡은 우산이 비 오는 날마다 주인을 기다렸어요.」에서 인물은 무엇인가요?',ARRAY['K5-2-u6-X05','K5-2-u6-X06']::text[],false,'{"seq":16,"concept":"K5-2-u6-C5","difficulty":2,"kind":"mc","stem":"「낡은 우산이 비 오는 날마다 주인을 기다렸어요.」에서 인물은 무엇인가요?","options":[{"t":"낡은 우산","correct":true},{"t":"비 오는 날","mis":"K5-2-u6-X05"},{"t":"사람이 없으니 인물이 없다","mis":"K5-2-u6-X05"},{"t":"기다린 일","mis":"K5-2-u6-X06"}],"explanation":["때예요.","사물도 인물이 돼요.","기다리는 일을 겪는 우산이 인물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#17','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C11',3,'mc','auto','「바람이 잦아든 새벽」에서 「다리가 놓이기 전」이라는 배경이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X11']::text[],false,'{"seq":17,"concept":"K5-2-u6-C11","difficulty":3,"kind":"mc","stem":"「바람이 잦아든 새벽」에서 「다리가 놓이기 전」이라는 배경이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"배가 육지로 가는 유일한 길이라 아버지가 밤새 배를 지켜야 했기 때문에","correct":true},{"t":"섬의 경치를 멋지게 꾸미려고","mis":"K5-2-u6-X11"},{"t":"도윤이의 나이를 알려 주려고","mis":"K5-2-u6-X11"},{"t":"배경은 사건과 관계없어 없어도 된다","mis":"K5-2-u6-X11"}],"explanation":["장식이 아니에요.","나이와 관계없어요.","배경이 사건을 만들었어요."],"asset":{"type":"passage","lines":["다리가 놓이기 전, 작은 섬 소리섬에서 육지로 가는 배는 아버지의 나룻배뿐이었어요.","도윤이는 육지에서 열리는 어린이 그림 대회에 학교 대표로 뽑혔어요.","대회 전날 밤, 도윤이는 들뜬 마음에 크레파스를 몇 번이나 다시 챙겼어요.","그런데 라디오에서 태풍이 올라온다는 소식이 흘러나왔어요.","아버지는 묵묵히 그물을 손질하다가 한마디만 했어요. 「내일은 배 못 띄운다.」","「한 해를 기다린 대회란 말이에요!」 도윤이는 방문을 쾅 닫았어요.","이불을 뒤집어쓰자 아버지가 야속해서 눈물이 났어요."],"title":"바람이 잦아든 새벽 (앞)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#18','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C24',3,'mc','auto','극본 「도서관의 마지막 손님」의 마지막 줄을 이야기 글로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K5-2-u6-X24']::text[],false,'{"seq":18,"concept":"K5-2-u6-C24","difficulty":3,"kind":"mc","stem":"극본 「도서관의 마지막 손님」의 마지막 줄을 이야기 글로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"지안이는 눈을 동그랗게 뜨고 「정말요?」 하더니, 책장을 넘기며 작은 소리로 읽기 시작했어요.","correct":true},{"t":"지안: 정말요? 책장을 넘겼다.","mis":"K5-2-u6-X24"},{"t":"(지안이는 눈을 동그랗게 뜨고) 정말요?","mis":"K5-2-u6-X24"},{"t":"정말요. 지안. 책장.","mis":"K5-2-u6-X24"}],"explanation":["극본 모양 그대로예요.","괄호가 남았어요.","줄글로 풀어 썼어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#19','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C43',3,'mc','auto','조회 시간에 사회를 맡은 친구가 할 말로 바른 것은 어느 것인가요?',ARRAY['K5-2-u6-X43','K5-2-u6-X42']::text[],false,'{"seq":19,"concept":"K5-2-u6-C43","difficulty":3,"kind":"mc","stem":"조회 시간에 사회를 맡은 친구가 할 말로 바른 것은 어느 것인가요?","options":[{"t":"「다음은 교장 선생님의 말씀이 있으시겠습니다.」","correct":true},{"t":"「다음은 교장 선생님의 말씀이 계시겠습니다.」","mis":"K5-2-u6-X43"},{"t":"「다음은 교장 선생님께서 말씀이 계십니다.」","mis":"K5-2-u6-X43"},{"t":"「교장 선생님께서는 지금 단상에 있으십니다.」","mis":"K5-2-u6-X42"}],"explanation":["말씀에 「계시다」는 어색해요.","말씀에 「계시다」는 어색해요.","말씀에는 「있으시다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#20','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C38',3,'mc','auto','「서준이는 어떤 운동화를 들고 왔나요?」를 감상 질문으로 바꾼 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X38']::text[],false,'{"seq":20,"concept":"K5-2-u6-C38","difficulty":3,"kind":"mc","stem":"「서준이는 어떤 운동화를 들고 왔나요?」를 감상 질문으로 바꾼 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「서준이는 밑창이 떨어진 운동화를 들고 오며 어떤 마음이었을까?」","correct":true},{"t":"「서준이 운동화는 몇 켤레일까?」","mis":"K5-2-u6-X38"},{"t":"「서준이는 운동화를 어디서 샀나요?」","mis":"K5-2-u6-X38"},{"t":"「운동화 밑창은 무엇으로 만드나요?」","mis":"K5-2-u6-X38"}],"explanation":["사실 확인이에요.","사실 확인이에요.","마음을 물어 의미를 생각하게 해요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#21','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C36',3,'mc','auto','연극에서 대사를 조금 바꾸어 말해도 괜찮은 경우는 어느 것인가요?',ARRAY['K5-2-u6-X36','K5-2-u6-X34']::text[],false,'{"seq":21,"concept":"K5-2-u6-C36","difficulty":3,"kind":"mc","stem":"연극에서 대사를 조금 바꾸어 말해도 괜찮은 경우는 어느 것인가요?","options":[{"t":"인물의 마음과 상황이 잘 드러나도록 자연스럽게 바꿀 때","correct":true},{"t":"대사가 외우기 귀찮을 때","mis":"K5-2-u6-X36"},{"t":"웃기려고 이야기와 다른 말을 할 때","mis":"K5-2-u6-X36"},{"t":"인물의 성격과 반대로 바꿀 때","mis":"K5-2-u6-X34"}],"explanation":["까닭이 알맞지 않아요.","이야기와 어긋나요.","마음이 드러나면 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#22','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C17',3,'mc','auto','「거센 바람이 밤새 불다가 새벽에 잦아들었다.」를 바르게 풀어 쓴 것은 어느 것인가요?',ARRAY['K5-2-u6-X17']::text[],false,'{"seq":22,"concept":"K5-2-u6-C17","difficulty":3,"kind":"mc","stem":"「거센 바람이 밤새 불다가 새벽에 잦아들었다.」를 바르게 풀어 쓴 것은 어느 것인가요?","options":[{"t":"세게 불던 바람이 새벽에 차차 가라앉았다","correct":true},{"t":"약하던 바람이 새벽에 더 세졌다","mis":"K5-2-u6-X17"},{"t":"바람이 새벽에 더 자주 불었다","mis":"K5-2-u6-X17"},{"t":"바람이 새벽에 방향을 바꾸었다","mis":"K5-2-u6-X17"}],"explanation":["뜻과 반대예요.","「잦다」와 헷갈렸어요.","「잦아들다」는 가라앉아 가는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#23','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C13',4,'essay','teacher','「골목 끝 수선집」에서 서준이의 마음이 어떻게 바뀌었는지 사건과 이어 쓰고, 가장 인상 깊은 장면을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u6-C13","difficulty":4,"kind":"essay","stem":"「골목 끝 수선집」에서 서준이의 마음이 어떻게 바뀌었는지 사건과 이어 쓰고, 가장 인상 깊은 장면을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 운동화가 망가지고 돈도 없어 쭈뼛쭈뼛 걱정하던 서준이는, 밑창에 새겨진 「끝까지」를 보고 힘을 얻었다. 그래서 마지막 바퀴에서 넘어질 뻔했을 때도 다시 달릴 수 있었다. 서준이가 밑창의 글씨를 떠올리며 다시 달리는 장면이 가장 인상 깊다. 할아버지의 말없는 응원이 서준이에게 닿은 순간이기 때문이다.","scoring_points":["마음의 변화를 썼는가","사건과 이어 썼는가","인상 깊은 장면과 까닭을 썼는가"]},"explanation":["변화를 써요.","사건과 이어요.","장면과 까닭을 써요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#24','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C23',4,'essay','teacher','「도서관의 마지막 손님」에서 해설, 대사, 지문을 하나씩 찾아 쓰고, 지문이 인물의 마음을 어떻게 보여 주는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u6-C23","difficulty":4,"kind":"essay","stem":"「도서관의 마지막 손님」에서 해설, 대사, 지문을 하나씩 찾아 쓰고, 지문이 인물의 마음을 어떻게 보여 주는지 쓰세요.","answer_guide":{"answer":"예: 해설 — 「때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관」. 대사 — 「딱 한 장만 더 읽으면 안 돼요?」. 지문 — 「(책을 품에 꼭 안으며)」. 이 지문은 지안이가 책을 놓고 싶지 않을 만큼 이야기에 푹 빠져 간절하다는 마음을 보여 준다.","scoring_points":["해설·대사·지문을 찾았는가","지문을 골라 썼는가","지문이 보여 주는 마음을 썼는가"]},"explanation":["셋을 찾아요.","지문을 골라요.","마음을 써요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_b#25','kor',5,2,'u6','','g5_2_kor_u6_review_b','unit_review','K5-2-u6-C1',4,'essay','teacher','이 단원에서 이야기 감상, 극본 감상, 연극하기 가운데 가장 기억에 남는 활동을 골라 무엇을 새롭게 알았는지, 앞으로 작품을 볼 때 어떻게 하고 싶은지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u6-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 이야기 감상, 극본 감상, 연극하기 가운데 가장 기억에 남는 활동을 골라 무엇을 새롭게 알았는지, 앞으로 작품을 볼 때 어떻게 하고 싶은지 쓰세요.","answer_guide":{"answer":"예: 극본 감상이 가장 기억에 남는다. 지문을 살펴 읽으니 대사만 읽을 때보다 인물의 마음이 훨씬 잘 보인다는 것을 새롭게 알았다. 앞으로 연극을 볼 때 배우가 지문을 어떻게 표현했는지 살피고, 이야기를 읽을 때도 배경이 사건에 준 영향을 생각하며 깊이 감상하고 싶다.","scoring_points":["활동을 골랐는가","새롭게 안 것을 썼는가","앞으로의 다짐을 썼는가"]},"explanation":["활동을 골라요.","새로 안 것을 써요.","다짐을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#1','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C6',1,'mc','auto','「골목 끝 수선집」에서 일어난 사건으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X06']::text[],false,'{"seq":1,"concept":"K5-2-u6-C6","difficulty":1,"kind":"mc","stem":"「골목 끝 수선집」에서 일어난 사건으로 알맞은 것은 어느 것인가요?","options":[{"t":"할아버지가 서준이의 운동화를 고쳐 주었다","correct":true},{"t":"눈이 펑펑 내리던 겨울","mis":"K5-2-u6-X06"},{"t":"시장 골목 끝","mis":"K5-2-u6-X06"},{"t":"수선집 할아버지","mis":"K5-2-u6-X06"}],"explanation":["때예요.","곳이에요.","일어난 일이 사건이에요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#2','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C20',1,'ox','auto','극본은 연극을 하려고 쓴 글이에요.',ARRAY['K5-2-u6-X20']::text[],false,'{"seq":2,"concept":"K5-2-u6-C20","difficulty":1,"kind":"ox","stem":"극본은 연극을 하려고 쓴 글이에요.","answer":"O","reason_options":[{"t":"극본은 무대에서 공연할 수 있게 대사와 지문으로 나누어 쓴 글이기 때문에","correct":true},{"t":"극본은 소리 내지 않고 혼자 읽기만 하는 글이기 때문에","mis":"K5-2-u6-X20"}],"mis":"K5-2-u6-X20","explanation":["공연하려고 써요.","대사와 지문으로 써요.","극본의 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#3','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C42',1,'mc','auto','「교장 선생님께서 교장실에 ( ).」의 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u6-X42']::text[],false,'{"seq":3,"concept":"K5-2-u6-C42","difficulty":1,"kind":"mc","stem":"「교장 선생님께서 교장실에 ( ).」의 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"계십니다","correct":true},{"t":"있으십니다","mis":"K5-2-u6-X42"},{"t":"있습니다","mis":"K5-2-u6-X42"},{"t":"있어요","mis":"K5-2-u6-X42"}],"explanation":["직접 높일 때는 높임 어휘예요.","높이지 않았어요.","어른이 계신 곳을 말할 때 「계시다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#4','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C8',1,'mc','auto','「골목 끝 수선집」에서 때를 알려 주는 말은 어느 것인가요?',ARRAY['K5-2-u6-X08']::text[],false,'{"seq":4,"concept":"K5-2-u6-C8","difficulty":1,"kind":"mc","stem":"「골목 끝 수선집」에서 때를 알려 주는 말은 어느 것인가요?","options":[{"t":"눈이 펑펑 내리던 겨울","correct":true},{"t":"시장 골목 끝","mis":"K5-2-u6-X08"},{"t":"작은 신발 수선집","mis":"K5-2-u6-X08"},{"t":"수선집 유리문","mis":"K5-2-u6-X08"}],"explanation":["곳이에요.","곳이에요.","언제인지 알려 줘요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#5','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C27',1,'mc','auto','극본을 감상할 때 함께 읽어야 할 것을 모두 담은 것은 어느 것인가요?',ARRAY['K5-2-u6-X27']::text[],false,'{"seq":5,"concept":"K5-2-u6-C27","difficulty":1,"kind":"mc","stem":"극본을 감상할 때 함께 읽어야 할 것을 모두 담은 것은 어느 것인가요?","options":[{"t":"해설과 대사와 지문","correct":true},{"t":"대사 하나만","mis":"K5-2-u6-X27"},{"t":"지문 하나만","mis":"K5-2-u6-X27"},{"t":"해설 하나만","mis":"K5-2-u6-X27"}],"explanation":["하나로는 부족해요.","하나로는 부족해요.","셋을 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#6','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C35',1,'mc','auto','연극하기 전 점검표에 들어갈 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X35']::text[],false,'{"seq":6,"concept":"K5-2-u6-C35","difficulty":1,"kind":"mc","stem":"연극하기 전 점검표에 들어갈 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"소품이 잘 준비되었나요?","correct":true},{"t":"관객이 몇 명 올까요?","mis":"K5-2-u6-X35"},{"t":"다른 모둠보다 잘할까요?","mis":"K5-2-u6-X35"},{"t":"공연 사진은 누가 찍을까요?","mis":"K5-2-u6-X35"}],"explanation":["점검할 것이 아니에요.","겨루기가 아니에요.","소품을 미리 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#7','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C40',1,'ox','auto','감상을 나눌 때 친구의 답이 내 생각과 달라도 끝까지 들어요.',ARRAY['K5-2-u6-X40']::text[],false,'{"seq":7,"concept":"K5-2-u6-C40","difficulty":1,"kind":"ox","stem":"감상을 나눌 때 친구의 답이 내 생각과 달라도 끝까지 들어요.","answer":"O","reason_options":[{"t":"친구의 답에서 내가 생각하지 못한 의미를 발견할 수 있기 때문에","correct":true},{"t":"내 답과 다르면 친구의 답이 틀린 것이기 때문에","mis":"K5-2-u6-X40"}],"mis":"K5-2-u6-X40","explanation":["끝까지 들어요.","새 의미를 발견해요.","존중하며 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#8','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C18',1,'ox','auto','인상 깊은 장면을 말할 때에는 그 장면을 고른 까닭도 함께 말해요.',ARRAY['K5-2-u6-X18']::text[],false,'{"seq":8,"concept":"K5-2-u6-C18","difficulty":1,"kind":"ox","stem":"인상 깊은 장면을 말할 때에는 그 장면을 고른 까닭도 함께 말해요.","answer":"O","reason_options":[{"t":"까닭을 들어야 친구가 내 감상을 이해하고 서로 견주어 볼 수 있기 때문에","correct":true},{"t":"장면 이름만 말하면 감상이 다 전해지기 때문에","mis":"K5-2-u6-X18"}],"mis":"K5-2-u6-X18","explanation":["까닭과 함께예요.","근거를 들어요.","서로 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#9','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C15',2,'mc','auto','「골목 끝 수선집」에서 할아버지의 마음을 가장 잘 짐작하게 하는 행동은 어느 것인가요?',ARRAY['K5-2-u6-X15']::text[],false,'{"seq":9,"concept":"K5-2-u6-C15","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」에서 할아버지의 마음을 가장 잘 짐작하게 하는 행동은 어느 것인가요?","options":[{"t":"밑창에 작은 글씨로 「끝까지」라고 새겨 주었다","correct":true},{"t":"안경을 코끝에 걸쳤다","mis":"K5-2-u6-X15"},{"t":"운동화를 이리저리 돌려 보았다","mis":"K5-2-u6-X15"},{"t":"수선집 문을 열어 두었다","mis":"K5-2-u6-X15"}],"explanation":["마음이 잘 드러나지 않아요.","마음이 잘 드러나지 않아요.","말 대신 응원을 새겨 주었어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#10','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C31',2,'mc','auto','사서 선생님 역할을 맡은 친구가 인물에게 던질 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X31']::text[],false,'{"seq":10,"concept":"K5-2-u6-C31","difficulty":2,"kind":"mc","stem":"사서 선생님 역할을 맡은 친구가 인물에게 던질 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「사서 선생님은 왜 문을 닫지 않고 함께 기다리기로 했을까?」","correct":true},{"t":"「사서 선생님의 열쇠는 몇 개일까?」","mis":"K5-2-u6-X31"},{"t":"「도서관 책은 모두 몇 권일까?」","mis":"K5-2-u6-X31"},{"t":"「내 대사는 몇 줄일까?」","mis":"K5-2-u6-X31"}],"explanation":["마음과 관계없어요.","마음과 관계없어요.","그렇게 한 까닭을 물어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#11','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C43',2,'ox','auto','어른과 관련된 말이면 무엇이든 「계시다」를 쓰면 높임 표현이 돼요.',ARRAY['K5-2-u6-X43']::text[],false,'{"seq":11,"concept":"K5-2-u6-C43","difficulty":2,"kind":"ox","stem":"어른과 관련된 말이면 무엇이든 「계시다」를 쓰면 높임 표현이 돼요.","answer":"X","reason_options":[{"t":"「계시다」는 어른을 직접 높일 때 쓰고, 말씀·고민처럼 밀접한 대상을 높일 때에는 「있으시다」를 쓰기 때문에","correct":true},{"t":"「계시다」가 「있으시다」보다 언제나 더 높이는 말이기 때문에","mis":"K5-2-u6-X43"}],"mis":"K5-2-u6-X43","explanation":["쓰임이 달라요.","밀접한 대상은 「있으시다」예요.","주어를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#12','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C24',2,'match','auto','같은 장면을 이야기 글과 극본으로 쓸 때 인물의 말과 행동을 쓰는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K5-2-u6-C24","difficulty":2,"kind":"match","stem":"같은 장면을 이야기 글과 극본으로 쓸 때 인물의 말과 행동을 쓰는 방법을 알맞게 이으세요.","pairs":[{"l":"이야기 글의 인물 행동","r":"문장으로 풀어 쓴다"},{"l":"극본의 인물 말","r":"인물 이름 뒤에 쓴다"},{"l":"극본의 인물 행동","r":"괄호 안에 쓴다"}],"mis":"K5-2-u6-X24","explanation":["줄글로 써요.","대사로 써요.","지문으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#13','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C32',2,'mc','auto','「도서관의 마지막 손님」에서 인상적인 부분을 근거와 함께 말한 것은 어느 것인가요?',ARRAY['K5-2-u6-X32']::text[],false,'{"seq":13,"concept":"K5-2-u6-C32","difficulty":2,"kind":"mc","stem":"「도서관의 마지막 손님」에서 인상적인 부분을 근거와 함께 말한 것은 어느 것인가요?","options":[{"t":"「선생님이 의자를 끌어와 앉는 지문이 인상적이었어. 문을 닫는 대신 지안이 마음을 알아준 게 느껴졌어.」","correct":true},{"t":"「그냥 좋았어.」","mis":"K5-2-u6-X32"},{"t":"「도서관이 나와서.」","mis":"K5-2-u6-X32"},{"t":"「짧아서 좋았어.」","mis":"K5-2-u6-X32"}],"explanation":["까닭이 없어요.","근거가 약해요.","지문을 근거로 들었어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#14','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C34',2,'mc','auto','지안이가 「딱 한 장만 더 읽으면 안 돼요?」라고 말할 때 알맞은 표현은 어느 것인가요?',ARRAY['K5-2-u6-X34','K5-2-u6-X23']::text[],false,'{"seq":14,"concept":"K5-2-u6-C34","difficulty":2,"kind":"mc","stem":"지안이가 「딱 한 장만 더 읽으면 안 돼요?」라고 말할 때 알맞은 표현은 어느 것인가요?","options":[{"t":"책을 품에 꼭 안고 간절한 목소리로 말한다","correct":true},{"t":"책을 던지며 소리친다","mis":"K5-2-u6-X34"},{"t":"하품하며 지루하게 말한다","mis":"K5-2-u6-X34"},{"t":"「책을 품에 꼭 안으며」까지 소리 내어 말한다","mis":"K5-2-u6-X23"}],"explanation":["지문과 반대예요.","마음과 맞지 않아요.","지문을 살려 간절하게 말해요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#15','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C27',2,'mc','auto','「도서관의 마지막 손님」을 대사만 읽으면 놓치기 쉬운 것은 어느 것인가요?',ARRAY['K5-2-u6-X27']::text[],false,'{"seq":15,"concept":"K5-2-u6-C27","difficulty":2,"kind":"mc","stem":"「도서관의 마지막 손님」을 대사만 읽으면 놓치기 쉬운 것은 어느 것인가요?","options":[{"t":"선생님이 의자를 끌어와 앉는 행동","correct":true},{"t":"지안이가 한 장만 더 읽고 싶다고 한 말","mis":"K5-2-u6-X27"},{"t":"선생님이 문 닫을 시간이라고 한 말","mis":"K5-2-u6-X27"},{"t":"지안이가 「정말요?」라고 한 말","mis":"K5-2-u6-X27"}],"explanation":["대사에 있어요.","대사에 있어요.","행동은 지문에 있어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#16','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C12',2,'ox','auto','인물, 사건, 배경을 생각하며 읽으면 이야기의 전체 흐름과 의미를 잘 알 수 있어요.',ARRAY['K5-2-u6-X12']::text[],false,'{"seq":16,"concept":"K5-2-u6-C12","difficulty":2,"kind":"ox","stem":"인물, 사건, 배경을 생각하며 읽으면 이야기의 전체 흐름과 의미를 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"구성 요소와 그 사이의 관계를 살피면 이야기가 어떻게 흘러가고 무엇을 말하는지 보이기 때문에","correct":true},{"t":"구성 요소는 외우는 것일 뿐 이야기 이해와는 관계없기 때문에","mis":"K5-2-u6-X12"}],"mis":"K5-2-u6-X12","explanation":["흐름이 보여요.","의미가 보여요.","관계를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#17','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C13',3,'error','auto','「골목 끝 수선집」을 감상한 말이에요. 이야기와 맞지 않는 말은 어느 것인가요?',ARRAY['K5-2-u6-X13']::text[],false,'{"seq":17,"concept":"K5-2-u6-C13","difficulty":3,"kind":"error","stem":"「골목 끝 수선집」을 감상한 말이에요. 이야기와 맞지 않는 말은 어느 것인가요?","options":[{"t":"「서준이는 처음부터 끝까지 자신만만했어.」","correct":true,"mis_target":"K5-2-u6-X13"},{"t":"「서준이는 운동화가 망가져 쭈뼛쭈뼛 들어섰어.」","mis":"K5-2-u6-X13"},{"t":"「밑창의 글씨를 떠올리고 다시 힘을 냈어.」","mis":"K5-2-u6-X13"}],"explanation":["이야기와 맞아요.","이야기와 맞아요.","서준이의 마음은 바뀌었어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#18','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C25',3,'mc','auto','사서 선생님의 두 대사를 낭독할 때 목소리를 바꾸는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X25','K5-2-u6-X23']::text[],false,'{"seq":18,"concept":"K5-2-u6-C25","difficulty":3,"kind":"mc","stem":"사서 선생님의 두 대사를 낭독할 때 목소리를 바꾸는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"첫 대사는 열쇠를 흔들며 문 닫을 때를 알리듯, 둘째 대사는 잠시 망설인 뒤 부드럽고 따뜻하게","correct":true},{"t":"두 대사 모두 같은 목소리로 빠르게","mis":"K5-2-u6-X25"},{"t":"첫 대사는 따뜻하게, 둘째 대사는 화를 내며","mis":"K5-2-u6-X25"},{"t":"지문까지 모두 소리 내어","mis":"K5-2-u6-X23"}],"explanation":["마음이 바뀌었어요.","지문과 반대예요.","지문과 마음의 변화를 살려요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#19','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C42',3,'error','auto','할머니 댁에 전화로 안부를 여쭙는 말이에요. 높임 어휘를 바르게 쓰지 않은 것은 어느 것인가요?',ARRAY['K5-2-u6-X42']::text[],false,'{"seq":19,"concept":"K5-2-u6-C42","difficulty":3,"kind":"error","stem":"할머니 댁에 전화로 안부를 여쭙는 말이에요. 높임 어휘를 바르게 쓰지 않은 것은 어느 것인가요?","options":[{"t":"「할머니, 요즘 많이 아프세요?」","correct":true,"mis_target":"K5-2-u6-X42"},{"t":"「할머니, 요즘 많이 편찮으세요?」","mis":"K5-2-u6-X42"},{"t":"「할아버지께서는 지금 댁에 계세요?」","mis":"K5-2-u6-X42"}],"explanation":["높임 어휘를 썼어요.","높임 어휘를 썼어요.","「아프다」의 높임 어휘는 「편찮으시다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#20','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C40',3,'mc','auto','감상을 나눈 뒤 「처음에는 할아버지가 무뚝뚝하다고 생각했는데, 친구 답을 듣고 말 대신 행동으로 마음을 전하는 분이라는 것을 알았어.」라고 썼어요. 이 글에서 알 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u6-X40','K5-2-u6-X38']::text[],false,'{"seq":20,"concept":"K5-2-u6-C40","difficulty":3,"kind":"mc","stem":"감상을 나눈 뒤 「처음에는 할아버지가 무뚝뚝하다고 생각했는데, 친구 답을 듣고 말 대신 행동으로 마음을 전하는 분이라는 것을 알았어.」라고 썼어요. 이 글에서 알 수 있는 것은 어느 것인가요?","options":[{"t":"묻고 답하며 나눈 뒤 내 감상이 깊어졌다","correct":true},{"t":"친구의 답이 틀렸다","mis":"K5-2-u6-X40"},{"t":"감상은 처음 생각을 바꾸면 안 된다","mis":"K5-2-u6-X40"},{"t":"이야기에 답이 그대로 쓰여 있었다","mis":"K5-2-u6-X38"}],"explanation":["친구 답으로 새로 알았어요.","바뀌어도 괜찮아요.","나눈 뒤 감상이 깊어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#21','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C37',3,'mc','auto','연극 역할을 나눌 때 바람직한 모습은 어느 것인가요?',ARRAY['K5-2-u6-X37','K5-2-u6-X33']::text[],false,'{"seq":21,"concept":"K5-2-u6-C37","difficulty":3,"kind":"mc","stem":"연극 역할을 나눌 때 바람직한 모습은 어느 것인가요?","options":[{"t":"앞에 나서기 부끄러운 친구도 소품이나 해설처럼 맡을 수 있는 일을 함께 정한다","correct":true},{"t":"잘하는 친구에게 역할을 몰아준다","mis":"K5-2-u6-X37"},{"t":"하고 싶지 않은 친구는 빠지게 한다","mis":"K5-2-u6-X37"},{"t":"목소리 큰 친구가 혼자 정한다","mis":"K5-2-u6-X33"}],"explanation":["몰아주지 않아요.","모두 함께해요.","저마다 맡을 일이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#22','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C2',3,'mc','auto','「골목 끝 수선집」을 친구에게 소개하는 말로 가장 깊이 있는 것은 어느 것인가요?',ARRAY['K5-2-u6-X02']::text[],false,'{"seq":22,"concept":"K5-2-u6-C2","difficulty":3,"kind":"mc","stem":"「골목 끝 수선집」을 친구에게 소개하는 말로 가장 깊이 있는 것은 어느 것인가요?","options":[{"t":"눈 내리는 겨울 시장 골목, 말없는 수선집 할아버지가 달리기 대회를 앞둔 서준이의 운동화에 응원을 새겨 주는 이야기야.","correct":true},{"t":"운동화 이야기야.","mis":"K5-2-u6-X02"},{"t":"할아버지가 나와.","mis":"K5-2-u6-X02"},{"t":"표지가 예뻐.","mis":"K5-2-u6-X02"}],"explanation":["흐름이 보이지 않아요.","흐름이 보이지 않아요.","때·곳·인물·일을 함께 담았어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#23','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C19',4,'essay','teacher','「골목 끝 수선집」의 할아버지나 서준이에게 편지를 쓰세요. 인물이 겪은 일과 마음을 헤아린 말, 내가 느낀 점을 넣으세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u6-C19","difficulty":4,"kind":"essay","stem":"「골목 끝 수선집」의 할아버지나 서준이에게 편지를 쓰세요. 인물이 겪은 일과 마음을 헤아린 말, 내가 느낀 점을 넣으세요.","answer_guide":{"answer":"예: 서준이에게. 대회 전날 운동화가 망가져서 얼마나 걱정했니. 돈도 없이 수선집 문을 여는 것도 무척 떨렸을 것 같아. 넘어질 뻔했을 때 밑창의 글씨를 떠올리고 다시 달린 너를 보며 나도 힘든 일이 있을 때 포기하지 않아야겠다고 생각했어.","scoring_points":["겪은 일을 썼는가","마음을 헤아린 말을 썼는가","내가 느낀 점을 썼는가"]},"explanation":["겪은 일을 써요.","마음을 헤아려요.","느낀 점을 써요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#24','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C34',4,'essay','teacher','「도서관의 마지막 손님」을 연극으로 한다면 지안이나 사서 선생님 가운데 한 인물을 골라 성격을 쓰고, 지문을 살려 어떻게 표현할지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u6-C34","difficulty":4,"kind":"essay","stem":"「도서관의 마지막 손님」을 연극으로 한다면 지안이나 사서 선생님 가운데 한 인물을 골라 성격을 쓰고, 지문을 살려 어떻게 표현할지 쓰세요.","answer_guide":{"answer":"예: 사서 선생님을 맡겠다. 선생님은 아이의 마음을 헤아릴 줄 아는 따뜻한 성격이다. 처음에는 열쇠를 흔들며 문 닫을 시간을 알리고, 지안이의 부탁을 듣고 잠시 말없이 바라본 뒤 의자를 끌어와 앉으며 부드러운 목소리로 「그럼 나도 같이 기다릴게.」라고 말하겠다.","scoring_points":["인물을 골랐는가","성격을 썼는가","지문을 살린 표현을 썼는가"]},"explanation":["인물을 골라요.","성격을 써요.","지문을 살려요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_c#25','kor',5,2,'u6','','g5_2_kor_u6_review_c','unit_review','K5-2-u6-C24',4,'essay','teacher','「이야기는 몇 번이고 다시 읽을 수 있어 연극보다 깊이 감상할 수 있다.」와 「연극은 배우의 목소리와 표정이 있어 더 깊이 와닿는다.」 가운데 내 생각을 이 단원에서 감상한 작품을 근거로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u6-C24","difficulty":4,"kind":"essay","stem":"「이야기는 몇 번이고 다시 읽을 수 있어 연극보다 깊이 감상할 수 있다.」와 「연극은 배우의 목소리와 표정이 있어 더 깊이 와닿는다.」 가운데 내 생각을 이 단원에서 감상한 작품을 근거로 쓰세요.","answer_guide":{"answer":"예: 나는 두 생각 모두 맞다고 본다. 「바람이 잦아든 새벽」은 이야기 글로 읽어서 아버지의 손등 자국 같은 장면을 천천히 다시 볼 수 있었다. 「빗속의 숲속 음악회」는 연극으로 해 보니 뭉치의 지문을 목소리와 몸짓으로 살리며 미안한 마음이 더 생생하게 와닿았다.","scoring_points":["내 생각을 밝혔는가","감상한 작품을 근거로 들었는가","이야기 글과 극본의 특징을 살폈는가"]},"explanation":["생각을 밝혀요.","작품을 근거로 들어요.","특징을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#1','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C12',1,'mc','auto','이야기의 구성 요소를 바르게 모은 것은 어느 것인가요?',ARRAY['K5-2-u6-X12']::text[],false,'{"seq":1,"concept":"K5-2-u6-C12","difficulty":1,"kind":"mc","stem":"이야기의 구성 요소를 바르게 모은 것은 어느 것인가요?","options":[{"t":"인물, 사건, 배경","correct":true},{"t":"해설, 대사, 지문","mis":"K5-2-u6-X12"},{"t":"제목, 쪽수, 글쓴이","mis":"K5-2-u6-X12"},{"t":"인물, 대사, 제목","mis":"K5-2-u6-X12"}],"explanation":["극본의 구성 요소예요.","구성 요소가 아니에요.","인물·사건·배경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#2','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C22',1,'mc','auto','「도서관의 마지막 손님」에서 대사로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X22','K5-2-u6-X23']::text[],false,'{"seq":2,"concept":"K5-2-u6-C22","difficulty":1,"kind":"mc","stem":"「도서관의 마지막 손님」에서 대사로 알맞은 것은 어느 것인가요?","options":[{"t":"정말요?","correct":true},{"t":"(열쇠 꾸러미를 흔들며)","mis":"K5-2-u6-X22"},{"t":"곳: 동네 작은 도서관","mis":"K5-2-u6-X22"},{"t":"(눈을 동그랗게 뜨고)","mis":"K5-2-u6-X23"}],"explanation":["지문이에요.","해설이에요.","인물이 직접 하는 말이에요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#3','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C43',1,'mc','auto','「지금부터 교장 선생님의 말씀이 ( ).」의 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u6-X43']::text[],false,'{"seq":3,"concept":"K5-2-u6-C43","difficulty":1,"kind":"mc","stem":"「지금부터 교장 선생님의 말씀이 ( ).」의 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"있으시겠습니다","correct":true},{"t":"계시겠습니다","mis":"K5-2-u6-X43"},{"t":"계십니다","mis":"K5-2-u6-X43"},{"t":"계셨습니다","mis":"K5-2-u6-X43"}],"explanation":["말씀이 「계시다」는 어색해요.","말씀이 「계시다」는 어색해요.","말씀에는 「있으시다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#4','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C10',1,'mc','auto','「골목 끝 수선집」에서 「말없이 바늘을 놀렸어요」로 짐작할 수 있는 할아버지의 모습은 어느 것인가요?',ARRAY['K5-2-u6-X10']::text[],false,'{"seq":4,"concept":"K5-2-u6-C10","difficulty":1,"kind":"mc","stem":"「골목 끝 수선집」에서 「말없이 바늘을 놀렸어요」로 짐작할 수 있는 할아버지의 모습은 어느 것인가요?","options":[{"t":"말은 적지만 묵묵히 제 일을 하는 사람","correct":true},{"t":"수다스럽고 장난이 많은 사람","mis":"K5-2-u6-X10"},{"t":"일을 싫어하는 사람","mis":"K5-2-u6-X10"},{"t":"서준이를 미워하는 사람","mis":"K5-2-u6-X10"}],"explanation":["행동과 반대예요.","행동과 반대예요.","말없이 일하는 행동이 근거예요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#5','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C24',1,'mc','auto','이야기 글과 극본 가운데 인물의 행동을 괄호 안에 쓰는 것은 어느 것인가요?',ARRAY['K5-2-u6-X24']::text[],false,'{"seq":5,"concept":"K5-2-u6-C24","difficulty":1,"kind":"mc","stem":"이야기 글과 극본 가운데 인물의 행동을 괄호 안에 쓰는 것은 어느 것인가요?","options":[{"t":"극본","correct":true},{"t":"이야기 글","mis":"K5-2-u6-X24"},{"t":"둘 다","mis":"K5-2-u6-X24"},{"t":"둘 다 아니다","mis":"K5-2-u6-X24"}],"explanation":["줄글로 풀어 써요.","이야기 글은 아니에요.","극본은 행동을 지문으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#6','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C34',1,'mc','auto','사서 선생님의 「(잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.」를 연기하는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X34','K5-2-u6-X23']::text[],false,'{"seq":6,"concept":"K5-2-u6-C34","difficulty":1,"kind":"mc","stem":"사서 선생님의 「(잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.」를 연기하는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"지안이를 잠시 바라본 뒤 의자를 끌어와 앉으며 따뜻하게 말한다","correct":true},{"t":"열쇠를 흔들며 화를 낸다","mis":"K5-2-u6-X34"},{"t":"괄호 안의 말까지 소리 내어 읽는다","mis":"K5-2-u6-X23"},{"t":"관객을 등지고 빠르게 말한다","mis":"K5-2-u6-X34"}],"explanation":["지문과 맞지 않아요.","지문은 말하지 않아요.","지문을 살려 표현해요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#7','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C41',1,'mc','auto','구성 요소를 생각하며 감상하는 활동으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X41']::text[],false,'{"seq":7,"concept":"K5-2-u6-C41","difficulty":1,"kind":"mc","stem":"구성 요소를 생각하며 감상하는 활동으로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 장면을 그리고 까닭을 붙여 전시하기","correct":true},{"t":"줄넘기 대회 열기","mis":"K5-2-u6-X41"},{"t":"구구단 외우기","mis":"K5-2-u6-X41"},{"t":"교실 청소하기","mis":"K5-2-u6-X41"}],"explanation":["감상과 관계없어요.","감상과 관계없어요.","장면과 까닭으로 감상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#8','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C19',1,'mc','auto','인물에게 편지를 쓸 때 담으면 좋은 것은 어느 것인가요?',ARRAY['K5-2-u6-X19']::text[],false,'{"seq":8,"concept":"K5-2-u6-C19","difficulty":1,"kind":"mc","stem":"인물에게 편지를 쓸 때 담으면 좋은 것은 어느 것인가요?","options":[{"t":"인물이 겪은 일과 그때의 마음을 헤아린 말","correct":true},{"t":"줄거리를 처음부터 끝까지 옮겨 적은 것","mis":"K5-2-u6-X19"},{"t":"인물을 꾸짖는 말만","mis":"K5-2-u6-X19"},{"t":"책값과 쪽수","mis":"K5-2-u6-X19"}],"explanation":["줄거리만 옮겼어요.","마음을 헤아리지 않았어요.","마음을 헤아려 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#9','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C11',2,'mc','auto','「골목 끝 수선집」에서 달리기 대회 바로 전날이라는 때는 이야기에서 어떤 구실을 하나요?',ARRAY['K5-2-u6-X11']::text[],false,'{"seq":9,"concept":"K5-2-u6-C11","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」에서 달리기 대회 바로 전날이라는 때는 이야기에서 어떤 구실을 하나요?","options":[{"t":"서준이가 급하게 운동화를 고쳐야 하는 사건을 만든다","correct":true},{"t":"아무 구실도 하지 않는 장식이다","mis":"K5-2-u6-X11"},{"t":"할아버지의 이름을 알려 준다","mis":"K5-2-u6-X11"},{"t":"수선집이 있는 곳을 알려 준다","mis":"K5-2-u6-X11"}],"explanation":["배경은 장식이 아니에요.","이름과 관계없어요.","때가 사건을 만들어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#10','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C28',2,'mc','auto','「도서관의 마지막 손님」에서 두 인물의 관계가 어떻게 바뀌었는지 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u6-X28']::text[],false,'{"seq":10,"concept":"K5-2-u6-C28","difficulty":2,"kind":"mc","stem":"「도서관의 마지막 손님」에서 두 인물의 관계가 어떻게 바뀌었는지 알맞게 말한 것은 어느 것인가요?","options":[{"t":"문을 닫으려던 선생님이 지안이 곁에서 함께 이야기를 기다리는 사이가 되었다","correct":true},{"t":"처음부터 끝까지 서로 다투는 사이이다","mis":"K5-2-u6-X28"},{"t":"지안이가 선생님을 도서관에서 내보냈다","mis":"K5-2-u6-X28"},{"t":"두 사람은 서로 말을 나누지 않았다","mis":"K5-2-u6-X28"}],"explanation":["다투지 않았어요.","극본과 달라요.","관계가 가까워졌어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#11','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C42',2,'mc','auto','웃어른을 직접 높일 때 높임 어휘가 있으면 어떻게 하나요?',ARRAY['K5-2-u6-X42']::text[],false,'{"seq":11,"concept":"K5-2-u6-C42","difficulty":2,"kind":"mc","stem":"웃어른을 직접 높일 때 높임 어휘가 있으면 어떻게 하나요?","options":[{"t":"「-시-」만 붙이기보다 높임 어휘를 먼저 쓴다","correct":true},{"t":"높임 어휘는 쓰지 않고 「-시-」만 붙인다","mis":"K5-2-u6-X42"},{"t":"높임 어휘와 반말을 섞어 쓴다","mis":"K5-2-u6-X42"},{"t":"어른에게는 높임 표현을 쓰지 않아도 된다","mis":"K5-2-u6-X42"}],"explanation":["높임 어휘가 먼저예요.","높임을 섞지 않아요.","높임 어휘를 먼저 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#12','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C8',2,'match','auto','이야기 속 내용과 구성 요소를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K5-2-u6-C8","difficulty":2,"kind":"match","stem":"이야기 속 내용과 구성 요소를 알맞게 이으세요.","pairs":[{"l":"전쟁을 피해 피란을 온 때","r":"시대적 배경"},{"l":"산비탈에 친 천막 교실","r":"공간적 배경"},{"l":"순덕이가 연필을 반으로 나누어 준 일","r":"사건"}],"mis":"K5-2-u6-X08","explanation":["어떤 시대인지예요.","어디인지예요.","일어난 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#13','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C19',2,'mc','auto','수선집 할아버지에게 쓰는 편지의 한 부분으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X19']::text[],false,'{"seq":13,"concept":"K5-2-u6-C19","difficulty":2,"kind":"mc","stem":"수선집 할아버지에게 쓰는 편지의 한 부분으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「밑창에 새겨 주신 글씨 덕분에 서준이가 다시 달릴 수 있었을 거예요. 말없이 건네신 마음이 따뜻했어요.」","correct":true},{"t":"「할아버지는 수선집에 계세요.」","mis":"K5-2-u6-X19"},{"t":"「운동화를 빨리 고치세요.」","mis":"K5-2-u6-X19"},{"t":"「겨울에는 눈이 와요.」","mis":"K5-2-u6-X19"}],"explanation":["사실만 적었어요.","마음을 헤아리지 않았어요.","겪은 일과 마음을 헤아렸어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#14','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C35',2,'mc','auto','「도서관의 마지막 손님」으로 연극을 할 때 준비할 소품으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X35']::text[],false,'{"seq":14,"concept":"K5-2-u6-C35","difficulty":2,"kind":"mc","stem":"「도서관의 마지막 손님」으로 연극을 할 때 준비할 소품으로 알맞은 것은 어느 것인가요?","options":[{"t":"열쇠 꾸러미, 책, 의자","correct":true},{"t":"북과 솔방울","mis":"K5-2-u6-X35"},{"t":"우체통과 편지","mis":"K5-2-u6-X35"},{"t":"나룻배와 노","mis":"K5-2-u6-X35"}],"explanation":["다른 극본이에요.","다른 극본이에요.","극본에 나오는 물건이에요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#15','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C26',2,'mc','auto','「도서관의 마지막 손님」 첫 장면을 상상한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X26']::text[],false,'{"seq":15,"concept":"K5-2-u6-C26","difficulty":2,"kind":"mc","stem":"「도서관의 마지막 손님」 첫 장면을 상상한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"비 내리는 저녁, 불이 하나둘 꺼진 도서관에 지안이가 남아 책을 읽고 있다","correct":true},{"t":"맑은 아침, 사람들로 붐비는 도서관","mis":"K5-2-u6-X26"},{"t":"눈 오는 날 우체국 앞","mis":"K5-2-u6-X26"},{"t":"운동장 축제 무대","mis":"K5-2-u6-X26"}],"explanation":["해설과 달라요.","다른 극본이에요.","해설대로 떠올렸어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#16','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C1',2,'mc','auto','「골목 끝 수선집」을 깊이 있게 감상한 친구의 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X01']::text[],false,'{"seq":16,"concept":"K5-2-u6-C1","difficulty":2,"kind":"mc","stem":"「골목 끝 수선집」을 깊이 있게 감상한 친구의 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「눈 내리는 시장 골목, 말없는 할아버지, 밑창의 글씨가 함께 어우러져 마음이 따뜻해져.」","correct":true},{"t":"「운동화를 고친 이야기야. 끝.」","mis":"K5-2-u6-X01"},{"t":"「등장인물이 둘이야.」","mis":"K5-2-u6-X01"},{"t":"「제목이 다섯 글자야.」","mis":"K5-2-u6-X01"}],"explanation":["줄거리만 말했어요.","감상이 아니에요.","때·곳·인물을 함께 살폈어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#17','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C15',3,'mc','auto','할아버지가 고개만 한 번 끄덕인 장면과 밑창의 글씨를 함께 보고 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u6-X15']::text[],false,'{"seq":17,"concept":"K5-2-u6-C15","difficulty":3,"kind":"mc","stem":"할아버지가 고개만 한 번 끄덕인 장면과 밑창의 글씨를 함께 보고 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"말은 아꼈지만 서준이를 응원하는 마음이 깊었다","correct":true},{"t":"귀찮아서 대충 고쳐 주었다","mis":"K5-2-u6-X15"},{"t":"말이 없으니 마음도 없었다","mis":"K5-2-u6-X15"},{"t":"서준이를 처음 본 척했다","mis":"K5-2-u6-X15"}],"explanation":["글씨와 맞지 않아요.","행동에 마음이 있어요.","말과 행동을 함께 보았어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#18','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C29',3,'mc','auto','「도서관의 마지막 손님」에서 흐름을 바꾼 순간은 어느 것인가요?',ARRAY['K5-2-u6-X29']::text[],false,'{"seq":18,"concept":"K5-2-u6-C29","difficulty":3,"kind":"mc","stem":"「도서관의 마지막 손님」에서 흐름을 바꾼 순간은 어느 것인가요?","options":[{"t":"선생님이 의자를 끌어와 앉으며 함께 기다리겠다고 한 때","correct":true},{"t":"창문에 빗방울이 맺힌 때","mis":"K5-2-u6-X29"},{"t":"선생님이 열쇠 꾸러미를 흔든 때","mis":"K5-2-u6-X29"},{"t":"불빛이 하나둘 꺼진 때","mis":"K5-2-u6-X29"}],"explanation":["배경이에요.","흐름이 바뀌기 전이에요.","문을 닫으려던 흐름이 바뀌었어요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#19','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C42',3,'mc','auto','높임 표현을 배우며 함께 지녀야 할 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X43','K5-2-u6-X42']::text[],false,'{"seq":19,"concept":"K5-2-u6-C42","difficulty":3,"kind":"mc","stem":"높임 표현을 배우며 함께 지녀야 할 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"높이는 방법뿐 아니라 어른을 존중하는 마음으로 말하는 것","correct":true},{"t":"높임을 많이 붙일수록 무조건 좋다는 생각","mis":"K5-2-u6-X43"},{"t":"높임 표현은 시험 볼 때만 쓰면 된다는 생각","mis":"K5-2-u6-X42"},{"t":"어른의 말씀에는 대답하지 않아도 된다는 생각","mis":"K5-2-u6-X42"}],"explanation":["알맞게 높여요.","늘 써요.","존중하는 마음이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#20','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C41',3,'mc','auto','독자 극장 활동으로 「골목 끝 수선집」을 감상하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X41']::text[],false,'{"seq":20,"concept":"K5-2-u6-C41","difficulty":3,"kind":"mc","stem":"독자 극장 활동으로 「골목 끝 수선집」을 감상하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"이야기를 대본처럼 나누어 인물의 마음을 살려 낭독한다","correct":true},{"t":"이야기를 읽지 않고 그림만 본다","mis":"K5-2-u6-X41"},{"t":"줄거리를 한 줄로 외운다","mis":"K5-2-u6-X41"},{"t":"혼자 소리 없이 빠르게 읽는다","mis":"K5-2-u6-X41"}],"explanation":["감상이 아니에요.","외우기가 아니에요.","나누어 낭독하는 활동이에요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#21','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C35',3,'mc','auto','마지막 연습에서 흐름이 어색한 곳을 찾았을 때 알맞은 일은 어느 것인가요?',ARRAY['K5-2-u6-X35','K5-2-u6-X37']::text[],false,'{"seq":21,"concept":"K5-2-u6-C35","difficulty":3,"kind":"mc","stem":"마지막 연습에서 흐름이 어색한 곳을 찾았을 때 알맞은 일은 어느 것인가요?","options":[{"t":"모둠이 함께 그 장면을 다시 읽고 이어지는 대사와 움직임을 맞춘다","correct":true},{"t":"그대로 두고 공연한다","mis":"K5-2-u6-X35"},{"t":"그 장면을 혼자 빼 버린다","mis":"K5-2-u6-X35"},{"t":"어색함을 만든 친구를 탓한다","mis":"K5-2-u6-X37"}],"explanation":["점검한 뜻이 없어요.","함께 고쳐요.","함께 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#22','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C32',3,'mc','auto','「빗속의 숲속 음악회」에서 「(솔방울 두 개를 들고 앞으로 나서며)」를 인상적인 부분으로 고른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u6-X32']::text[],false,'{"seq":22,"concept":"K5-2-u6-C32","difficulty":3,"kind":"mc","stem":"「빗속의 숲속 음악회」에서 「(솔방울 두 개를 들고 앞으로 나서며)」를 인상적인 부분으로 고른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"북을 치지 말라는 말을 들었던 가시가 위기에서 먼저 나서는 용기가 행동으로 드러나서","correct":true},{"t":"솔방울이 두 개라서","mis":"K5-2-u6-X32"},{"t":"지문이 길어서","mis":"K5-2-u6-X32"},{"t":"가시가 고슴도치라서","mis":"K5-2-u6-X32"}],"explanation":["까닭이 감상과 멀어요.","까닭이 감상과 멀어요.","인물의 마음과 행동을 근거로 들었어요."],"asset":{"type":"passage","lines":["때: 단풍 든 가을 오후 · 곳: 숲속 빈터의 나무 무대","나오는 인물: 고슴도치 가시, 다람쥐 토리, 너구리 뭉치, 부엉이 선생님","뭉치: (북을 끌어안으며) 가시야, 넌 북 치지 마. 네 가시에 북이 찢어지면 끝이야!","토리: (가시를 따라가 어깨를 토닥이며) 솔방울 두드리는 네 장단, 나는 정말 좋던데.","(하늘이 어두워지고 빗방울이 후드득 떨어진다. 북이 흠뻑 젖는다.)","부엉이 선생님: (젖은 북을 두드려 보고) 소리가 안 나는구나. 음악회는 어렵겠다.","가시: (솔방울 두 개를 들고 앞으로 나서며) 선생님, 제가 해 볼게요! 딱, 딱따구르르!","뭉치: (얼굴이 빨개져서) 가시야, 아까는 미안해. 네 장단에 맞춰 내가 노래할게!"],"title":"극본 「빗속의 숲속 음악회」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#23','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C39',4,'essay','teacher','「골목 끝 수선집」을 읽고 인물, 사건, 배경에 대한 감상 질문을 하나씩 만들고, 그 가운데 하나에 근거를 들어 답하세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u6-C39","difficulty":4,"kind":"essay","stem":"「골목 끝 수선집」을 읽고 인물, 사건, 배경에 대한 감상 질문을 하나씩 만들고, 그 가운데 하나에 근거를 들어 답하세요.","answer_guide":{"answer":"예: 인물 — 할아버지는 왜 말 대신 글씨로 마음을 전했을까? 사건 — 수선집 유리문에 붙은 운동화 그림은 어떤 의미일까? 배경 — 눈 내리는 겨울 골목이라는 배경은 어떤 느낌을 줄까? 답 — 유리문의 운동화 그림은 서준이의 고마운 마음이다. 서준이도 말 대신 그림으로 할아버지에게 마음을 돌려준 것 같다.","scoring_points":["세 요소의 질문을 만들었는가","하나에 답했는가","근거를 들었는가"]},"explanation":["질문을 만들어요.","답해요.","근거를 들어요."],"asset":{"type":"passage","lines":["눈이 펑펑 내리던 겨울, 시장 골목 끝에는 작은 신발 수선집이 있었어요.","수선집 할아버지는 늘 안경을 코끝에 걸치고 말없이 바늘을 놀렸어요.","어느 날, 서준이가 밑창이 떨어진 운동화를 들고 쭈뼛쭈뼛 들어섰어요.","「내일 달리기 대회인데……. 돈은 다음에 꼭 드릴게요.」","할아버지는 운동화를 이리저리 돌려 보더니 고개만 한 번 끄덕였어요.","다음 날 아침, 운동화 밑창에는 작은 글씨로 「끝까지」라고 새겨져 있었어요.","서준이는 마지막 바퀴에서 넘어질 뻔했지만, 밑창의 글씨를 떠올리며 다시 달렸어요.","그날 저녁, 수선집 유리문에는 서준이가 그린 운동화 그림이 붙어 있었어요."],"title":"골목 끝 수선집"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#24','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C33',4,'essay','teacher','「도서관의 마지막 손님」으로 모둠 연극을 준비하는 차례를 쓰고, 각 차례에서 우리 모둠이 할 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u6-C33","difficulty":4,"kind":"essay","stem":"「도서관의 마지막 손님」으로 모둠 연극을 준비하는 차례를 쓰고, 각 차례에서 우리 모둠이 할 일을 쓰세요.","answer_guide":{"answer":"예: 장면 정하기 — 지안이가 한 장만 더 읽게 해 달라고 부탁하는 장면을 고른다. 역할 정하기 — 인물의 특징을 살펴 지안, 사서 선생님, 해설을 나눈다. 소품 준비하기 — 열쇠 꾸러미, 책, 의자를 챙긴다. 연습하기 — 지문을 살려 두 번 이상 연습한다. 점검하기 — 소품과 등장 순서, 어색한 흐름을 확인한다.","scoring_points":["차례를 바르게 썼는가","차례마다 할 일을 썼는가","극본에 맞는 할 일인가"]},"explanation":["차례를 써요.","할 일을 써요.","극본에 맞춰요."],"asset":{"type":"passage","lines":["때: 비 오는 토요일 저녁 · 곳: 동네 작은 도서관 · 나오는 인물: 지안, 사서 선생님","책장 사이로 불빛이 하나둘 꺼지고, 창문에 빗방울이 맺혀 있다.","사서 선생님: (열쇠 꾸러미를 흔들며) 지안아, 이제 문 닫을 시간이란다.","지안: (책을 품에 꼭 안으며) 딱 한 장만 더 읽으면 안 돼요? 주인공이 곧 집에 돌아가거든요.","사서 선생님: (잠시 지안을 바라보다가 의자를 끌어와 앉으며) 그럼 나도 같이 기다릴게.","지안: (눈을 동그랗게 뜨고) 정말요? (책장을 넘기며 작은 소리로 읽기 시작한다.)"],"title":"극본 「도서관의 마지막 손님」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u6_review_d#25','kor',5,2,'u6','','g5_2_kor_u6_review_d','unit_review','K5-2-u6-C12',4,'essay','teacher','이 단원에서 배운 이야기의 구성 요소와 극본의 구성 요소를 각각 쓰고, 구성 요소를 생각하며 감상하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u6-C12","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 이야기의 구성 요소와 극본의 구성 요소를 각각 쓰고, 구성 요소를 생각하며 감상하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 이야기의 구성 요소는 인물, 사건, 배경이고, 극본의 구성 요소는 해설, 대사, 지문이다. 구성 요소를 생각하며 감상하면 인물의 마음과 사건의 흐름, 배경이 준 영향까지 살필 수 있어 작품을 깊이 이해할 수 있다.","scoring_points":["이야기의 구성 요소를 썼는가","극본의 구성 요소를 썼는가","좋은 점을 썼는가"]},"explanation":["셋을 써요.","셋을 써요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
